import { useModalOnClose } from '@gsm-app/hooks/useModalOnClose';
import type { AnyIconProps } from '@hawkins/assets';
import { Button, ButtonGroup, Heading, Modal, ModalBody, ModalFooter, ModalHeader } from '@hawkins/components';
import type { ComponentType, ReactNode } from 'react';

function isFunction<T>(method: T | Function): method is Function {
    return typeof method === 'function';
}

interface ConfirmModalProps {
    onClose: () => void;
    onConfirm: () => void;
    modalData?: {
        title: string;
        body: (() => ReactNode) | ReactNode;
        icon?: false | ComponentType<AnyIconProps> | undefined;
        closeLabel?: string;
        confirmLabel?: string;
        confirmVariant?:
            | 'icon'
            | 'secondary'
            | 'icon-color'
            | 'icon-reverse'
            | 'primary'
            | 'primary-destructive'
            | 'tertiary'
            | 'tertiary-color'
            | 'tertiary-reverse'
            | undefined;
    };
}

export const ConfirmModal = (props: ConfirmModalProps) => {
    const {
        onClose,
        modalData: { title, body, closeLabel = '', confirmLabel = '', confirmVariant } = {},
        onConfirm,
    } = props;

    const handleOnClose = useModalOnClose({ onClose });

    const bodyElement = body === undefined || isFunction<ReactNode>(body) ? body : () => body;
    return (
        <Modal open style={{ width: '600px' }} maxWidth='medium' onClose={handleOnClose}>
            <ModalHeader>
                <Heading level={0}>{title}</Heading>
            </ModalHeader>
            {bodyElement && <ModalBody>{bodyElement()}</ModalBody>}
            <ModalFooter>
                <ButtonGroup justifyContent='flex-end'>
                    <Button variant='secondary' onClick={onClose}>
                        {closeLabel ? closeLabel : 'Cancel'}
                    </Button>
                    <Button
                        variant={confirmVariant}
                        onClick={() => {
                            onConfirm();
                            onClose();
                        }}
                    >
                        {confirmLabel ? confirmLabel : 'Ok'}
                    </Button>
                </ButtonGroup>
            </ModalFooter>
        </Modal>
    );
};
