import type { GameVisibility } from '@netflix-internal/nf-game-control-protocol';
import { loggerManager } from '../common';
import { EventEmitter } from '../common/EventEmitter';
import type { CgAppliance, CgControllerFeatures } from '../graphql_generated/schema';
import type { Streamer } from '../streamer';
import { GameControl, type GameControlEventsTypeMap } from './GameControl';
import { RTCService, type RTCServiceEventsTypeMap, type DataChannelLabel } from './RTCService';

export class Transport extends EventEmitter<TransportEventsTypeMap> {
    private readonly rtcService = new RTCService();
    private readonly gameControl = new GameControl(this.rtcService);
    private readonly log = loggerManager.getLogger('Transport');
    private connectedAppliance_: CgAppliance | undefined;

    public constructor() {
        super();
        this.forwardEvents(this.gameControl, [
            'clientlist',
            'gamecontrolconnectionestablished',
            'requestedstream',
            'sentsdpoffer',
            'receivedsdpanswer',
            'ocgaloadprogress',
            'inputactive',
            'inputidlewarning',
            'connectionmetrics',
        ]);

        this.forwardEvents(this.rtcService, [
            'track',
            'gameconnecting',
            'gameconnected',
            'gamedisconnected',
            'gameconnectionclosed',
            'datachannelopened',
        ]);
    }

    public async connect(
        gameAppliance: CgAppliance,
        controllerFeatures: CgControllerFeatures | undefined,
        streamer: Streamer,
    ): Promise<void> {
        const startTime = Date.now();
        await this.gameControl.connect(gameAppliance, controllerFeatures, streamer);
        const elapsedMs = Date.now() - startTime;
        const elapsedSec = (elapsedMs / 1000).toFixed(2);
        this.log.debug(`connect_and_first_frame=${elapsedSec}s (${elapsedMs}ms)`);
        this.connectedAppliance_ = gameAppliance;
    }

    public setGameVisibility(visibility: GameVisibility) {
        return this.gameControl.setGameVisibility(visibility);
    }

    public async setClientLimit(max: number): Promise<void> {
        return this.gameControl.setClientLimit(max);
    }

    /**
     * Return stats about current webRTC connection
     * @returns {RTCStatsReport} peer connection stats
     */
    public async getRTCStats(): Promise<RTCStatsReport> {
        return this.rtcService.getStats();
    }

    public getReceiverId(): string {
        return this.gameControl.getReceiverId();
    }

    public getConnectionState(): RTCPeerConnectionState {
        return this.rtcService.getConnectionState();
    }

    public sendData(channel: DataChannelLabel, data: ArrayBuffer | string): void {
        this.rtcService.sendData(channel, data);
    }

    public onDataMessage(channel: DataChannelLabel, callback: (data: ArrayBuffer) => void): void {
        this.rtcService.onDataMessage(channel, callback);
    }

    public get connectedAppliance(): CgAppliance | undefined {
        return this.connectedAppliance_;
    }

    public async close(): Promise<void> {
        this.log.trace('close');
        this.connectedAppliance_ = undefined;
        await this.gameControl.close();
    }
}

export type TransportEventsTypeMap = GameControlEventsTypeMap & RTCServiceEventsTypeMap;
