import { createError } from '@gsm-common/utils/toast/createError';
import { useQuery } from '@tanstack/react-query';
import { useEffect } from 'react';

export type PlayerBlob = {
    name: string;
    revision: string;
};

export type PlayerBlobsResponse = {
    data: {
        items: PlayerBlob[];
        total_items: number;
    };
};

const fetchPlayerBlobs = async (pat: string | undefined): Promise<PlayerBlobsResponse | undefined> => {
    if (!pat) {
        return Promise.resolve(undefined);
    }
    const response = await fetch('/api/playerblobs', {
        headers: {
            pat,
            'Content-Type': 'application/json',
        },
    });

    if (!response.ok) {
        const errorData = await response.text();
        throw new Error(`Fetch failed with status ${response.status}: ${errorData}`);
    }
    return response.json() as Promise<PlayerBlobsResponse>;
};

export function usePATPlayerBlobs(pat: string | undefined) {
    const query = useQuery({
        queryKey: ['playerblobs', pat],
        queryFn: () => fetchPlayerBlobs(pat),
        enabled: Boolean(pat),
        gcTime: 1_000,
    });

    const { error, isError} = query;
    useEffect(() => {
        if (isError) {
            createError({
                title: 'Error Getting Player Blobs',
                body: `${error?.message}`,
                options: {
                    id: 'playerblobs',
                },
            });
        }
    }, [error, isError, createError]);

    return query;
}
