import { BuildState } from '@gsm-app/models/BuildState';
import type { Channel } from '@gsm-app/models/Channel';
import type { DropdownOption } from '@hawkins/components';
import { useMemo } from 'react';

export const createChannelOption = (ch: Channel): DropdownOption<string> & { buildId?: string } => {
    return {
        label: ch.name,
        value: ch.id,
        subtitle: ch?.activeBuild?.label ?? 'N/A',
        group: ch?.activeBuild?.state === BuildState.INSTALL_SUCCEED ? 'Playable' : 'Upload required',
        buildId: ch?.activeBuild?.id,
    };
};

export const useChannelOptions = (channels: Channel[] | undefined) => {
    return useMemo<DropdownOption<string>[]>(() => {
        if (!channels) {
            return [];
        }
        return channels.map((ch) => createChannelOption(ch)).sort((a, b) => a.label.localeCompare(b.label));
    }, [channels]);
};
