import { UserAuthentication, type MeechumUserData } from '@hawkins-community/user-authentication';

export const auth = UserAuthentication;
export const initAuth = () => {
    return auth.initialize<MeechumUserData>();
};

export class AuthenticationError extends Error {
    constructor(message = 'Authentication failed.') {
        super(message);
        this.name = this.constructor.name;
    }
}

export const isAuthzStatus = (status: unknown): status is 401 | 403 => status === 401 || status === 403;

export const createAuthzError = (status: number, message = 'You do not have access to this game.') => {
    const error = new Error(message);
    return Object.assign(error, { status });
};

export const isAuthzError = (error: unknown) => {
    // Prefer structured errors when available
    if (typeof error === 'object' && error) {
        const maybeStatus = (error as { status?: unknown }).status;
        if (isAuthzStatus(maybeStatus)) {
            return true;
        }
    }

    // Many queryFns in this codebase throw `Error("Fetch failed with status 403: ...")`
    if (error instanceof Error) {
        return /status\s+(401|403)\b/i.test(error.message);
    }

    return false;
};
