import { assert, loggerManager } from '../common';
import { EventEmitter } from '../common/EventEmitter';
import { ConfigManager } from '../config';
import type { Transport } from '../transport';
import { PlaybackStatusReporter } from './PlaybackStatusReporter';
import { GameVisibility } from '@netflix-internal/nf-game-control-protocol';

enum StreamerState {
    init = 0,
    playing = 1,
    frozen = 2,
    background = 3,
}

export class Streamer extends EventEmitter<StreamerEventsTypeMap> {
    private audioElement: HTMLAudioElement | undefined;
    private videoElement: HTMLVideoElement | undefined;
    private parentElement: HTMLElement | undefined;
    private readonly log = loggerManager.getLogger('Streamer');
    private readonly playbackStatusReporter: PlaybackStatusReporter;
    private useAudioElement = false;
    private isBackground = false;
    private streamerState = StreamerState.init;
    private rvfcMonitorId = 0;
    private rvfcMonitorFrozenId = 0;
    private rvfcMonitorFirstFrameId = 0;
    private videoFrameTimestamp: number | undefined;
    // biome-ignore lint/suspicious/noExplicitAny: DOM event listeners are heterogeneous
    private readonly videoListeners: Record<string, any> = {};

    public constructor(private readonly transport: Transport) {
        super();
        this.transport.addEventListener('track', (evt: RTCTrackEvent) => {
            const streamLabels = evt.streams
                .map((s) => {
                    if (s.id === 'stream0') return 'video';
                    if (s.id === 'stream1') return 'audio';
                    return s.id;
                })
                .join(',');
            this.log.debug(`track(${streamLabels})`);
            this.setStream(evt.streams[0]);
        });
        this.playbackStatusReporter = new PlaybackStatusReporter(this.transport);
    }

    public init(parentElement: HTMLElement = globalThis.document.body): void {
        this.useAudioElement = false;
        if (this.videoElement) {
            this.log.warn('Video element has already been created');
            return;
        }

        this.log.debug('Creating video element');
        this.parentElement = parentElement;
        this.videoElement = globalThis.document.createElement('video');
        this.videoElement.autoplay = true;
        this.parentElement.appendChild(this.videoElement);

        this.log.debug('Creating audio element');
        this.audioElement = globalThis.document.createElement('audio');
        this.audioElement.autoplay = true;
        this.parentElement.appendChild(this.audioElement);
    }

    public startMonitor() {
        const video = this.videoElement;
        assert(video, 'videoElement is undefined');

        // Send 'firstframe' event in first requestVideoFrameCallback
        // requestVideoFrameCallback is not yet an offical HTML standard
        // https://wicg.github.io/video-rvfc/
        this.rvfcMonitorFirstFrameId = video.requestVideoFrameCallback?.(() => {
            this.log.debug('firstframe');
            this.emitEvent('firstframe', { type: 'firstframe', target: video });
        });

        // The 'play' event triggers UI to go into Fullscreen and must be initiated by a user gesture
        // Ideally this event would be fired when videoElement emits 'playing', but that's not a user gesture
        // It seems as though this is allowed in the case of videoElement.play (when autoplay is allowed)
        this.videoListeners.play = () => this.emitEvent('play', { type: 'play', target: video });
        video.addEventListener('play', this.videoListeners.play);
        this.videoListeners.playing = () => {
            // TODO: remove delay to avoid pink flash OCGA encoder bug
            setTimeout(() => this.emitEvent('playing', { type: 'playing', target: video }), 84);
        };
        video.addEventListener('playing', this.videoListeners.playing);

        this.playbackStatusReporter.init();
        this.videoFrameTimestamp = undefined;
        this.streamerState = StreamerState.init;
        const rvfc = (now: DOMHighResTimeStamp, metadata: VideoFrameCallbackMetadata) => {
            this.rvfcMonitorId = video.requestVideoFrameCallback(rvfc);
            this.playbackStatusReporter.report(metadata);
            const previousTimestamp = this.videoFrameTimestamp;
            this.videoFrameTimestamp = now;

            if (this.isBackground) {
                return;
            }

            if (this.streamerState === StreamerState.frozen) {
                if (this.streamerState === StreamerState.frozen && previousTimestamp) {
                    const interval = now - previousTimestamp;
                    const intervalMs = Math.round(interval);
                    const intervalSec = (intervalMs / 1000).toFixed(2);
                    this.log.debug(`stalled=${intervalSec}s (${intervalMs}ms)`);
                }
            }

            if (this.streamerState !== StreamerState.playing) {
                this.streamerState = StreamerState.playing;
                this.emitEvent('playing', { type: 'playing', target: this.videoElement });
            }

            this.startOrResetFrozenTimer();
        };
        this.rvfcMonitorId = video.requestVideoFrameCallback?.(rvfc);
    }

    public stopMonitor() {
        const video = this.videoElement;
        assert(video, 'videoElement is undefined');
        video.srcObject = null;
        video.cancelVideoFrameCallback(this.rvfcMonitorFirstFrameId);
        video.cancelVideoFrameCallback(this.rvfcMonitorId);
        video.removeEventListener('play', this.videoListeners.play);
        video.removeEventListener('playing', this.videoListeners.playing);
    }

    public setGameVisibility(visibility: GameVisibility) {
        const wasBackground = this.isBackground;
        this.isBackground = visibility === GameVisibility.NOT_VISIBLE;
        this.log.debug(`setGameVisibility: ${visibility} : ${this.isBackground}`);

        if (this.isBackground !== wasBackground) {
            if (this.isBackground) {
                this.stopFrozenTimer();
                this.streamerState = StreamerState.background;
                this.emitEvent('background', { type: 'background' });
            } else {
                this.startOrResetFrozenTimer();
            }
        }
    }

    private startOrResetFrozenTimer() {
        clearTimeout(this.rvfcMonitorFrozenId);
        this.rvfcMonitorFrozenId = window.setTimeout(() => {
            this.rvfcMonitorFrozenId = window.setTimeout(() => {}, 0);
            this.streamerState = StreamerState.frozen;
            this.emitEvent('frozen', { type: 'frozen', target: this.videoElement });
        }, ConfigManager.getConfig().frozenTimeout);
    }

    private stopFrozenTimer() {
        clearTimeout(this.rvfcMonitorFrozenId);
        this.rvfcMonitorFrozenId = window.setTimeout(() => {}, 0);
    }

    public getTargetForMouseEvents(): EventTarget {
        return this.videoElement ?? globalThis.document;
    }

    public getTargetForKeyboardEvents(): EventTarget {
        return globalThis.document;
    }

    public getVideoPlaybackQuality(): string {
        const quality = this.videoElement?.getVideoPlaybackQuality();
        return JSON.stringify(quality, ['creationTime', 'droppedVideoFrames', 'totalVideoFrames']);
    }

    public close(): void {
        this.log.trace('close');
        this.stopFrozenTimer();

        if (this.audioElement) {
            this.log.debug('Destroying audio element');
            this.parentElement?.removeChild(this.audioElement);
            this.audioElement.srcObject = null;
            this.audioElement = undefined;
        }

        if (this.videoElement) {
            this.stopMonitor();
            this.log.debug('Destroying video element');
            this.parentElement?.removeChild(this.videoElement);
            if (ConfigManager.getConfig().reportVideoFrameMetrics) {
                this.playbackStatusReporter.close();
            }
            this.videoElement.srcObject = null;
            this.videoElement = undefined;
        }
    }

    public async play(): Promise<void> {
        try {
            assert(this.audioElement);
            assert(this.videoElement);
            if (this.useAudioElement) {
                await this.audioElement.play();
            }
            await this.videoElement.play();
            this.log.trace('Playback started');
        } catch (e: unknown) {
            const err = e as { name?: string };
            if (err?.name === 'NotAllowedError') {
                this.log.warn('Autoplay blocked', e);
                this.emitEvent('autoplayblocked', { type: 'autoplayblocked', target: this.videoElement });
            } else if (err?.name === 'AbortError') {
                this.log.error('Aborted playback before it could start');
            } else {
                this.log.error(`videoElement.play failed: ${String(e)}`);
            }
        }
    }

    private async setStream(mediaStream: MediaStream): Promise<void> {
        assert(this.videoElement);
        assert(this.audioElement);

        switch (mediaStream.id) {
            case 'stream0':
                this.videoElement.srcObject = mediaStream;
                break;
            case 'stream1':
                this.useAudioElement = true;
                this.audioElement.srcObject = mediaStream;
                break;
            default:
                throw new Error(`Unexpected mediaStream: ${mediaStream.id}`);
        }
        if (this.videoElement.srcObject === mediaStream) {
            this.log.trace('srcObject already set to this MediaStream');
            return;
        }

        this.log.trace('Setting video mediastream');
        this.videoElement.srcObject = mediaStream;

        if (this.videoElement.paused) {
            this.log.trace('Starting playback');
            await this.play();
        } else {
            this.log.error('Tried to set media stream to video element while playing');
        }
    }
}

export type StreamerEventsTypeMap = {
    autoplayblocked: { type: 'autoplayblocked'; target?: HTMLVideoElement };
    firstframe: { type: 'firstframe'; target?: HTMLVideoElement };
    frozen: { type: 'frozen'; target?: HTMLVideoElement };
    play: { type: 'play'; target?: HTMLVideoElement };
    playing: { type: 'playing'; target?: HTMLVideoElement };
    background: { type: 'background'; target?: HTMLVideoElement };
};
