import { CLIENT_NAME } from '@gsm-app/constants';
import { mockFetch } from '@gsm-app/mocks/mockFetchHandlers';
import { isMockPlayMode } from '@gsm-app/mocks/mockPlayMode';
import crossFetch from 'cross-fetch';
import { auth } from './auth';

export const fetch = async (input: RequestInfo | URL, init?: RequestInit) => {
    // Local-only UI dev mode — skip the public-IP lookup and Hawkins auth token entirely (neither is
    // reachable/initialized without a real Netflix backend) and go straight to fixture data.
    if (isMockPlayMode) {
        return mockFetch(input, init);
    }

    const ip = await getPublicIP();
    return crossFetch(input, {
        ...init,
        headers: {
            ...init?.headers,
            'X-Ncgt-Client-Name': CLIENT_NAME,
            'X-Ncgt-Client-Version': navigator.userAgent,
            'X-Ncgt-Client-Ip': ip,
            authorization: `Bearer ${(await auth.getOrRefreshUser()).access.token}`,
        },
    });
};

async function getPublicIP() {
    const response = await crossFetch('https://api.ipify.org?format=json');
    const data = (await response.json()) as { ip: string };
    return data.ip;
}
