export const isJSON = (value: string | Blob): boolean => {
    if (typeof value === 'string') {
        // remove whitespace, extra quotes, escapes
        value = value
            .trim()
            .replace(/^"(.*)"$/, '$1')
            .replace(/\\"/g, '"');
        if (value.search(/^(\[|\{){1}/) > -1) {
            try {
                const obj = JSON.parse(value);
                return true;
            } catch {}
        }
    }
    return false;
};
