const drawCanvas = document.createElement('canvas');
drawCanvas.width = 100;
drawCanvas.height = drawCanvas.width * 0.75;

const createImage = (color: string = 'red') => {
    const img = document.createElement('img');
    img.width = drawCanvas.width;
    img.height = drawCanvas.height;
    const ctx = drawCanvas.getContext('2d');
    if (ctx) {
        const gradient = ctx.createLinearGradient(0, 0, img.width, img.height);
        gradient.addColorStop(0, color);
        gradient.addColorStop(1, Colors.Black);
        ctx.fillStyle = gradient;
        ctx.fillRect(0, 0, img.width, img.height);
    }
    img.src = drawCanvas.toDataURL('image/jpeg');
    return img;
};

const SCREENSHOTS_TAKEN = Math.floor(5000 / 500); // show screenshot every
export const SCREENSHOT_LOOKUP = [createImage(Colors.Amber), createImage(Colors.Indigo), createImage(Colors.Purple)];

const cpu = [1610, 4906, 12082, 13791, 21551, 8000];
const gpu = [2000, 3000, 9000, 16000, 15000, 8000];
const mem = [1000, 2000, 8000, 12000, 10000, 8000];

interface ExampleData {
    lineKey: string;
    value: number;
    date: number;
}

const createExampleData = (key: string, values: number[], offset: number = 1000) => {
    return values.map<ExampleData>((value, i) => ({
        lineKey: key,
        value,
        date: offset * i,
    }));
};

const points = [createExampleData('cpu', cpu), createExampleData('gpu', gpu), createExampleData('mem', mem)].flat();

export const statsData: DataConfig = {
    points,
    channels: {
        x: 'date',
        y: 'value',
        dataset: 'lineKey',
        color: 'lineKey',
        datasetTitle: d => String(d.lineKey).toUpperCase(),
    },
};

