import type { AnyIconProps } from '@hawkins/assets';
import { InlineFeedback, Stack, Text } from '@hawkins/components';
import { Colors, Dimensions, VariableUtils } from '@hawkins/variables';
import { type ComponentType, type ReactNode, isValidElement } from 'react';
import toast, { type Toast } from 'react-hot-toast';
import styles from './Toast.module.css';

type ToastOptions = Partial<
    Pick<Toast, 'id' | 'icon' | 'duration' | 'ariaProps' | 'className' | 'style' | 'position' | 'iconTheme'>
>;

function isFunction<T>(method: T | Function): method is Function {
    return typeof method === 'function';
}

function Title({ value }: { value: ((toast: Toast) => ReactNode) | ReactNode }) {
    if (value === undefined || isFunction<ReactNode>(value)) {
        return <>{value}</>;
    }

    if (isValidElement(value)) {
        return <>{value}</>;
    }

    return (
        <Text level={1} bold variant='body' style={{ color: 'inherit' }}>
            {value}
        </Text>
    );
}

export interface ToastProps {
    title: ((toast: Toast) => ReactNode) | ReactNode;
    body?: ((toast: Toast) => ReactNode) | ReactNode;
    footer?: ((toast: Toast) => ReactNode) | ReactNode;
    clickblock?: boolean;
    icon?: false | ComponentType<AnyIconProps> | undefined;
    dismissible?: boolean;
    showLoader?: boolean;
    options?: ToastOptions;
    variant?: 'error' | 'regular' | 'success' | 'warning';
}

export const createToast = ({
    title,
    body,
    clickblock,
    footer,
    dismissible,
    icon,
    variant,
    showLoader,
    options,
}: ToastProps) => {
    const bodyElement = body === undefined || isFunction<ReactNode>(body) ? body : () => body;
    const footerElement = footer === undefined || isFunction<ReactNode>(footer) ? footer : () => footer;

    toast.custom(
        (t) => (
            <>
                {clickblock && (
                    <div
                        className={styles.backdrop}
                        style={{
                            backgroundColor: VariableUtils.updateAlpha(Colors.Black, 0.5),
                        }}
                    ></div>
                )}
                <InlineFeedback
                    classes={{
                        container: styles.toasterMinWidth,
                        messageContainer: styles.toasterMessageContainer,
                    }}
                    onClose={() => toast.remove(t.id)}
                    dismissible={dismissible !== false}
                    aria-multiline={true}
                    icon={icon}
                    showLoader={showLoader}
                    variant={variant}
                    message={
                        <Stack gap={Dimensions.Space2}>
                            <Title value={title} />
                            {bodyElement && bodyElement(t)}
                        </Stack>
                    }
                >
                    {footerElement && footerElement(t)}
                </InlineFeedback>
            </>
        ),
        options,
    );
};
