import type { EnvVar } from '@ncgt/common/models/envVar';
import { mapSavedEnvVarsToModel } from '@ncgt/common/utils/envVar';
import { type PropsWithChildren, createContext, useCallback, useContext, useMemo, useState } from 'react';

interface EnvVariablesContextValue {
    envVariables: { [gameId: string]: EnvVar[] };
    setEnvVariables: (gameId: string, vars: EnvVar[]) => void;
    clearEnvVariables: (gameId: string) => void;
    getEnvVariablesForGame: (gameId: string) => EnvVar[];
}

const EnvVariablesContext = createContext<EnvVariablesContextValue>({} as EnvVariablesContextValue);

const ENV_VARS_STORAGE_KEY = 'ncgt_playSessionEnvVars';

export const EnvVariablesProvider = ({ children }: PropsWithChildren) => {
    const [envVariables, _setEnvVars] = useState<{ [gameId: string]: EnvVar[] }>(() => {
        try {
            const saved = localStorage.getItem(ENV_VARS_STORAGE_KEY);
            return saved ? mapSavedEnvVarsToModel(JSON.parse(saved)) : {};
        } catch {
            return {};
        }
    });

    const setEnvVariables = useCallback((gameId: string, vars: EnvVar[]) => {
        _setEnvVars((prev) => {
            const newVars = { ...prev, [gameId]: vars };
            try {
                localStorage.setItem(ENV_VARS_STORAGE_KEY, JSON.stringify(newVars));
            } catch (error) {
                console.warn('Failed to save environment variables to localStorage:', error);
            }
            return newVars;
        });
    }, []);

    const clearEnvVariablesForGame = useCallback((gameId: string) => {
        _setEnvVars((prev) => {
            const newVars = { ...prev };
            delete newVars[gameId];
            localStorage.setItem(ENV_VARS_STORAGE_KEY, JSON.stringify(newVars));
            return newVars;
        });
    }, []);

    const getEnvVariablesForGame = useCallback((gameId: string) => envVariables[gameId] ?? [], [envVariables]);

    const value = useMemo(
        () => ({ envVariables, setEnvVariables, clearEnvVariables: clearEnvVariablesForGame, getEnvVariablesForGame }),
        [envVariables, setEnvVariables, clearEnvVariablesForGame, getEnvVariablesForGame],
    );

    return <EnvVariablesContext.Provider value={value}>{children}</EnvVariablesContext.Provider>;
};

export const useEnvVariables = () => useContext(EnvVariablesContext);

export const useEnvVariablesForGame = (gameId: string | undefined): EnvVar[] => {
    const { envVariables } = useEnvVariables();

    return useMemo(() => {
        if (!gameId) return [];
        return envVariables[gameId] ?? [];
    }, [gameId, envVariables]);
};
