import { useMutation, useQueryClient } from '@tanstack/react-query';
import { CHANNELS_QUERY_KEY } from './useChannels';

export type Channel = {
    gameId: string;
    name: string;
    notes?: string;
    isPrivate?: boolean;
    platform?: string;
};

interface NewChannelResponse {
    data?: Channel;
    errors: any[];
}

async function createChannel(channel: Channel): Promise<NewChannelResponse> {
    const response = await fetch(`api/games/${channel.gameId}/channels`, {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
        },
        body: JSON.stringify(channel),
    });

    if (!response.ok) {
        const errorData = await response.text();
        throw new Error(errorData);
    }
    return response.json() as Promise<NewChannelResponse>;
}

export function useChannelCreate() {
    const queryClient = useQueryClient();

    return useMutation({
        mutationFn: createChannel,
        onSettled: () => {
            queryClient.invalidateQueries({ queryKey: [CHANNELS_QUERY_KEY] });
        },
    });
}
