import * as input from '@netflix-internal/game-input';
import { loggerManager } from '../common';
import type { InputDevice } from './InputDevice';
import { KeyMap } from './KeyMap';

// Maps a printable character to the physical key + shift state for US QWERTY layout.
const CHAR_KEY_MAP: ReadonlyMap<string, { keyCode: string; shift: boolean }> = (() => {
    const m = new Map<string, { keyCode: string; shift: boolean }>();
    for (const c of 'abcdefghijklmnopqrstuvwxyz') m.set(c, { keyCode: `Key${c.toUpperCase()}`, shift: false });
    for (const c of 'ABCDEFGHIJKLMNOPQRSTUVWXYZ') m.set(c, { keyCode: `Key${c}`, shift: true });
    for (const c of '0123456789') m.set(c, { keyCode: `Digit${c}`, shift: false });
    const shiftChars = new Set('!@#$%^&*()_+{}:"~|<>?');
    [
        ['!', 'Digit1'],
        ['@', 'Digit2'],
        ['#', 'Digit3'],
        ['$', 'Digit4'],
        ['%', 'Digit5'],
        ['^', 'Digit6'],
        ['&', 'Digit7'],
        ['*', 'Digit8'],
        ['(', 'Digit9'],
        [')', 'Digit0'],
        [' ', 'Space'],
        ['\n', 'Enter'],
        ['\t', 'Tab'],
        ['-', 'Minus'],
        ['_', 'Minus'],
        ['=', 'Equal'],
        ['+', 'Equal'],
        ['[', 'BracketLeft'],
        ['{', 'BracketLeft'],
        [']', 'BracketRight'],
        ['}', 'BracketRight'],
        [';', 'Semicolon'],
        [':', 'Semicolon'],
        ["'", 'Quote'],
        ['"', 'Quote'],
        ['`', 'Backquote'],
        ['~', 'Backquote'],
        ['\\', 'Backslash'],
        ['|', 'Backslash'],
        [',', 'Comma'],
        ['<', 'Comma'],
        ['.', 'Period'],
        ['>', 'Period'],
        ['/', 'Slash'],
        ['?', 'Slash'],
    ].forEach(([char, keyCode]) => m.set(char, { keyCode, shift: shiftChars.has(char) }));
    return m;
})();

export class KeyboardInput implements InputDevice {
    private readonly events: Array<keyof HTMLElementEventMap> = ['keyup', 'keydown'];
    private readonly log = loggerManager.getLogger('KeyboardInput');
    private readonly interceptedKeys: Array<KeyInterceptor> = [];
    private readonly device: input.Device;

    public constructor(private readonly eventsTarget: EventTarget) {
        this.device = input.Device.create(
            0,
            0,
            'Standard Keyboard',
            Object.values(KeyMap).map((keyCode) => new input.Key(keyCode)),
        );
        if (this.device.transport) {
            this.device.transport.logger = this.log;
        }
    }

    public start() {
        this.log.trace('Subscribing to keyboard events', this.events);
        this.events.forEach((keyEvent) => this.eventsTarget.addEventListener(keyEvent, this.handleKeyEvent));
    }

    public getInputDevice(): input.Device {
        return this.device;
    }

    public close() {
        this.typeActive = false;
        this.log.trace('Unsubscribing from keyboard events', this.events);
        this.events.forEach((keyEvent) => this.eventsTarget.removeEventListener(keyEvent, this.handleKeyEvent));
    }

    public readonly handleKeyEvent = (e: Event) => {
        const keyEvent = e as KeyboardEvent;
        if (
            (keyEvent.target as Element)?.tagName !== 'INPUT' &&
            !keyEvent.ctrlKey &&
            !keyEvent.altKey &&
            !keyEvent.metaKey &&
            keyEvent.code !== 'Escape'
        ) {
            e.preventDefault();
        }
        // Paste shortcuts are handled by the document paste event — don't forward to game
        if ((keyEvent.ctrlKey || keyEvent.metaKey) && keyEvent.code === 'KeyV') {
            return;
        }
        const isKeyPressed = keyEvent.type === 'keydown';
        if (isKeyPressed) {
            const interceptors = this.interceptedKeys.filter((interceptor) =>
                this.matchesKeyboardEvent(interceptor, keyEvent),
            );
            if (interceptors.length > 0) {
                interceptors.forEach((interceptor) => interceptor.callback(keyEvent));
                return;
            }
        }

        this.device.setKey(KeyMap[keyEvent.code], isKeyPressed);
        this.device.pushStates();
    };

    private matchesKeyboardEvent(interceptor: KeyInterceptor, keyEvent: KeyboardEvent) {
        return (
            interceptor.keyCode === keyEvent.code &&
            !!interceptor.modifiers?.alt === keyEvent.altKey &&
            !!interceptor.modifiers?.ctrl === keyEvent.ctrlKey &&
            !!interceptor.modifiers?.meta === keyEvent.metaKey &&
            !!interceptor.modifiers?.shift === keyEvent.shiftKey
        );
    }

    public subscribeToKeyPress(
        keyCode: string,
        modifiers: KeyPressEventModifiers,
        callback: (e: KeyboardEvent) => void,
    ) {
        this.interceptedKeys.push({ keyCode, modifiers, callback });
    }

    private typeActive = false;
    private static readonly MAX_PASTE_LENGTH = 1_000;
    // Printable ASCII plus newline and tab (which map to Enter/Tab). Strips other control chars, emojis, non-ASCII.
    private static readonly PRINTABLE_ASCII_PATTERN = /[^\x20-\x7E\n\t]/g;

    public async typeText(text: string, charDelayMs: number): Promise<void> {
        if (this.typeActive) return;
        this.typeActive = true;
        const sanitized = text.replace(KeyboardInput.PRINTABLE_ASCII_PATTERN, '');
        if (sanitized.length < text.length) {
            this.log.warn(`typeText: stripped ${text.length - sanitized.length} unsupported character(s)`);
        }
        const safeText =
            sanitized.length > KeyboardInput.MAX_PASTE_LENGTH
                ? sanitized.slice(0, KeyboardInput.MAX_PASTE_LENGTH)
                : sanitized;
        if (safeText.length < sanitized.length) {
            this.log.warn(
                `typeText: truncated input from ${sanitized.length} to ${KeyboardInput.MAX_PASTE_LENGTH} characters`,
            );
        }
        // Ctrl/Meta may still be physically held from the Ctrl+V / Cmd+V that triggered paste.
        // Release them so the game doesn't receive Ctrl+char or Meta+char combos.
        ['ControlLeft', 'ControlRight', 'MetaLeft', 'MetaRight'].forEach((mod) => {
            const code = KeyMap[mod];
            if (code !== undefined) this.device.setKey(code, false);
        });
        this.device.pushStates();
        let shiftHeld = false;
        try {
            for (const char of safeText) {
                if (!this.typeActive) break;
                const entry = CHAR_KEY_MAP.get(char);
                if (!entry) continue;
                const code = KeyMap[entry.keyCode];
                if (code === undefined) continue;

                if (entry.shift !== shiftHeld) {
                    this.device.setKey(KeyMap['ShiftLeft'], entry.shift);
                    this.device.pushStates();
                    shiftHeld = entry.shift;
                }

                this.device.setKey(code, true);
                this.device.pushStates();
                this.device.setKey(code, false);
                this.device.pushStates();

                await new Promise<void>((resolve) => setTimeout(resolve, charDelayMs));
            }
        } finally {
            if (shiftHeld) {
                this.device.setKey(KeyMap['ShiftLeft'], false);
                this.device.pushStates();
            }
            this.typeActive = false;
        }
    }
}

export type KeyPressEventModifiers = {
    ctrl?: boolean;
    shift?: boolean;
    alt?: boolean;
    meta?: boolean;
};

export type KeyInterceptor = {
    keyCode: string;
    modifiers: KeyPressEventModifiers;
    callback: (e: KeyboardEvent) => void;
};
