import '@netflix-internal/react-vizkit/main.css';
import { IdentityProvider } from '@gsm-app/providers/IdentityProvider';
import { UploadProvider } from '@gsm-app/providers/UploadProvider';
import { EnvVariablesProvider } from '@gsm-app/providers/EnvVariablesProvider';
import { OcgaHardwareVersionsPrefetch } from '@gsm-app/components/OcgaHardwareVersionsPrefetch/OcgaHardwareVersionsPrefetch';
import { router } from '@gsm-app/routes/createRouter';
import { fetch } from '@gsm-app/utils/fetch';
import { ClientLoader } from '@ncgt/player';
import { SessionTimelinePanelProvider } from '@ncgt/session-timeline';
import { queryClient } from '@gsm-app/queryClient';
import { QueryClientProvider } from '@tanstack/react-query';
import { RouterProvider } from 'react-router-dom';
import { Toaster } from 'react-hot-toast';
import { MaintenanceMode } from '../MaintenanceMode/MaintenanceMode';

export const App = () => {
    return (
        <QueryClientProvider client={queryClient}>
            <MaintenanceMode>
                <IdentityProvider>
                    <Toaster
                        position='top-right'
                        containerStyle={{ zIndex: 1300 }}
                        toastOptions={{ style: { minWidth: 300 } }}
                    />
                    <UploadProvider>
                        <EnvVariablesProvider>
                            <OcgaHardwareVersionsPrefetch />
                            <ClientLoader fetch={fetch}>
                                <SessionTimelinePanelProvider defaultOpen={true}>
                                    <RouterProvider router={router} future={{ v7_startTransition: true }} />
                                </SessionTimelinePanelProvider>
                            </ClientLoader>
                        </EnvVariablesProvider>
                    </UploadProvider>
                </IdentityProvider>
            </MaintenanceMode>
        </QueryClientProvider>
    );
};
