import type { OpenChangeReason } from '@floating-ui/react';
import { useCallback } from 'react';

interface UseModalOnCloseProps {
    disableOutsidePress?: boolean;
    disableEscapeKey?: boolean;
    onClose?: Function;
}

export const useModalOnClose = ({
    disableOutsidePress = true,
    disableEscapeKey = true,
    onClose,
}: UseModalOnCloseProps) => {
    return useCallback(
        ({ event, reason }: { event?: Event; reason?: OpenChangeReason }) => {
            if (disableOutsidePress && reason === 'outside-press') {
                event?.preventDefault();
                return;
            }
            if (disableEscapeKey && reason === 'escape-key') {
                return;
            }
            onClose?.();
        },
        [disableOutsidePress, disableEscapeKey, onClose],
    );
};
