import { useUpload } from '@gsm-app/providers/UploadProvider';
import { useCallback } from 'react';
import type { PlayerBlob } from './usePATPlayerBlobs';

export const usePATPlayerBlobUpload = (pat: string | undefined) => {
    const { startUpload: fileUpload, updateUpload } = useUpload();

    const startUpload = useCallback(
        async (name: string, revision: string | undefined, file: File) => {
            if (!pat) {
                return;
            }

            const buffer = await file?.arrayBuffer();
            const blob = new Blob([buffer], { type: 'application/octet-stream' });
            return fileUpload<{ data: PlayerBlob }, Blob>(name, name, {
                method: 'post',
                url: '/api/playerblobs/upload',
                headers: {
                    pat,
                    xblobname: name,
                    xblobrevision: revision,
                    'Content-Type': 'application/octet-stream',
                    'Content-Disposition': `attachment; filename="${name}"`,
                },
                data: blob,
            });
        },
        [pat, fileUpload],
    );

    return {
        startUpload,
        updateUpload,
    };
};
