import * as yup from 'yup';

export const createSchema = (usedSlotNames: string[]) => {
    return yup.object({
        slot: yup
            .string()
            .required('Slot Name is required')
            .notOneOf(usedSlotNames, 'Slot Name already used')
            .max(50)
            .matches(/^[A-Za-z0-9\-_.]+$/, 'Slot Name must use only letters, numbers, dashes, and underscores'),
        files: yup
            .mixed<FileList>()
            .required('File is required')
            .test('fileList', 'File is required', list => list?.length > 0),
    });
};
