import { createClient } from '@ui-paved-road/graphql';
import { createPrePersistedQueryLink } from '@ui-paved-road/graphql/links';

/**
 * Constructs the headers required for making requests to the consumer gateway.
 *
 * @param passport The users passport id
 * @returns A headers object for use with the consumer graphql client
 */
export const getConsumerHeaders = (passport?: string) => {
    return {
        'X-Ncgt-Client-Name': 'ncgtportal',
        'x-passport': passport ?? '',
    };
};

export const consumerClient = createClient({
    uri: '/consumer/graphql',
    additionalLinks: [createPrePersistedQueryLink()],
});
