import type { PlayerBlob } from '@gsm-app/components/PlayerBlobModal/hooks/usePATPlayerBlobs';

import { Button, ButtonGroup, Card, CardBody, CardFooter, CardHeader, Stack } from '@hawkins/components';
import { Dimensions } from '@hawkins/variables';
import { yupResolver } from '@hookform/resolvers/yup';
import { InputField } from '@ncgt/common-ui';
import { useMemo, useRef } from 'react';
import { FormProvider, type SubmitHandler, useForm } from 'react-hook-form';
import { createSchema } from './schema';

interface PlayerBlobUploadFormProps {
    playerBlobs: PlayerBlob[];
    onClose: () => void;
    onSubmit: SubmitHandler<FormState>;
}

export interface FormState {
    slot: string;
    files: FileList;
}

export const PlayerBlobUploadForm = ({ playerBlobs, onClose, onSubmit }: PlayerBlobUploadFormProps) => {
    const formRef = useRef<HTMLFormElement>(null);
    const schema = useMemo(() => createSchema(playerBlobs.map((p) => p.name)), [playerBlobs]);
    const methods = useForm<FormState>({
        mode: 'onChange',
        reValidateMode: 'onChange',
        resolver: yupResolver(schema),
        defaultValues: { slot: '' },
    });

    return (
        <Card>
            <CardHeader title='Upload Player Blob' />
            <CardBody>
                <FormProvider {...methods}>
                    <form ref={formRef} autoComplete='off' onSubmit={methods.handleSubmit(onSubmit)}>
                        <Stack gap={Dimensions.Space8}>
                            <InputField label='Slot Name' name='slot' required />
                            <InputField type='file' name='files' label='Player Blob' required />
                        </Stack>
                    </form>
                </FormProvider>
            </CardBody>
            <CardFooter>
                <ButtonGroup justifyContent='flex-end'>
                    <Button variant='tertiary' onClick={onClose}>
                        Cancel
                    </Button>
                    <Button
                        onClick={() => {
                            formRef.current?.dispatchEvent(new Event('submit', { cancelable: true, bubbles: true }));
                        }}
                    >
                        Submit
                    </Button>
                </ButtonGroup>
            </CardFooter>
        </Card>
    );
};
