import { isNil, omitBy, overSome } from 'lodash-es';
import { useCallback, useMemo } from 'react';
import { type NavigateOptions, type URLSearchParamsInit, useSearchParams as useSearch } from 'react-router-dom';

export type URLSearchParamsObject = Record<string, string | string[] | undefined>;
export type SetParams = (
    nextInit?: URLSearchParamsInit | ((prev: URLSearchParams) => URLSearchParamsInit),
    navigateOpts?: NavigateOptions,
) => void;

export const paramsObject = <T extends URLSearchParamsObject>(params: URLSearchParams) => {
    const results: any = {};
    params.forEach((v, k) => {
        results[k] = v;
    });
    return results as T;
};

/**
 * remove KVPs when value is undefined or null
 * @param value
 * @returns
 */
const cleanupParams = (value: URLSearchParamsInit) => {
    if (typeof value === 'string') {
        return value;
    }
    return omitBy(value, overSome([isNil])) as URLSearchParamsInit;
};

/**
 * Sync Record with the URL
 * @param defaultInit
 * @returns [params as Record, method to set params]
 */
export const useSearchParams = <T extends URLSearchParamsObject>(
    defaultInit?: URLSearchParamsInit,
): [Partial<T>, SetParams] => {
    const [params, setParams] = useSearch(defaultInit);
    const state = useMemo(() => paramsObject<Partial<T>>(params), [params]);
    const setState = useCallback<SetParams>(
        (next, options) => {
            if (typeof next === 'function') {
                return setParams(prev => {
                    return cleanupParams(next(prev));
                }, options);
            }
            return setParams(next ? cleanupParams(next) : undefined, options);
        },
        [setParams],
    );
    return [state, setState];
};
