import type { FallbackProps } from 'react-error-boundary';
import { ErrorBoundary as TelemetryErrorBoundary } from '@ui-paved-road/telemetry/react';
import type { ReactNode, PropsWithChildren } from 'react';
import { AppLogo, Button, ButtonGroup, Centered, ErrorState, type ErrorStateProps } from '@hawkins/components';
import { APP_NAME } from '@gsm-app/constants';
import { useTelemetry } from '@ui-paved-road/telemetry/react';
import { useEffect } from 'react';

export interface ErrorUIProps {
    title?: string;
    subtitle?: string;
    errorMessage?: string;
    actions?: ReactNode;
    variant?: ErrorStateProps['variant'];
}

const getDefaultContent = (variant: ErrorStateProps['variant']): { title: string; subtitle: string } => {
    switch (variant) {
        case 'not-found':
            return {
                title: 'Page Not Found',
                subtitle: "The page you're looking for doesn't exist or has been moved.",
            };
        case 'restricted':
            return {
                title: 'Access Restricted',
                subtitle: "You don't have permission to access this page.",
            };
        case 'unavailable':
            return {
                title: 'Service Unavailable',
                subtitle: 'This service is temporarily unavailable. Please try again later.',
            };
        default:
            return {
                title: 'Something went wrong!',
                subtitle: 'Sorry about that. Please try again or contact support to help troubleshoot.',
            };
    }
};

export const ErrorUI = ({ title, subtitle, errorMessage, actions, variant = 'something-wrong' }: ErrorUIProps) => {
    const defaults = getDefaultContent(variant);
    const finalTitle = title ?? defaults.title;
    const finalSubtitle = subtitle ?? defaults.subtitle;
    const telemetry = useTelemetry();

    // Track when user hits a restricted page
    useEffect(() => {
        if (variant === 'restricted') {
            telemetry.trackError(new Error('User attempted to access restricted content'));
        }
    }, [variant, telemetry]);

    const defaultActions = (
        <ButtonGroup>
            <Button
                onClick={() => {
                    window.location.href = '/';
                }}
                variant='primary'
            >
                Go Home
            </Button>
            <Button onClick={() => window.location.reload()} variant='secondary'>
                Try Again
            </Button>
        </ButtonGroup>
    );

    return (
        <Centered layout={{ padding: 24 }}>
            <ErrorState
                appLogo={<AppLogo name={APP_NAME} studioLogo translate={{ 'appLogo.netflix.studio': APP_NAME }} />}
                subtitle={`${finalSubtitle} ${errorMessage && variant !== 'restricted' ? `Error: ${errorMessage}` : ''}`}
                actions={actions ?? defaultActions}
                title={finalTitle}
                variant={variant}
            />
        </Centered>
    );
};

export const ErrorFallback = ({ error }: FallbackProps) => {
    return <ErrorUI errorMessage={error?.message} />;
};

export const ErrorBoundary = ({ children }: PropsWithChildren) => {
    return <TelemetryErrorBoundary FallbackComponent={ErrorFallback}>{children}</TelemetryErrorBoundary>;
};
