import type { Game } from '@gsm-app/models/Game';
import type { DropdownOption } from '@hawkins/components';
import { useMemo } from 'react';

export const createGameOption = (game: Game): DropdownOption<string> => {
    return {
        label: game.title,
        value: game.id,
        subtitle: game.partner?.name ? `${game.id} · ${game.partner.name}` : game.id,
    };
};

export const useGameOptions = (games: Game[]) => {
    return useMemo<DropdownOption<string>[]>(() => {
        return games.map((game) => createGameOption(game));
    }, [games]);
};
