import { IconRefresh, IconUpload } from '@hawkins/assets';
import { Button, ButtonGroup, ErrorState, InlineFeedback, Loader, Stack } from '@hawkins/components';
import { Dimensions } from '@hawkins/variables';
import { useState } from 'react';
import { usePlayerBlobs } from '../../hooks/usePlayerBlobs';
import { PlayerBlobItem } from '../PlayerBlobItem';
import { PlayerBlobUploadForm } from './components/PlayerBlobUploadForm';

interface PlayerBlobContentProps {
    gameId: number | undefined;
    email: string | undefined;
    loadingSopAccount: boolean;
}

export const PlayerBlobContent = ({ gameId, email, loadingSopAccount }: PlayerBlobContentProps) => {
    const {
        loading: loadingPlayerBlobs,
        data: playerblobs,
        error,
        refreshPlayerBlobs,
        uploadPlayerBlob,
        replacePlayerBlob,
        deletePlayerBlob,
        downloadPlayerBlob,
    } = usePlayerBlobs(gameId, email);
    const [showFileUpload, setShowFileUpload] = useState(false);

    if (error) {
        return <InlineFeedback dismissible={false} message='Error retrieving Player Blobs' variant='error' />;
    }

    if (!loadingSopAccount && !email) {
        return <InlineFeedback dismissible={false} message='No Test Account Selected' variant='warning' />;
    }

    if (loadingPlayerBlobs || loadingSopAccount || !gameId) {
        return <Loader variant='linear' />;
    }

    if (showFileUpload) {
        return (
            <PlayerBlobUploadForm
                playerBlobs={playerblobs?.data.items ?? []}
                onClose={() => setShowFileUpload(false)}
                onSubmit={values => {
                    uploadPlayerBlob(values.slot, values.files[0]);
                    setShowFileUpload(false);
                }}
            />
        );
    }

    return (
        <>
            <ButtonGroup justifyContent='space-between'>
                <Button icon={IconRefresh} variant='tertiary' onClick={() => refreshPlayerBlobs(false)}>
                    Refresh
                </Button>
                <Button icon={IconUpload} variant='tertiary' onClick={() => setShowFileUpload(true)}>
                    Upload Player Blob
                </Button>
            </ButtonGroup>
            <Stack gap={Dimensions.Space8}>
                {playerblobs?.data.items.map(({ name, revision }) => {
                    return (
                        <PlayerBlobItem
                            key={`${revision}_${name}`}
                            disabled={false}
                            name={name}
                            revision={revision}
                            onDelete={() => deletePlayerBlob(name, revision)}
                            onDownload={() => downloadPlayerBlob(name)}
                            onReplace={(file: File) => replacePlayerBlob(name, file)}
                        />
                    );
                })}
                {!playerblobs?.data.total_items && (
                    <ErrorState size='small' title='No Player Blobs Found' variant='not-found' />
                )}
            </Stack>
        </>
    );
};
