import type { OcgaHardwareVersion } from '@gsm-app/models/OcgaHardwareVersion';
import { useFeature } from '@gsm-app/hooks/useFeature';
import { fetch } from '@gsm-app/utils/fetch';
import { createError } from '@gsm-common/utils/toast/createError';
import { useQuery } from '@tanstack/react-query';
import { useEffect, useMemo } from 'react';

interface OcgaHardwareVersionsResponse {
    hardwareTypes: OcgaHardwareVersion[];
    cached?: boolean;
}

export const OCGA_HARDWARE_VERSIONS_QUERY_KEY = 'ocgaHardwareVersions';

export const useOcgaHardwareVersions = () => {
    const { ocgaTargeting } = useFeature();

    const query = useQuery<OcgaHardwareVersionsResponse>({
        queryKey: [OCGA_HARDWARE_VERSIONS_QUERY_KEY],
        enabled: ocgaTargeting,
        queryFn: async () => {
            const response = await fetch('/api/ocga-hardware-versions');
            if (!response.ok) {
                throw new Error(`Error fetching OCGA hardware versions: ${response.statusText}`);
            }
            return await response.json();
        },
    });

    const hardwareVersions = useMemo<OcgaHardwareVersion[]>(
        () => (query.data?.hardwareTypes && Array.isArray(query.data?.hardwareTypes) ? query.data.hardwareTypes : []),
        [query.data],
    );

    const { error, isError } = query;
    useEffect(() => {
        if (isError) {
            createError({
                title: 'Error Loading OCGA Hardware Versions',
                body: `${error?.message}`,
                options: {
                    id: 'ocga-hardware-versions-fetch-error',
                },
            });
        }
    }, [error, isError]);

    return {
        ...query,
        data: hardwareVersions,
    };
};
