export class PromiseTimerImpl {
    static resolveWithin<T>(timeout: number, promise: Promise<T>): Promise<T> {
        return new Promise<T>((resolve, reject) => {
            const timeoutId = globalThis.setTimeout(() => {
                reject(new Error('Timeout'));
            }, timeout);

            promise
                .then(result => {
                    resolve(result);
                    globalThis.clearTimeout(timeoutId);
                })
                .catch(error => {
                    reject(error);
                    globalThis.clearTimeout(timeoutId);
                });
        });
    }
}
