import { createError } from '@gsm-common/utils/toast/createError';
import type { PlayerBlob } from '../hooks/usePATPlayerBlobs';

export const deletePlayerBlob = async (
    name: string,
    revision: string | undefined,
    pat: string,
): Promise<PlayerBlob | undefined> => {
    let deleteResponse: PlayerBlob | undefined = undefined;

    try {
        deleteResponse = await fetch('/api/playerblobs/delete', {
            method: 'POST',
            headers: {
                pat,
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                name,
                revision,
            }),
        }).then(async response => {
            if (response.ok) {
                return response.json();
            }
            throw await response.json();
        });
    } catch (e: any) {
        const error: { title: string; detail: string } = e?.errors?.[0];
        createError({
            title: 'Error Deleting Player Blob',
            body: `${error?.detail}`,
            options: {
                id: 'delete-playerblob',
            },
        });
    }

    return deleteResponse;
};
