import { Divider, Text } from '@hawkins/components';
import {
    Brush,
    CursorLine,
    type DataConfig,
    LineChart,
    type ScaleFn,
    type VizValue,
    XAxis,
    XYGridLines,
    transformIdentity,
} from '@netflix-internal/react-vizkit';
import { useCallback, useMemo } from 'react';
import { CHART_HEIGHT, ChartColors } from '../../constants';
import { scrubberData } from '../../exampleData';
import { BrushType, useChart } from '../../providers/ChartProvider';
import { getDurationTicks } from '../../utils/getDurationTicks';
import { renderTick } from '../../utils/renderTick';
import { format } from '../../utils/time';
import { zoomToExtent } from '../../utils/zoomToExtent';
import { useSessionTimelineData } from '../../providers/SessionTimelineDataProvider';
import { ChartType } from '../../types';

const SCRUBBER_HEIGHT = 80;
const SCRUBBER_AXIS_HEIGHT = 25;
const STATS_GRAPH = ChartType.STATS;
const SCRUBBER_STAT = 'gpu';

export const Scrubber = () => {
    const { datasets } = useSessionTimelineData();

    const chartDataset = datasets ? datasets[ChartType.STATS] : undefined;
    const latestDateTimestamp = chartDataset ? chartDataset[chartDataset.length - 1]?.date : 0;
    const { brushXExtentState, setBrushXExtent, vizTransform, setVizTransform } = useChart();

    const brushXExtent = useMemo(() => {
        if (brushXExtentState === null) {
            return null;
        }
        if (brushXExtentState.type === BrushType.RANGE) {
            return brushXExtentState.extent;
        }
        // otherwise latest...
        return [
            new Date(latestDateTimestamp - brushXExtentState.delta),
            new Date(latestDateTimestamp),
        ];
    }, [brushXExtentState, latestDateTimestamp]);

    const onBrush = useCallback((bounds: any, { xScale, yScale, groupHeight }: VizValue) => {
        if (bounds) {



            const xExtent = [
                (xScale as any).invert(bounds[0][0]),
                (xScale as any).invert(bounds[1][0]),
              ];

              setBrushXExtent({
                  type: BrushType.LATEST,
                  delta: xExtent[1].getTime() - xExtent[0].getTime(),
                });


            const range = xScale?.range() ?? [0, 0];
            const yRange = yScale?.range() ?? [0, 0];
            setVizTransform(zoomToExtent(bounds, range[1] - range[0], groupHeight));
        } else {
            setBrushXExtent(null);
            setVizTransform(transformIdentity.reset());
        }
    }, [setBrushXExtent, setVizTransform]);

    const data: any[] | DataConfig<any> | undefined =
        chartDataset ? {
        points: chartDataset.filter((stat: any) => {
            return stat.lineKey === SCRUBBER_STAT;
        }),
        channels: {
            x: 'date',
            y: 'value',
            dataset: 'lineKey',
            color: 'lineKey',
            datasetTitle: (d: any) => String(d.lineKey).toUpperCase(),
        }
    } : undefined;

    return data ? (
        <>
            <div style={{ minHeight: SCRUBBER_HEIGHT }}>
                <LineChart
                    data={data}
                    width='100%'
                    height={SCRUBBER_HEIGHT}
                    measureEndcaps={false}
                    disableGroups={['LineEndcaps', 'XYPopperLines', 'CursorLine']}
                    x={{ axis: false }}
                    y={{ axis: false }}
                    color={{
                        scale: ((series: string | undefined) => {
                            return series ? ChartColors[series] : '';
                        }) as ScaleFn,
                    }}
                >
                    <XAxis
                        orient='top'
                        position='top-center'
                        showTickLines={false}
                        showLine={false}
                    />
                    <XYGridLines y={false} />
                    <CursorLine
                        highlightClosestPointToMouse={false}
                        pointProps={{
                            opacity: 0,
                            fillOpacity: 0,
                        }}
                    />
                    <Brush
                        axis='x'
                        brushExtent={brushXExtent}
                        onBrush={onBrush}
                    />
                </LineChart>
            </div>
            <Divider />
            <div style={{ minHeight: SCRUBBER_AXIS_HEIGHT }}>
                <LineChart
                    data={scrubberData}
                    width='100%'
                    height={SCRUBBER_AXIS_HEIGHT}
                    measureEndcaps={false}
                    disableGroups={['LineEndcaps', 'XYPopperLines', 'CursorLine', 'Lines']}
                    vizTransform={vizTransform}
                    onChangeVizTransform={setVizTransform}
                    x={{ axis: false }}
                    y={{ axis: false }}
                >
                    <XYGridLines
                        y={false}
                        x
                        dy1={-SCRUBBER_AXIS_HEIGHT / 2}
                        dy2={SCRUBBER_AXIS_HEIGHT / 2}
                        layer='svg-viz-bg'
                    />
                    <XAxis
                        position='bottom-center'
                        showLine={false}
                        showTickLines={false}
                        formatter={v => format(v)}
                        render={renderTick}
                        ticks={getDurationTicks}
                    />
                </LineChart>
            </div>
        </>
    ): (
        <div style={{
            minHeight: CHART_HEIGHT,
            display: 'flex',
            alignItems: 'center',
            flexDirection: 'column',
            justifyContent: 'center'
        }}>
            <Text colorVariant='faded'>
                No data
            </Text>
        </div>
    );
};
