import { AppLogo, Box, Stack, Text, useTheme } from '@hawkins/components';
import { IconWarning } from '@hawkins/assets';
import { APP_NAME } from '@gsm-app/constants';
import { useFeature } from '@gsm-app/hooks/useFeature';
import type { PropsWithChildren } from 'react';
import styles from './MaintenanceMode.module.css';

export const MaintenanceMode = ({ children }: PropsWithChildren) => {
    const { maintenanceMode } = useFeature();

    // maintenance mode screen if enabled
    if (maintenanceMode) {
        return <MaintenanceScreen />;
    }

    // show normal app content
    return <>{children}</>;
};

const MaintenanceScreen = () => {
    const theme = useTheme();
    const bgGradient = theme.name === 'dark' ? styles.backgroundGradientDark : styles.backgroundGradientLight;
    
    return (
        <div className={styles.maintenanceContainer}>
            <div className={bgGradient} />
            
            <Box className={styles.maintenanceBox}>
                <Stack direction='column' spacing='large' align='center' gap={5}>
                    <div className={styles.logoContainer}>
                        <AppLogo
                            name={APP_NAME}
                            studioLogo
                            translate={{ 'appLogo.netflix.studio': APP_NAME }}
                        />
                    </div>
                    <Box>
                        <IconWarning size='jumbo' color='warning' />
                    </Box>
                    
                    <Stack direction='column' spacing='small' align='center' gap={12} className={styles.messageContainer}>
                        <Text variant='body' align='center' level={2} bold className={styles.warningTitle}>
                            System Maintenance
                        </Text>
                         <Text variant='body' align='center' color='secondary' level={2}>
                            We're currently performing scheduled maintenance to improve your experience.
                        </Text>
                        <Text variant='body' align='center' color='secondary' level={2}>
                            We'll be back online shortly. Thank you for your patience.
                        </Text>
                    </Stack>
                </Stack>
            </Box>
        </div>
    );
};
