import DetectRTC from 'detectrtc';
import { useEffect, useState } from 'react';

export function useWebRTCDetection() {
    const [detector, setDetector] = useState<{
        isWebRTCSupported: boolean;
        browser: {
            name: string;
            fullVersion: string;
        };
    }>();

    useEffect(() => {
        DetectRTC.load(function () {
            setDetector(DetectRTC);
        });
    }, []);

    if (!detector) {
        return 'Detecting WebRTC Capability...';
    }
    const supportText = detector.isWebRTCSupported ? 'supports' : 'does not support';
    return `${detector.browser.name} ${detector.browser.fullVersion} ${supportText} WebRTC`;
}
