import { createContext, type PropsWithChildren, useCallback, useContext, useState } from 'react';

interface SessionTimelinePanelContextValue {
    open: boolean;
    toggleOpen: () => void;
    onExpand: () => void;
    onCollapse: () => void;
}

const context = createContext<SessionTimelinePanelContextValue>({} as SessionTimelinePanelContextValue);

export const SessionTimelinePanelProvider = ({ children, defaultOpen }: PropsWithChildren<{ defaultOpen: boolean }>) => {
    const [open, setIsOpen] = useState(defaultOpen);
    const toggleOpen = useCallback(() => setIsOpen(prev => !prev), []);
    const onExpand = useCallback(() => setIsOpen(true), []);
    const onCollapse = useCallback(() => setIsOpen(false), []);

    return <context.Provider value={{ open, toggleOpen, onExpand, onCollapse }}>{children}</context.Provider>;
};

export const useSessionTimelinePanel = () => useContext(context);
