import { useModal } from '@gsm-app/providers/ModalProvider';
import { useQueryClient } from '@tanstack/react-query';
import { useCallback, useMemo, useState } from 'react';
import { deletePlayerBlob as deleteBlob } from '../utils/deletePlayerBlob';
import { downloadPlayerBlob as downloadBlob } from '../utils/downloadPlayerBlob';
import { usePAT } from './usePAT';
import { type PlayerBlobsResponse, usePATPlayerBlobs } from './usePATPlayerBlobs';
import { usePATPlayerBlobUpload } from './usePATPlayerBlobUpload';

export const usePlayerBlobs = (gameId: number | undefined, email: string | undefined) => {
    const queryClient = useQueryClient();
    const { showModal } = useModal();
    const [ignoreRefetch, setIgnoreRefetch] = useState(true);
    const { data: pat, error: errorPAT, isLoading: loadingPlayerAccessToken } = usePAT(gameId, email);
    const {
        data: playerblobs,
        error: errorPlayerBlobs,
        isLoading: loadingPlayerBlobs,
        isRefetching: isRefetchingPlayerBlobs,
    } = usePATPlayerBlobs(pat);
    const { startUpload, updateUpload } = usePATPlayerBlobUpload(pat);
    const queryKey = useMemo(() => ['playerblobs', pat], [pat]);

    const refreshPlayerBlobs = useCallback(
        (ignoreRefetch: boolean = true) => {
            setIgnoreRefetch(() => ignoreRefetch);
            // invalidate the cache
            queryClient.invalidateQueries({ queryKey });
        },
        [queryKey, setIgnoreRefetch],
    );

    const uploadPlayerBlob = useCallback(
        async (name: string, file: File) => {
            if (!pat || !playerblobs || !name) {
                return;
            }

            // check if name is already used
            const save = playerblobs.data.items.find(item => item.name === name);
            if (save) {
                updateUpload(name, {
                    filename: name,
                    status: 'failure',
                    message: `Player Blob ${name} already in use`,
                    loaded: 0,
                    total: 0,
                });
                return;
            }

            try {
                const uploaded = await startUpload(name, undefined, file);
                if (!uploaded) {
                    return;
                }
                const items = [...playerblobs.data.items, uploaded.data.data];

                // add to local cache
                queryClient.setQueryData<PlayerBlobsResponse>(queryKey, {
                    data: {
                        total_items: (playerblobs.data.total_items ?? 0) + 1,
                        items: items,
                    },
                });
                refreshPlayerBlobs();
            } catch (_) {
                // error is handled within useUpload
            }
        },
        [queryClient, queryKey, updateUpload, startUpload, refreshPlayerBlobs, playerblobs, pat],
    );

    const replacePlayerBlob = useCallback(
        async (name: string, file: File) => {
            const save = playerblobs?.data.items.find(item => item.name === name);

            if (!save || !playerblobs) {
                return;
            }

            try {
                const uploaded = await startUpload(save.name, save.revision, file);

                if (!uploaded) {
                    return;
                }

                const items = playerblobs.data.items.map(item => {
                    if (item.name !== name) {
                        return item;
                    }
                    return uploaded.data.data;
                });

                // update local cache
                queryClient.setQueryData<PlayerBlobsResponse>(queryKey, {
                    data: {
                        total_items: playerblobs.data.total_items,
                        items: items,
                    },
                });
                refreshPlayerBlobs();
            } catch (_) {
                // error is handled within useUpload
            }
        },
        [playerblobs, queryClient, queryKey, refreshPlayerBlobs],
    );

    const deletePlayerBlob = useCallback(
        async (name: string, revision: string | undefined) => {
            if (!pat || !playerblobs) {
                return;
            }

            showModal('confirm', {
                title: 'Are you sure you want to delete this Player Blob?',
                confirmLabel: 'Delete',
                confirmVariant: 'primary-destructive',
                onConfirm: async () => {
                    // remove from local cache
                    const items = playerblobs.data.items.filter(item => item.revision !== revision);
                    queryClient.setQueryData<PlayerBlobsResponse>(queryKey, {
                        data: {
                            total_items: Math.max(0, (playerblobs.data.total_items ?? 1) - 1),
                            items: items,
                        },
                    });

                    await deleteBlob(name, revision, pat);

                    // invalidate the cache
                    refreshPlayerBlobs();
                },
            });
        },
        [playerblobs, queryClient, pat, refreshPlayerBlobs],
    );

    const downloadPlayerBlob = useCallback(
        (name: string) => {
            if (!pat) {
                return;
            }
            downloadBlob(name, pat);
        },
        [pat],
    );

    return {
        loading: loadingPlayerAccessToken || loadingPlayerBlobs || (!ignoreRefetch && isRefetchingPlayerBlobs),
        data: playerblobs,
        error: errorPAT || errorPlayerBlobs,
        uploadPlayerBlob,
        refreshPlayerBlobs,
        replacePlayerBlob,
        deletePlayerBlob,
        downloadPlayerBlob,
    };
};
