import { useFeature } from '@gsm-app/hooks/useFeature';
import { useModal } from '@gsm-app/providers/ModalProvider';
import { useCallback } from 'react';
import { UserVoiceFeedbackModal } from '@ncgt/common-ui';
import { createToast } from '@gsm-common/utils/toast/createToast';
import { Button } from '@hawkins/components';
import { ConfirmModal } from '../ConfirmModal';
import { NewChannelModal } from '../NewChannelModal';
import { NotificationsModal } from '../NotificationsModal';
import { PlayerBlobModal } from '../PlayerBlobModal';
import { SopAccountModal } from '../SopAccountModal';
import { UploadBuildModal } from '../UploadBuildModal';

export const ModalContainer = () => {
    const { modal, modalData, showModal } = useModal();
    const { viewUserVoice } = useFeature();

    const closeModal = useCallback(() => showModal(undefined), [showModal]);

    return (
        <>
            {modal === 'uploadBuild' && <UploadBuildModal onClose={closeModal} />}
            {modal === 'sopAccount' && <SopAccountModal modalData={modalData} onClose={closeModal} />}
            {modal === 'confirm' && (
                <ConfirmModal onClose={closeModal} onConfirm={modalData.onConfirm} modalData={modalData} />
            )}
            {modal === 'newChannel' && <NewChannelModal onClose={closeModal} />}
            {modal === 'notifications' && <NotificationsModal onClose={closeModal} />}
            {modal === 'playerBlob' && <PlayerBlobModal onClose={closeModal} />}
            {modal === 'feedback' && (
                <UserVoiceFeedbackModal
                    onClose={closeModal}
                    showViewButton={viewUserVoice}
                    onSuccess={(portalUrl) => {
                        createToast({
                            title: 'Thank you for your feedback!',
                            variant: 'success',
                            footer: portalUrl ? (
                                <Button
                                    variant="tertiary"
                                    size="small"
                                    onClick={() => window.open(portalUrl, '_blank')}
                                >
                                    View
                                </Button>
                            ) : undefined,
                            options: { duration: Infinity, position: 'top-center' },
                        });
                    }}
                />
            )}
        </>
    );
};
