import axios, { AxiosError, type AxiosProgressEvent, type AxiosResponse, CanceledError } from 'axios';
import axiosRetry from 'axios-retry';
import { auth } from './auth';

const MAX_PARTS = 10_000;
const MIN_PART_SIZE = 5 * 1024 * 1024;
const DEFAULT_PART_SIZE = 8 * 1024 * 1024;
const TARGET_SIZE_IN_MEMORY = 100 * 1024 * 1024;

interface UploadOptions {
    onStart?: () => Promise<Response>;
    updateProgressCallback?: (progress: number) => void;
    partSize?: number;
}

// these must match the BuildState values on the server side
export enum UploadState {
    UPLOAD_PROGRESS = 'upload_progress',
    UPLOAD_CANCELED = 'upload_canceled',
    UPLOAD_FAILED = 'upload_failed',
    UPLOAD_SUCCEED = 'upload_succeed',
}

interface UploadResult {
    state: UploadState;
    status?: number;
    title?: string;
    statusText?: string;
    error?: any;
}

export class FileUploader {
    abortController: AbortController;
    authProvider: typeof auth;
    

    constructor() {
        this.abortController = new AbortController();
        this.authProvider = auth; 
    }

    cancel() {
        this.abortController.abort();
    }

    async upload(uploadUrl: string, file: File, options: UploadOptions = {}): Promise<UploadResult> {
        this.abortController = new AbortController();
        axiosRetry(axios, { retries: 3, retryDelay: axiosRetry.exponentialDelay });

        let _reject: any = undefined;

        let uploadInitResponse: AxiosResponse;
        try {
            if (options.onStart) {
                const res = await options.onStart();
                if (!res.ok) {
                    const data = await res.json();
                    throw new Error(data.message);
                }
            }

            uploadInitResponse = await axios({
                method: 'post',
                // Specific to FileDTA, see https://file.dta.netflix.com/apidoc/#api-Path-InsertMultiPartInitiate
                url: `${uploadUrl}?uploads`,
                withCredentials: true,
                headers: {
                    'Expire-Policy': 'inf',
                    'Content-Type': 'application/gzip',
                    authorization: `Bearer ${(await this.authProvider.getOrRefreshUser()).access.token}`,
                },
                maxContentLength: Infinity,
                maxBodyLength: Infinity,
                signal: this.abortController.signal,
            });
        } catch (e: any) {
            if (e instanceof CanceledError) {
                return {
                    state: UploadState.UPLOAD_CANCELED,
                };
            } else if (e instanceof AxiosError) {
                return {
                    state: UploadState.UPLOAD_FAILED,
                    error: e.toJSON(),
                };
            } else {
                return {
                    state: UploadState.UPLOAD_FAILED,
                    error: { message: e.message },
                };
            }
        }

        const uploadId = uploadInitResponse.data.uploadId;

        const reader = new FileReader();
        return new Promise((resolve, reject) => {
            _reject = reject;
            const fileSize = file.size;

            let partSize = options.partSize ?? DEFAULT_PART_SIZE;
            if (partSize < MIN_PART_SIZE) partSize = MIN_PART_SIZE;
            if (fileSize > partSize * MAX_PARTS) partSize = Math.ceil(partSize / MAX_PARTS);

            const partsPerChunk = Math.ceil(TARGET_SIZE_IN_MEMORY / partSize);
            const chunkSize = partsPerChunk * partSize;

            let fileOffset = 0;
            let chunkIndex = 0;
            const promises: Promise<{ partNumber: number; etag: any }>[] = [];
            const partProgress: number[] = [];

            reader.onload = async e => {
                const rawData = new Uint8Array(e?.target?.result as ArrayBuffer);

                const parts = [];
                for (let i = 0; i < rawData.length; i += partSize) {
                    const dataSlice = rawData.slice(i, i + partSize);
                    parts.push(dataSlice);
                    partProgress.push(0);
                }

                const newPromises = parts.map(async (part, index) => {
                    const partNumber = partsPerChunk * chunkIndex + index + 1;

                    const uploadPartResponse = await axios({
                        method: 'post',
                        url: `${uploadUrl}?uploadId=${uploadId}&partNumber=${partNumber}`,
                        data: part,
                        headers: {
                            'Content-Type': 'multipart/form-data',
                            authorization: `Bearer ${(await this.authProvider.getOrRefreshUser()).access.token}`,
                        },
                        maxContentLength: Infinity,
                        maxBodyLength: Infinity,
                        onUploadProgress: (evt: AxiosProgressEvent) => {
                            if (options.updateProgressCallback) {
                                partProgress[partNumber] = evt.loaded;

                                let totalProgress = partProgress.reduce((acc, a) => acc + a, 0);
                                const p = Math.round((totalProgress / fileSize) * 100);
                                if (!isNaN(p)) options.updateProgressCallback(p);
                            }
                        },
                        signal: this.abortController.signal,
                    });

                    const etag = uploadPartResponse.data.etag;

                    return { partNumber, etag };
                });

                promises.push(...newPromises);
                fileOffset += chunkSize;
                chunkIndex += 1;
                seek();
            };

            const seek = async () => {
                if (fileOffset >= fileSize) {
                    try {
                        const partTags = await Promise.all(promises);
                        await axios({
                            method: 'post',
                            url: `${uploadUrl}?uploadId=${uploadId}`,
                            data: { parts: partTags },
                            headers: {
                                'Content-Type': 'application/json',
                                authorization: `Bearer ${(await this.authProvider.getOrRefreshUser()).access.token}`,
                            },
                            maxContentLength: Infinity,
                            maxBodyLength: Infinity,
                            signal: this.abortController.signal,
                        });

                        resolve({
                            state: UploadState.UPLOAD_SUCCEED,
                            status: uploadInitResponse.status,
                            statusText: uploadInitResponse.statusText,
                        });
                    } catch (e: any) {
                        if (e instanceof CanceledError) {
                            resolve({
                                state: UploadState.UPLOAD_CANCELED,
                            });
                        } else if (e instanceof AxiosError) {
                            resolve({
                                state: UploadState.UPLOAD_FAILED,
                                error: e.toJSON(),
                            });
                        } else {
                            resolve({
                                state: UploadState.UPLOAD_FAILED,
                                error: { message: e.message },
                            });
                        }
                    }
                } else {
                    const slice = file.slice(fileOffset, fileOffset + chunkSize);
                    reader.readAsArrayBuffer(slice);
                }
            };

            seek();
        });
    }
}
