import { type FileFormat, download } from '@gsm-common/utils/file/download';
import { isJSON } from '@gsm-common/utils/file/isJSON';
import { createError } from '@gsm-common/utils/toast/createError';

const detectFileFormat = (content: Blob): FileFormat => {
    // check json
    if (isJSON(content)) {
        return 'json';
    }
    return 'binary';
};

const createDownload = (name: string, content: Blob) => {
    const format = detectFileFormat(content);
    download(name, content, format);
};

export const downloadPlayerBlob = async (name: string, pat: string) => {
    let doc: Blob | undefined = undefined;
    try {
        doc = await fetch(`/api/playerblobs/download?name=${name}`, {
            headers: {
                pat,
            },
        }).then(async response => {
            if (response.ok) {
                return response.blob();
            }
            throw await response.json();
        });
    } catch (e: any) {
        const error: { title: string; detail: string } = e?.errors?.[0];
        createError({
            title: 'Error Downloading Player Blob',
            body: `${error.detail}`,
            options: {
                id: 'download-playerblob',
            },
        });
    }

    if (doc) {
        createDownload(name, doc);
    }
};
