import { type FeatureKeys, useFeature } from '@gsm-app/hooks/useFeature';
import { Loader } from '@hawkins/components';
import { type ReactNode, useMemo } from 'react';
import { Navigate } from 'react-router-dom';

interface Props {
    featureKey: FeatureKeys;
    featureEvaluationPredicate?: (featureValue: any) => boolean;
    children: ReactNode;
    redirectUrl?: string;
}

export const FeatureProtectedRoute = ({
    featureKey,
    featureEvaluationPredicate,
    children,
    redirectUrl = '/'
}: Props) => {

    const feature = useFeature();
    const enabled = useMemo(() => {
        return featureEvaluationPredicate ? featureEvaluationPredicate(feature[featureKey]) : feature[featureKey];
    }, [feature, featureKey, featureEvaluationPredicate]);

    if (feature.isLoading) {
        return <Loader variant='linear' />
    }

    if (!enabled) {
        return <Navigate to={redirectUrl} replace />;
    }
    return <>{children}</>;
};
