import {
    MOCK_TARGET_INSTANCE_COUNT,
    mockChannels,
    mockControllersResponse,
    mockFeatures,
    mockGames,
    mockSessionInfoResponse,
} from './mockPlayFixtures';

const json = (body: unknown, status = 200) =>
    new Response(JSON.stringify(body), { status, headers: { 'Content-Type': 'application/json' } });

const pathOf = (input: RequestInfo | URL): string => {
    const raw = typeof input === 'string' ? input : input instanceof URL ? input.toString() : input.url;
    try {
        return new URL(raw, window.location.origin).pathname;
    } catch {
        return raw;
    }
};

type Route = { test: (path: string, method: string) => boolean; handle: () => Response };

const routes: Route[] = [
    {
        test: (path, method) => path === '/api/features' && method === 'POST',
        handle: () => json({ data: mockFeatures }),
    },
    {
        test: (path, method) => path === '/api/identity' && method === 'GET',
        // IdentityProvider itself is bypassed entirely in mock mode (see IdentityProvider.tsx), but
        // route this too in case anything else ever calls it directly.
        handle: () => json({ data: null }),
    },
    {
        test: (path, method) => path === '/api/games' && method === 'GET',
        handle: () => json({ data: mockGames }),
    },
    {
        test: (path, method) => /^\/api\/games\/[^/]+\/channels$/.test(path) && method === 'GET',
        handle: () => json({ data: mockChannels }),
    },
    {
        test: (path, method) => /^\/api\/games\/[^/]+\/builds\/[^/]+\/controllers$/.test(path) && method === 'GET',
        handle: () => json(mockControllersResponse),
    },
    {
        test: (path, method) => /^\/api\/games\/[^/]+\/target-instance-count$/.test(path) && method === 'GET',
        handle: () => json({ data: MOCK_TARGET_INSTANCE_COUNT }),
    },
    {
        test: (path, method) => path === '/api/user/key' && method === 'PUT',
        handle: () => json({ key: 'mock-secret-key-0123456789abcdef' }),
    },
    {
        test: (path, method) => path === '/api/access/passport' && method === 'POST',
        handle: () => json({ data: 'mock-passport-token' }),
    },
    {
        test: (path, method) => /^\/api\/sessions\/[^/]+\/info$/.test(path) && method === 'GET',
        handle: () => json(mockSessionInfoResponse),
    },
    {
        test: (path) => path === '/api/game/config',
        handle: () => json({ data: { resolution: 1080, fps: 60 } }),
    },
    {
        test: (path) => path === '/api/ocga-hardware-versions',
        handle: () => json({ hardwareTypes: [] }),
    },
    {
        // Response is a bare array here (see useNotifications.ts's `response.json() as
        // Promise<Notification[]>`), unlike most other routes which wrap in `{ data }`.
        test: (path, method) => path === '/api/notifications' && method === 'GET',
        handle: () => json([]),
    },
    {
        // Queried by the admin-only "system" tooltip in AppMenu.tsx; bare `{ db }` shape, not `{ data }`.
        test: (path, method) => path === '/api/system' && method === 'GET',
        handle: () => json({ db: 'mock-db' }),
    },
];

/**
 * Canned REST responses for the `/api/*` surface the Play page hits — used both by the global
 * `window.fetch` patch (installed from `main.tsx` in mock mode) and by `utils/fetch.ts`'s authed
 * wrapper, so every hook (`useFeature`, `useGames`, `useChannels`, `useSecretKey`, `usePassport`,
 * `useGameControllers`, `useTargetInstanceCount`, …) gets sane fixture data with no real backend.
 * Falls back to a generic empty-success response for any other `/api/*` path so unmocked endpoints
 * degrade quietly instead of throwing on an HTML SPA-fallback body.
 */
export const mockFetch = async (input: RequestInfo | URL, init?: RequestInit): Promise<Response> => {
    const path = pathOf(input);
    const method = (init?.method ?? 'GET').toUpperCase();

    if (!path.startsWith('/api/')) {
        // Not one of ours (e.g. https://api.ipify.org) — resolve harmlessly rather than hitting the network.
        return json({});
    }

    const route = routes.find((r) => r.test(path, method));
    if (route) {
        return route.handle();
    }

    console.debug(`[mockPlay] Unmocked request, returning empty success: ${method} ${path}`);
    return json({ data: [] });
};
