import { arrayMove } from '@dnd-kit/sortable';
import { type Transform, transformIdentity } from '@netflix-internal/react-vizkit';
import {
    type Dispatch,
    type PropsWithChildren,
    type SetStateAction,
    createContext,
    useCallback,
    useContext,
    useMemo,
    useState,
} from 'react';
import { ChartType } from '../types';

export enum BrushType {
    LATEST = 'latest',
    RANGE = 'range',
}

interface ChartContextValue {
    // viz
    vizTransform: Transform;
    setVizTransform: Dispatch<SetStateAction<Transform>>;
    // brush
    brushType: { type: BrushType; value: number } | null;
    setBrushType: Dispatch<SetStateAction<{ type: BrushType; value: number } | null>>;
    brushXExtentState: { type: BrushType.LATEST; delta: number } | { type: BrushType.RANGE; extent: any[] } | null;
    setBrushXExtent: Dispatch<
        SetStateAction<{ type: BrushType.LATEST; delta: number } | { type: BrushType.RANGE; extent: any[] } | null>
    >;
    // charts
    chartState: { [k in ChartType]: ChartState };
    enabledCharts: ChartType[];
    allCharts: ChartType[];
    swapChartIndexes: (a: ChartType, b: ChartType) => void;
    // toggles
    toggleChartVisible: (chart: ChartType) => void;
    toggleChartEnabled: (chart: ChartType) => void;
    isAnyChartEnabled: boolean;
    // drag
    dragId: ChartType | undefined;
    setDragId: Dispatch<SetStateAction<ChartType | undefined>>;
}

type ChartState = { enabled: boolean; visible: boolean };

const context = createContext<ChartContextValue | undefined>(undefined);

// all the available charts (order of menu)
const allCharts: ChartType[] = [
    // ChartType.SCREENSHOTS,
    ChartType.STATS,
    ChartType.FPS,
    // ChartType.INPUT_LATENCY,
    // ChartType.SUGGESTIONS,
];
export const ChartProvider = ({ children }: PropsWithChildren<{}>) => {
    const [vizTransform, setVizTransform] = useState(transformIdentity);
    const [brushType, setBrushType] = useState<{ type: BrushType; value: number } | null>({
        type: BrushType.RANGE,
        value: 1000,
    });
    const [brushXExtentState, setBrushXExtent] = useState<
        { type: BrushType.LATEST; delta: number } | { type: BrushType.RANGE; extent: any[] } | null
    >(null);
    const [chartState, setChartState] = useState<{ [k in ChartType]: ChartState }>({
        [ChartType.FPS]: { enabled: true, visible: true },
        [ChartType.INPUT_LATENCY]: { enabled: true, visible: true },
        [ChartType.SUGGESTIONS]: { enabled: true, visible: true },
        [ChartType.SCREENSHOTS]: { enabled: true, visible: true },
        [ChartType.INSTANCE_COUNT]: { enabled: true, visible: true },
        [ChartType.STATS]: { enabled: true, visible: true },
        [ChartType.EXPORT]: { enabled: true, visible: false },
    });
    const [charts, setCharts] = useState<ChartType[]>(allCharts);
    const [dragId, setDragId] = useState<ChartType | undefined>(undefined);

    const swapChartIndexes = useCallback((a: ChartType, b: ChartType) => {
        if (a !== b) {
            setCharts((prev) => {
                const oldIndex = prev.indexOf(a);
                const newIndex = prev.indexOf(b);
                return arrayMove(prev, oldIndex, newIndex);
            });
        }
    }, []);

    const toggleChartVisible = useCallback((chart: ChartType) => {
        setChartState((prev: any) => {
            const last = prev[chart];
            return {
                ...prev,
                [chart]: {
                    ...last,
                    visible: !last.visible,
                },
            };
        });
    }, []);

    const toggleChartEnabled = useCallback((chart: ChartType) => {
        setChartState((prev: any) => {
            const last = prev[chart];
            return {
                ...prev,
                [chart]: {
                    ...last,
                    enabled: !last.enabled,
                },
            };
        });
    }, []);

    const enabledCharts = useMemo(() => charts.filter((chart) => chartState[chart].enabled), [charts, chartState]);

    const isAnyChartEnabled = useMemo(() => enabledCharts.some((k) => k !== ChartType.SCREENSHOTS), [enabledCharts]);

    return (
        <context.Provider
            value={{
                vizTransform,
                setVizTransform,
                brushType,
                setBrushType,
                brushXExtentState,
                setBrushXExtent,
                chartState,
                enabledCharts,
                allCharts,
                swapChartIndexes,
                toggleChartVisible,
                toggleChartEnabled,
                isAnyChartEnabled,
                dragId,
                setDragId,
            }}
        >
            {children}
        </context.Provider>
    );
};

export const useChart = () => {
    const ctx = useContext(context);
    if (!ctx) {
        throw new Error('useChart must be used within a ChartProvider');
    }
    return ctx;
};
