import type { DevToolsContextValue } from '@gsm-app/providers/DevToolsProvider';
import { useState } from 'react';

export const useDevToolsData = (): DevToolsContextValue => {
    const [open, setOpen] = useState<boolean>(false);
    const toggleDevTools = () => {
        setOpen(!open);
    };

    return { open, toggleDevTools };
};
