import { AppLayout } from '@gsm-app/components/AppLayout';
import { LazyContent } from '@gsm-app/components/LazyContent';
import {
    ROUTE_ADMIN,
    ROUTE_LOGS,
    ROUTE_NETWORK,
    ROUTE_PLAY,
    ROUTE_SESSIONS,
    ROUTE_SSIC,
    ROUTE_TESTS,
} from '@gsm-app/constants';
import { Role } from '@ncgt/common/models/identity';
import { FeatureProtectedRoute } from '@gsm-common/components/FeatureProtectedRoute';
import { RolesProtectedRoute } from '@gsm-common/components/ProtectedRoute';
import { Redirect } from '@gsm-common/components/Redirect';
import { RouteErrorBoundary } from '@gsm-common/components/Error';
import { lazy } from 'react';
import { createBrowserRouter, Navigate } from 'react-router-dom';

const Play = lazy(() => import('@gsm-app/routes/Play'));
const Admin = lazy(() => import('@gsm-app/routes/Admin'));
const SessionView = lazy(() => import('@gsm-app/routes/Sessions/routes/SessionView'));
const CrashDashboard = lazy(() => import('@gsm-app/routes/CrashDashboard'));
const TestExecutionsTable = lazy(() => import('@gsm-app/routes/Tests'));
const NetworkingPage = lazy(() => import('@gsm-app/routes/Networking'));
const Ssic = lazy(() => import('@gsm-app/routes/Ssic'));

export const router = createBrowserRouter(
    [
        {
            path: ROUTE_SSIC,
            element: (
                <LazyContent key={ROUTE_SSIC} loadingMessage='Loading SSIC...'>
                    <Ssic />
                </LazyContent>
            ),
            errorElement: <RouteErrorBoundary />,
        },
        {
            path: '/',
            element: (
                <RolesProtectedRoute roles={[Role.GAMES_ACCESS]} redirect={false}>
                    <AppLayout />
                </RolesProtectedRoute>
            ),
            errorElement: <RouteErrorBoundary />,
            children: [
                { index: true, element: <Redirect to={ROUTE_PLAY} replace={true} /> },
                {
                    path: ROUTE_PLAY,
                    element: (
                        <LazyContent key={ROUTE_PLAY}>
                            <Play />
                        </LazyContent>
                    ),
                },
                {
                    path: ROUTE_ADMIN,
                    element: (
                        <LazyContent key={ROUTE_ADMIN}>
                            <RolesProtectedRoute roles={[Role.NCGT_ADMIN]}>
                                <Admin />
                            </RolesProtectedRoute>
                        </LazyContent>
                    ),
                },
                ...[ROUTE_SESSIONS, `${ROUTE_SESSIONS}/:sessionId`].map((path) => ({
                    path,
                    element: (
                        <LazyContent key={ROUTE_SESSIONS}>
                            <SessionView />
                        </LazyContent>
                    ),
                })),
                ...[ROUTE_LOGS, `${ROUTE_LOGS}/:gameId`].map((path) => {
                    return {
                        path,
                        element: (
                            <LazyContent key={ROUTE_LOGS}>
                                <CrashDashboard />
                            </LazyContent>
                        ),
                    };
                }),
                ...[ROUTE_TESTS, `${ROUTE_TESTS}/:gameId`].map((path) => {
                    return {
                        path,
                        element: (
                            <LazyContent key={ROUTE_TESTS}>
                                <FeatureProtectedRoute featureKey='testExecutions'>
                                    <TestExecutionsTable />
                                </FeatureProtectedRoute>
                            </LazyContent>
                        ),
                    };
                }),
                ...[ROUTE_NETWORK, `${ROUTE_NETWORK}/:gameId`].map((path) => {
                    return {
                        path,
                        element: (
                            <LazyContent key={ROUTE_NETWORK}>
                                <FeatureProtectedRoute featureKey='networkValidation'>
                                    <NetworkingPage />
                                </FeatureProtectedRoute>
                            </LazyContent>
                        ),
                    };
                }),
                {
                    path: '*',
                    element: <Navigate to='/' replace />,
                },
            ],
        },
    ],
);
