import { type ChangeEvent, useState } from 'react';
import { Modal, Stack, Text, Button, Heading, Dropdown, ContextualBanner } from '@hawkins/components';
import { Colors, Dimensions } from '@hawkins/variables';
import styles from './UserVoiceFeedbackModal.module.css';

const typeOfFeedbackOptions = [
    { value: 'Bug', label: 'Bug' },
    { value: 'Feature request', label: 'Feature request' },
    { value: 'Other', label: 'Other' },
];

const urgencyOptions = [
    { value: '(P0) I am blocked', label: '(P0) I am blocked' },
    { value: '(P1) I need it', label: '(P1) I need it' },
    { value: '(P2) I want it', label: '(P2) I want it' },
];

const relevantFeatureOptions = [
    { value: 'Games Workspace', label: 'Games Workspace' },
    { value: 'Cloud Development Portal', label: 'Cloud Development Portal' },
    { value: 'Cloud Toolkit App', label: 'Cloud Toolkit App' },
    { value: 'Cloud CLI', label: 'Cloud CLI' },
    { value: 'Web API', label: 'Web API' },
    { value: 'Documentation', label: 'Documentation' },
    { value: 'Other', label: 'Other' },
];

interface FeedbackData {
    title: string;
    description: string;
    typeOfFeedback: string;
    urgency: string;
    relevantFeatures: string[];
}

interface FeedbackResponse {
    success: boolean;
    suggestionId?: number;
    portalUrl?: string;
    message: string;
    error?: string;
}

interface UserVoiceFeedbackModalProps {
    onClose: () => void;
    maxWidth?: string;
    submitFeedback?: (data: FeedbackData) => Promise<FeedbackResponse>;
    showViewButton?: boolean;
    onSuccess?: (portalUrl?: string) => void;
}

const defaultSubmitFeedback = async (data: FeedbackData): Promise<FeedbackResponse> => {
    const response = await fetch('/api/uservoice/feedback', {
        method: 'POST',
        credentials: 'include',
        headers: {
            'Content-Type': 'application/json',
        },
        body: JSON.stringify(data),
    });

    if (!response.ok) {
        const errorData = await response.json().catch(() => ({ error: 'Failed to submit feedback' }));
        throw new Error(errorData.error || errorData.message || 'Failed to submit feedback');
    }

    const responseData = await response.json();
    return {
        success: true,
        suggestionId: responseData.data?.suggestionId,
        portalUrl: responseData.data?.portalUrl,
        message: 'Feedback submitted successfully',
    };
};

export const UserVoiceFeedbackModal = ({
    onClose,
    maxWidth = '600px',
    submitFeedback = defaultSubmitFeedback,
    showViewButton = true,
    onSuccess,
}: UserVoiceFeedbackModalProps) => {
    const [description, setDescription] = useState('');
    const [typeOfFeedback, setTypeOfFeedback] = useState<{ value: string; label: string } | null>(null);
    const [urgency, setUrgency] = useState<{ value: string; label: string } | null>(null);
    const [relevantFeatures, setRelevantFeatures] = useState<Array<{ value: string; label: string }>>([]);
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [error, setError] = useState<string | null>(null);

    const handleSubmit = async () => {
        if (!typeOfFeedback) {
            setError('Type of Feedback is required');
            return;
        }
        if (!description.trim()) {
            setError('Description is required');
            return;
        }
        if (!urgency) {
            setError('Urgency is required');
            return;
        }

        setError(null);
        setIsSubmitting(true);

        try {
            // Auto-generate title from type and first line of description
            const USER_VOICE_MAX_TITLE_LENGTH = 140;
            const prefix = `[${typeOfFeedback.value}] `;
            const firstLine = description.split('\n')[0].trim();
            const title = `${prefix}${firstLine.substring(0, USER_VOICE_MAX_TITLE_LENGTH - prefix.length)}`;

            // Submit feedback via the provided submit function
            const responseData = await submitFeedback({
                title,
                description,
                typeOfFeedback: typeOfFeedback.value,
                urgency: urgency.value,
                relevantFeatures: relevantFeatures.map(option => option.value),
            });

            if (!responseData.success) {
                throw new Error(responseData.error || responseData.message || 'Failed to submit feedback');
            }
            const suggestionUrl = responseData.portalUrl;

            // Notify consumer of success with portal URL
            if (onSuccess) {
                onSuccess(showViewButton ? suggestionUrl : undefined);
            }

            onClose();
        } catch (err: any) {
            console.error('Failed to submit feedback:', err);
            setError(err.message || 'Failed to submit feedback. Please try again.');
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <Modal open onClose={onClose} maxWidth="90vw">
            <Modal.Header>
                <Heading>Give Feedback</Heading>
            </Modal.Header>
            <Modal.Body className={styles.body} style={{ width: '100vw', maxWidth }}>
                <Stack gap={Dimensions.Space8}>
                    <div className={styles.fieldContainer}>
                        <Dropdown
                            id="feedback-type"
                            label={
                                <>
                                    Type of Feedback <span style={{ color: Colors.Red400 }}>*</span>
                                </>
                            }
                            options={typeOfFeedbackOptions}
                            value={typeOfFeedback}
                            onChange={(selectedValue) => {
                                setTypeOfFeedback(selectedValue as { value: string; label: string });
                            }}
                            disabled={isSubmitting}
                            placeholder="Select an option"
                        />
                    </div>

                    <div className={styles.fieldContainer}>
                        <Text as="label" htmlFor="feedback-description" bold>
                            Description <span style={{ color: Colors.Red400 }}>*</span>
                        </Text>
                        <Text variant="body" className={styles.helperText}>
                            Please give as much detail as possible.
                        </Text>
                        <textarea
                            id="feedback-description"
                            className={styles.textarea}
                            value={description}
                            onChange={(e: ChangeEvent<HTMLTextAreaElement>) =>
                                setDescription(e.target.value)
                            }
                            placeholder=""
                            disabled={isSubmitting}
                            rows={5}
                        />
                    </div>

                    <div className={styles.fieldContainer}>
                        <Dropdown
                            id="feedback-urgency"
                            label={
                                <>
                                    Urgency <span style={{ color: Colors.Red400 }}>*</span>
                                </>
                            }
                            options={urgencyOptions}
                            value={urgency}
                            onChange={(selectedValue) => {
                                setUrgency(selectedValue as { value: string; label: string });
                            }}
                            disabled={isSubmitting}
                            placeholder="Select an option"
                        />
                    </div>

                    <div className={styles.fieldContainer}>
                        <Dropdown
                            id="relevant-features"
                            label="Relevant features"
                            options={relevantFeatureOptions}
                            value={relevantFeatures}
                            onChange={(selectedValues) => {
                                setRelevantFeatures(selectedValues as Array<{ value: string; label: string }>);
                            }}
                            disabled={isSubmitting}
                            placeholder="Select features"
                            multi={true}
                        />
                    </div>

                    {error && (
                        <ContextualBanner
                            variant="error"
                            text={error}
                            onClose={() => setError(null)}
                        />
                    )}
                </Stack>
            </Modal.Body>
            <Modal.Footer className={styles.footer}>
                <div className={styles.buttonContainer}>
                    <Button variant="secondary" onClick={onClose} disabled={isSubmitting}>
                        Cancel
                    </Button>
                    <Button variant="primary" onClick={handleSubmit} disabled={isSubmitting}>
                        {isSubmitting ? 'Submitting...' : 'Submit'}
                    </Button>
                </div>
            </Modal.Footer>
        </Modal>
    );
};
