import { EventEmitter } from '../common/EventEmitter';
import type { Controller } from '../controller';
import type { KeyPressEventModifiers } from '../controller/KeyboardInput';
import { ButtonMap } from '../controller/GamepadMap';
import type { Code } from '@netflix-internal/game-input';

export class UIEventManager extends EventEmitter<UIEventsTypeMap> {
    public constructor(private readonly controller: Controller) {
        super();
    }

    public start(): void {
        const keys: Array<{ key: string; modifiers: KeyPressEventModifiers; eventType: keyof UIEventsTypeMap }> = [
            // Shift + Tab triggers a 'togglemenu' event that will be handled by the web site UI
            {
                key: 'Tab',
                modifiers: { shift: true },
                eventType: 'togglemenu',
            },
            // Ctrl + Alt + Shift + D will trigger the 'toggledebug' event, that's handle by DebugViewer
            {
                key: 'KeyD',
                modifiers: {
                    shift: true,
                    alt: true,
                    ctrl: true,
                },
                eventType: 'toggledebug',
            },
        ];

        keys.forEach(({ key, modifiers, eventType }) =>
            this.controller.subscribeToKeyPress(key, modifiers, keyboardEvent => {
                this.emitEvent(eventType, { type: eventType });
                keyboardEvent.preventDefault();
            }),
        );

        const buttons: Array<{ button: Code; eventType: keyof UIEventsTypeMap }> = [
            {
                button: ButtonMap.ButtonHome,
                eventType: 'togglemenu',
            },
        ];

        buttons.forEach(({ button, eventType }) => {
            this.controller.subscribeToButtonPress(button, () => {
                this.emitEvent(eventType, { type: eventType });
            });
        });
    }
}

export type UIEventsTypeMap = {
    'togglemenu': { type: 'togglemenu' };
    'toggledebug': { type: 'toggledebug' };
};
