import { Paper, type PaperProps } from '@hawkins/components';
import clsx from 'clsx';
import { forwardRef, type ReactNode } from 'react';
import './styles.css';

export interface ContentProps extends PaperProps {
    overflowHidden?: boolean;
    children?: ReactNode;
    className?: string;
}

export const Content = forwardRef<HTMLDivElement, ContentProps>(
    ({ children, className, overflowHidden, ...rest }, ref) => (
        <Paper
            className={clsx('layoutContent', className, {
                overflowHidden,
            })}
            ref={ref}
            square
            {...rest}
        >
            {children}
        </Paper>
    ),
);
