import { useModalOnClose } from '@gsm-app/hooks/useModalOnClose';
import { type SopAccountType, useSopAccounts } from '@gsm-app/providers/SopAccountProvider';
import { Input } from '@gsm-common/components/Input';
import { IconEye, IconEyeOff } from '@hawkins/assets';
import {
    Button,
    ButtonGroup,
    Heading,
    Modal,
    ModalBody,
    ModalFooter,
    ModalHeader,
    Stack
} from '@hawkins/components';
import { type KeyboardEvent, useRef, useState } from 'react';

interface SopAccountModalProps {
    onClose: () => void;
    modalData: {
        edit: string;
        pin: string;
    };
}

export const SopAccountModal = ({ onClose, modalData }: SopAccountModalProps) => {
    const { savedAccounts, setSavedAccounts, selectedAccount, setSelectedAccount } = useSopAccounts();

    const editing = !!modalData?.edit;

    const [selectedSopAccount, setSelectedSopAccount] = useState<SopAccountType | undefined>(selectedAccount);

    const [showPassword, setShowPassword] = useState<boolean>(false);

    const [validateEmail, setValidateEmail] = useState<boolean>(false);
    const emailTaken = useRef<boolean>(editing);
    const emailValid = useRef<boolean>(editing);

    const [validatePIN, setValidatePIN] = useState<boolean>(false);
    const pinValid = useRef<boolean>(editing);

    const [pinValue, setPinValue] = useState<string | null>(() => {
        return editing ? modalData.pin : null;
    });

    const saveLogin = () => {
        if (!selectedSopAccount?.value || !pinValue || !pinValid.current || !emailValid.current) {
            setValidateEmail(true);
            setValidatePIN(true);
            return;
        }

        if (editing) {
            const accountIndex = savedAccounts.findIndex(sop => sop.value === modalData.edit);
            if (accountIndex !== -1) {
                savedAccounts[accountIndex].pin = pinValue;
                savedAccounts[accountIndex].label = selectedSopAccount.label;
                savedAccounts[accountIndex].value = selectedSopAccount.value;
                setSelectedAccount(savedAccounts[accountIndex]);
                setSavedAccounts([...savedAccounts]);
            }
        } else {
            const newAccount = { ...selectedSopAccount, pin: pinValue };
            setSavedAccounts([...savedAccounts, newAccount]);
            setSelectedAccount(newAccount);
        }

        onClose();
    };

    const submitOnEnter = (e: KeyboardEvent<HTMLElement>) => {
        if (e.key === 'Enter') {
            saveLogin();
        }
    };

    const handleOnClose = useModalOnClose({ onClose });

    return (
        <Modal open style={{ width: '600px' }} maxWidth='medium' onKeyDown={submitOnEnter} onClose={handleOnClose}>
            <ModalHeader>
                <Heading level={0}>{editing ? 'Edit' : 'Add'} Test Account</Heading>
            </ModalHeader>
            <ModalBody>
                <Stack gap={5}>
                    <Input
                        label='Account Email'
                        placeholder='Enter Account Email'
                        description='Insert a test account (@netflix.com) email'
                        requirementType='required-star'
                        onKeyDown={submitOnEnter}
                        onChange={e => {
                            const value = e.target.value.trim();
                            emailTaken.current = savedAccounts.findIndex(sop => sop.value === value) !== -1;
                            emailValid.current =
                                !emailTaken.current &&
                                value.startsWith('tester_') &&
                                value.endsWith('@netflix.com');
                            setSelectedSopAccount({
                                label: value,
                                value: value,
                            } as SopAccountType);
                        }}
                        onBlur={() => setValidateEmail(true)}
                        validationStatus={!validateEmail || emailValid.current ? undefined : 'error'}
                        validationMessage={
                            !validateEmail || emailValid.current
                                ? undefined
                                : emailTaken.current
                                ? 'The provided account email has already been saved.'
                                : "The account email address should start with 'tester_' followed by a unique identifier and end with '@netflix.com'"
                        }
                        value={selectedSopAccount?.value ?? ''}
                        autoFocus
                    />
                    <Input
                        label='PIN'
                        type={showPassword ? 'text' : 'password'}
                        autoComplete='off'
                        requirementType='required-star'
                        description='Enter the 4 digit PIN for the test account'
                        placeholder='Enter 4 digit PIN'
                        onChange={e => {
                            setPinValue(e.target.value);
                            pinValid.current = e.target.value !== null && e.target.value.length >= 4;
                        }}
                        onBlur={() => setValidatePIN(true)}
                        onKeyDown={submitOnEnter}
                        value={pinValue ?? ''}
                        inputProps={{
                            pattern: /^[0-9]+$/,
                            autoComplete: 'off',
                            max: 4,
                        }}
                        validationStatus={!validatePIN || pinValid.current ? undefined : 'error'}
                        validationMessage={
                            !validatePIN || pinValid.current
                                ? undefined
                                : 'Please provide the 4 digit PIN for the test account'
                        }
                        endAdornment={
                            <Button
                                compact
                                variant='icon'
                                icon={showPassword ? IconEyeOff : IconEye}
                                onClick={() => setShowPassword(!showPassword)}
                            >
                                {showPassword ? 'Mask Password' : 'Show Password'}
                            </Button>
                        }
                    />
                </Stack>
            </ModalBody>
            <ModalFooter>
                <ButtonGroup justifyContent='flex-end'>
                    <Button variant='secondary' onClick={onClose}>
                        Cancel
                    </Button>
                    <Button onClick={saveLogin}>Save</Button>
                </ButtonGroup>
            </ModalFooter>
        </Modal>
    );
};
