import type { Channel } from '@gsm-app/models/Channel';
import { createAuthzError, isAuthzError, isAuthzStatus } from '@gsm-app/utils/auth';
import { fetch as authedFetch } from '@gsm-app/utils/fetch';
import { createError } from '@gsm-common/utils/toast/createError';
import { useQuery } from '@tanstack/react-query';
import { useEffect, useMemo } from 'react';

interface ChannelsResponse {
    data: Channel[];
}

export const CHANNELS_QUERY_KEY = 'channels';

export const CHANNELS_FETCH_TIMEOUT_MS = 5000;

const getErrorMessage = (error: unknown) => {
    if (error instanceof Error) {
        return error.message;
    }
    if (typeof error === 'string') {
        return error;
    }
    return 'Unknown error';
};

export type UseChannelsOptions = {
    enabled?: boolean;
};

export const useChannels = (gameId?: string, filterGameDev?: boolean, options?: UseChannelsOptions) => {
    const query = useQuery<ChannelsResponse>({
        queryKey: [CHANNELS_QUERY_KEY, gameId],
        gcTime: 0,
        enabled: options?.enabled ?? Boolean(gameId),
        queryFn: async () => {
            const controller = new AbortController();
            const timeout = setTimeout(() => {
                controller.abort();
            }, CHANNELS_FETCH_TIMEOUT_MS);
            try {
                const response = await authedFetch(`/api/games/${gameId}/channels`, { signal: controller.signal });
                if (!response.ok) {
                    if (isAuthzStatus(response.status)) {
                        throw createAuthzError(response.status);
                    }
                    const body = await response.text().catch(() => '');
                    throw new Error(
                        `Error fetching channels (${response.status} ${response.statusText})${body ? `: ${body}` : ''}`,
                    );
                }

                return await response.json();
            } catch (error: unknown) {
                if (controller.signal.aborted) {
                    throw new Error('Channel request timed out');
                }
                throw error;
            } finally {
                clearTimeout(timeout);
            }
        },
    });
    let channels = useMemo(() => (Array.isArray(query.data?.data) ? query.data?.data : []), [query]);

    if (filterGameDev) {
        channels = channels.filter((channel) => channel.assignedTarget?.targetSelectorRule?.name === 'GAME_DEV');
    }

    const { isError, error } = query;
    useEffect(() => {
        if (!isError) {
            return;
        }
        // Permission denials are expected/non-transient; let the page handle access state.
        if (isAuthzError(error)) {
            return;
        }
        createError({
            title: 'Error Fetching Channels',
            body: getErrorMessage(error),
            options: {
                id: 'get-channels-error',
            },
        });
    }, [error, isError]);

    return {
        ...query,
        data: channels,
    };
};
