import { assert, loggerManager } from '../common';
import { EventEmitter } from '../common/EventEmitter';
import { ConfigManager } from '../config';

interface PeerConnectionListeners {
    negotiationneeded?: () => void;
    connectionstatechange?: () => void;
    icecandidate?: (ev: RTCPeerConnectionIceEvent) => void;
    iceconnectionstatechange?: () => void;
    datachannel?: (evt: RTCDataChannelEvent) => void;
    signalingstatechange?: () => void;
    track?: (evt: RTCTrackEvent) => void;
}

export class RTCService extends EventEmitter<RTCServiceEventsTypeMap> {
    private dataChannels: Record<DataChannelLabel, RTCDataChannel | undefined> = {
        [DataChannelLabel.Input]: undefined,
        [DataChannelLabel.Feedback]: undefined,
    };
    private peerConnection: RTCPeerConnection | undefined = undefined;
    private readonly peerConnectionListeners: PeerConnectionListeners = {};
    private readonly log = loggerManager.getLogger('RTCService');

    public async init(): Promise<RTCSessionDescriptionInit> {
        this.log.debug('init');

        const peerConnection = this.createPeerConnection();
        const offer = await peerConnection.createOffer();
        const offerWithStereo = this.enableStereoHack(offer);
        await peerConnection.setLocalDescription(offerWithStereo);
        return offerWithStereo;
    }

    public async setRemoteDescription(offerDescription: RTCSessionDescriptionInit) {
        this.log.trace('setRemoteDescription');
        assert(this.peerConnection);
        await this.peerConnection.setRemoteDescription(offerDescription);
        await this.waitForIceGatheringState(this.peerConnection);
    }

    /**
     * Google Chrome doesn't add the ability to receive stereo audio on its generated SDP offer,
     * even though it is capable of playing stereo, and the OCGA is sending stereo audio, the fact
     * that it's not part of the SDP offer makes Chrome play mono.
     * For this reason we do this hack of munging the offer and it seems to address the issue
     */
    private enableStereoHack(offer: RTCSessionDescriptionInit): RTCSessionDescriptionInit {
        if (offer.sdp && !offer.sdp.includes('stereo=1')) {
            this.log.debug('Adding hack to enable stereo on the SDP offer');
            offer.sdp = offer.sdp.replace('useinbandfec=1', 'useinbandfec=1;stereo=1');
        }
        return offer;
    }

    private createPeerConnection(): RTCPeerConnection {
        // If there was a previous peerConnection, remove all listeners
        this.removePeerConnectionEventListeners(this.peerConnection);

        this.log.debug('Create RTCPeerConnection');
        const peerConnection = RTCPeerConnectionFactory.create({
            bundlePolicy: 'max-bundle',
        });

        peerConnection.addTransceiver('audio', {
            direction: 'recvonly',
        });
        peerConnection.addTransceiver('video', {
            direction: 'recvonly',
        });

        this.addPeerConnectionEventListeners(peerConnection);
        this.configureDataChannels(peerConnection);

        this.peerConnection = peerConnection;
        return this.peerConnection;
    }

    private addPeerConnectionEventListeners(peerConnection: RTCPeerConnection) {
        this.peerConnectionListeners.negotiationneeded = () => this.log.trace('negotiationneeded');
        peerConnection.addEventListener('negotiationneeded', this.peerConnectionListeners.negotiationneeded);

        this.log.debug(`connectionState: ${peerConnection.connectionState}`);
        this.peerConnectionListeners.connectionstatechange = () => {
            this.log.debug(`connectionState: ${peerConnection.connectionState}`);
            switch (peerConnection.connectionState) {
                case 'closed':
                    this.emitEvent('gameconnectionclosed', { type: 'gameconnectionclosed' });
                    break;
                case 'connected':
                    this.emitEvent('gameconnected', { type: 'gameconnected' });
                    break;
                case 'connecting':
                    this.emitEvent('gameconnecting', { type: 'gameconnecting' });
                    break;
                case 'disconnected':
                    this.emitEvent('gamedisconnected', { type: 'gamedisconnected' });
                    break;
                case 'failed':
                    this.emitEvent('gameconnectionfailed', { type: 'gameconnectionfailed' });
                    break;
            }
        };
        peerConnection.addEventListener('connectionstatechange', this.peerConnectionListeners.connectionstatechange);

        this.peerConnectionListeners.icecandidate = (ev: RTCPeerConnectionIceEvent) => {
            this.log.debug(`icecandidate: ${JSON.stringify(ev.candidate)}`);
        };
        peerConnection.addEventListener('icecandidate', this.peerConnectionListeners.icecandidate);

        this.log.debug(`iceconnectionstatechange: ${peerConnection.iceConnectionState}`);
        this.peerConnectionListeners.iceconnectionstatechange = () => {
            this.log.debug(`iceconnectionstatechange: ${peerConnection.iceConnectionState}`);
        };
        peerConnection.addEventListener(
            'iceconnectionstatechange',
            this.peerConnectionListeners.iceconnectionstatechange,
        );

        this.peerConnectionListeners.datachannel = (evt: RTCDataChannelEvent) => {
            this.log.debug('Setting data channel', evt.channel.id, evt.channel.label);
            this.dataChannels[evt.channel.label as DataChannelLabel] = evt.channel;
        };
        peerConnection.addEventListener('datachannel', this.peerConnectionListeners.datachannel);

        this.peerConnectionListeners.signalingstatechange = () => {
            this.log.debug(`signalingState: ${peerConnection.signalingState}`);
        };
        peerConnection.addEventListener('signalingstatechange', this.peerConnectionListeners.signalingstatechange);

        this.peerConnectionListeners.track = (evt: RTCTrackEvent) => {
            this.log.debug('Track event received');
            this.emitEvent('track', evt);
        };
        peerConnection.addEventListener('track', this.peerConnectionListeners.track);
    }

    private removePeerConnectionEventListeners(peerConnection: RTCPeerConnection | undefined) {
        if (!peerConnection) return;
        const listeners = this.peerConnectionListeners;
        if (listeners.negotiationneeded)
            peerConnection.removeEventListener('negotiationneeded', listeners.negotiationneeded);
        if (listeners.connectionstatechange)
            peerConnection.removeEventListener('connectionstatechange', listeners.connectionstatechange);
        if (listeners.icecandidate) peerConnection.removeEventListener('icecandidate', listeners.icecandidate);
        if (listeners.iceconnectionstatechange)
            peerConnection.removeEventListener('iceconnectionstatechange', listeners.iceconnectionstatechange);
        if (listeners.datachannel) peerConnection.removeEventListener('datachannel', listeners.datachannel);
        if (listeners.signalingstatechange)
            peerConnection.removeEventListener('signalingstatechange', listeners.signalingstatechange);
        if (listeners.track) peerConnection.removeEventListener('track', listeners.track);
    }

    private configureDataChannels(peerConnection: RTCPeerConnection) {
        this.dataChannels[DataChannelLabel.Input] = peerConnection.createDataChannel(DataChannelLabel.Input, {
            id: DataChannelId.Input,
            ordered: false,
            maxRetransmits: 0,
        });

        if (ConfigManager.getConfig().reportVideoFrameMetrics) {
            this.dataChannels[DataChannelLabel.Feedback] = peerConnection.createDataChannel(DataChannelLabel.Feedback, {
                id: DataChannelId.Feedback,
                ordered: false,
                maxRetransmits: 0,
            });
            this.dataChannels[DataChannelLabel.Feedback]?.addEventListener('open', () =>
                this.emitEvent('datachannelopened', {
                    type: 'datachannelopened',
                    channel: DataChannelLabel.Feedback,
                }),
            );
        }

        this.dataChannels[DataChannelLabel.Input]?.addEventListener('open', () =>
            this.emitEvent('datachannelopened', { type: 'datachannelopened', channel: DataChannelLabel.Input }),
        );
    }

    private async waitForIceGatheringState(peerConnection: RTCPeerConnection): Promise<void> {
        return new Promise((resolve) => {
            const waitForComplete = () => {
                const iceGatheringState = peerConnection?.iceGatheringState;
                this.log.debug(`iceGatheringState: ${iceGatheringState}`);
                if (iceGatheringState === 'complete') {
                    peerConnection.removeEventListener('icegatheringstatechange', waitForComplete);
                    resolve();
                }
            };
            peerConnection.addEventListener('icegatheringstatechange', waitForComplete);
            waitForComplete();
        });
    }

    public sendData(channel: DataChannelLabel, payload: ArrayBuffer | string): void {
        if (!(channel in this.dataChannels)) {
            return;
        }
        if (this.dataChannels[channel]?.readyState === 'open') {
            // biome-ignore lint/suspicious/noExplicitAny: RTCDataChannel.send accepts ArrayBuffer but TS lib.dom.d.ts is overly restrictive
            this.dataChannels[channel]?.send(payload as any);
        } else {
            const send = () => {
                // biome-ignore lint/suspicious/noExplicitAny: RTCDataChannel.send accepts ArrayBuffer but TS lib.dom.d.ts is overly restrictive
                this.dataChannels[channel]?.send(payload as any);
                this.dataChannels[channel]?.removeEventListener('open', send);
            };
            this.dataChannels[channel]?.addEventListener('open', send);
        }
    }

    public onDataMessage(channel: DataChannelLabel, callback: (data: ArrayBuffer) => void) {
        // biome-ignore lint/suspicious/noExplicitAny: game-input library expects Uint8Array wrapped data
        this.dataChannels[channel]?.addEventListener('message', (e) => callback(new Uint8Array(e.data) as any));
    }

    public async getStats(): Promise<RTCStatsReport> {
        return this.peerConnection?.getStats() ?? ({ forEach: () => {} } as unknown as RTCStatsReport);
    }

    public async getStatsReport(): Promise<string> {
        return this.getStats().then((stats) => {
            const report: Array<Record<string, RTCStats>> = [];
            stats.forEach((v) => {
                report.push({ [v.type]: v });
            });
            return JSON.stringify(report, undefined, '  ');
        });
    }

    public getConnectionState(): RTCPeerConnectionState {
        return this.peerConnection?.connectionState ?? 'closed';
    }

    public getIceConnectionState(): RTCIceConnectionState {
        return this.peerConnection?.iceConnectionState ?? 'closed';
    }

    public getSignalingState(): RTCSignalingState {
        return this.peerConnection?.signalingState ?? 'closed';
    }

    public close(): void {
        this.log.trace('close');
        Object.entries(this.dataChannels).forEach(([label, dc]) => {
            dc?.close();
            this.dataChannels[label as DataChannelLabel] = undefined;
        });

        if (this.peerConnection) {
            this.peerConnection.getTransceivers().forEach((transceiver) => {
                if (transceiver.stop) {
                    transceiver.stop();
                }
            });

            this.peerConnection.getSenders().forEach((sender) => {
                if (sender.track) {
                    sender.track.stop();
                }
            });

            this.peerConnection.close();
            this.peerConnection = undefined;
        }
    }
}

export type RTCServiceEventsTypeMap = {
    track: RTCTrackEvent;
    datachannelopened: { type: 'datachannelopened'; channel: string };
    gameconnecting: { type: 'gameconnecting' };
    gameconnected: { type: 'gameconnected' };
    gamedisconnected: { type: 'gamedisconnected' };
    gameconnectionclosed: { type: 'gameconnectionclosed' };
    gameconnectionfailed: { type: 'gameconnectionfailed' };
};

// This factory exists only to simplify mocking on tests
export const RTCPeerConnectionFactory = {
    create: (config: RTCConfiguration): RTCPeerConnection => new RTCPeerConnection(config),
};

export enum DataChannelLabel {
    Input = 'input',
    Feedback = 'feedback',
}

export enum DataChannelId {
    Input = 0,
    Feedback = 2,
}
