import { IconCloud, IconDownload, IconMoreHorizontal, IconTrashCan, IconUpload } from '@hawkins/assets';
import { Button, Menu, MenuItem, Paper, Stack, Text, Tooltip } from '@hawkins/components';
import { Colors, Dimensions, VariableUtils } from '@hawkins/variables';
import { useRef } from 'react';
import { FileInput } from '../FileInput';
import styles from './PlayerBlobItem.module.css';

interface PlayerBlobItemProps {
    name: string;
    nameMaxWidth?: number;
    revision: string;
    disabled: boolean;
    onDelete: () => void;
    onDownload: () => void;
    onReplace: (file: File) => void;
}

export const PlayerBlobItem = ({
    name,
    nameMaxWidth = 230,
    onDelete,
    disabled = false,
    onDownload,
    onReplace,
}: PlayerBlobItemProps) => {
    const inputRef = useRef<HTMLInputElement>(null);
    const nameRef = useRef(null);
    return (
        <Paper
            style={{
                backgroundColor: VariableUtils.updateAlpha(Colors.White, 0.04),
                borderRadius: 8,
            }}
        >
            <Stack gap={Dimensions.Space8} orientation='horizontal' layout={{ display: 'flex' }}>
                <Stack gap={Dimensions.Space8} orientation='horizontal' layout={{ alignItems: 'center' }}>
                    <IconCloud color={disabled ? Colors.Gray500 : undefined} size='small' />
                    <Tooltip label={name} ref={nameRef} ellipsis>
                        <Text
                            ref={nameRef}
                            colorVariant={disabled ? 'disabled' : undefined}
                            level={1}
                            noWrap
                            style={{ maxWidth: nameMaxWidth }}
                        >
                            {name}
                        </Text>
                    </Tooltip>
                </Stack>
                <div style={{ flex: 1 }} />
                <div>
                    <FileInput
                        ref={inputRef}
                        onChange={e => {
                            const file = e.target.files?.[0];
                            if (file) {
                                onReplace(file);
                                e.target.value = '';
                            }
                        }}
                    />
                    <Menu
                        disableAutoFocusOnOpen={true}
                        disableAutoFocusOnClose={true}
                        trigger={
                            <Button
                                icon={IconMoreHorizontal}
                                iconProps={{ size: 'small' }}
                                variant='icon'
                                disabled={disabled}
                                tooltipProps={{ enterDelay: 1500 }}
                            >
                                Player Blob Actions
                            </Button>
                        }
                        disabled={disabled}
                    >
                        <MenuItem onClick={() => inputRef.current?.click()} icon={IconUpload}>
                            Replace Save Data
                        </MenuItem>
                        <MenuItem onClick={onDownload} icon={IconDownload}>
                            Download Save Data
                        </MenuItem>
                        <MenuItem
                            onClick={onDelete}
                            icon={IconTrashCan}
                            classes={{
                                iconContainer: styles.deleteIconContainer,
                                icon: styles.delete,
                                labelContainer: styles.delete,
                            }}
                        >
                            Delete Save Data
                        </MenuItem>
                    </Menu>
                </div>
            </Stack>
        </Paper>
    );
};
