import { createError } from '@gsm-common/utils/toast/createError';
import { createWarning } from '@gsm-common/utils/toast/createWarning';

const WARNING_PREFIX = 'WARN_';
interface BuildStateError {
    status?: number;
    code?: string;
    title: string;
    detail: string;
    meta?: any;
}

export const useDisplayUploadStateErrors = () => {
    const showErrors = (errors: BuildStateError[]) => {
        errors.forEach(error => {
            const props = {
                title: error.title,
                body: error.detail,
                options: {
                    id: error.code,
                },
            };
            if (error.code?.startsWith(WARNING_PREFIX)) {
                createWarning(props);
            } else {
                createError(props);
            }
        });
    };

    return { showErrors };
};
