import { ErrorState, Loader } from '@hawkins/components';
import { Dimensions } from '@hawkins/variables';
import type fetch from 'cross-fetch';
import { type ReactNode, useEffect, useState } from 'react';
import { type BrowserGamingClient, GamingClientFactory } from '../../api/BrowserGamingClient';
import { MockBrowserGamingClient } from '../../mocks/MockBrowserGamingClient';
import { isMockPlayMode } from '../../mocks/isMockPlayMode';
import { GamingClientProvider } from '../../providers/GamingClientProvider/GamingClientProvider';

const getGamingClientFactory = () => {
    if (typeof window === 'undefined') {
        return;
    }

    return window['netflix']?.['GamingClientFactory'];
};

const queryParams = new URLSearchParams(window.location.search);
const getCadmiumURL = () =>
    queryParams.get('localCadmium') === 'true'
        ? 'https://local.netflix.com/playercore.js'
        : 'https://nq.prod.cloud.netflix.com/nq/cadmium/pbo_config/%5E1.0.0/player';
const getClientURL = () => {
    const queryParams = new URLSearchParams(globalThis.window.location.search);
    let buildSelector: string | undefined;
    if (queryParams.has('commit')) {
        buildSelector = `commit=${queryParams.get('commit')}`;
    } else if (queryParams.has('buildId')) {
        buildSelector = `buildId=${queryParams.get('buildId')}`;
    }
    return buildSelector
        ? `https://build.dta.netflix.com/cad/browser-gaming-client/(${buildSelector})/dist/client.js`
        : '/client.js';
};

const loadBundle = async (id: string, url: string) => {
    // allow analyzer to see bundle
    if (url === '/client.js') {
        return new Promise(async (resolve) => {
            window['netflix'] = window['netflix'] ?? {};
            window['netflix']['GamingClientFactory'] = new GamingClientFactory();
            resolve(id);
        });
    }
    return new Promise((resolve, reject) => {
        const elementAlreadyExists = !!document.getElementById(id);
        const script = document.getElementById(id) ?? document.createElement('script');
        script.addEventListener('load', resolve);
        script.addEventListener('error', reject);
        script.setAttribute('src', url);
        script.setAttribute('id', id);
        if (!elementAlreadyExists) {
            document.body.appendChild(script);
        }
    });
};

const loadMslClient = async () =>
    new Promise<typeof fetch>((resolve, reject) => {
        const videoSession = new window.netflix.player.VideoSession();
        videoSession.init((initResponse: any) => {
            if (!initResponse.success) {
                reject(initResponse.error);
                return;
            }
            resolve(initResponse['mslFetch']);
        });
    });

interface ClientLoaderProps {
    children: ReactNode;
    fetch?: typeof fetch;
}
export const ClientLoader = ({ children, fetch }: ClientLoaderProps) => {
    const [gamingClient, setGamingClient] = useState<BrowserGamingClient>();
    const [error, setError] = useState<string>();
    useEffect(() => {
        if (isMockPlayMode) {
            setGamingClient(new MockBrowserGamingClient());
            return;
        }

        const handleLoad = (mslFetch: typeof fetch) => {
            const gamingClientFactory = getGamingClientFactory();
            if (gamingClientFactory) {
                setGamingClient(gamingClientFactory.createClient(fetch ?? mslFetch));
            } else {
                setError('Failed to start gaming client');
            }
        };

        const handleError = (e: Error) => {
            setError('Failed to load gaming client');
            console.error(e);
        };

        Promise.all([loadBundle('gaming-client-js', getClientURL()), loadBundle('playercore', getCadmiumURL())])
            .then(loadMslClient)
            .then(handleLoad)
            .catch(handleError);
    }, [fetch]);

    if (gamingClient) {
        return <GamingClientProvider value={gamingClient}>{children}</GamingClientProvider>;
    } else if (error) {
        return (
            <div
                style={{
                    padding: Dimensions.Space24,
                }}
            >
                <ErrorState subtitle={error} title='Something went wrong!' />
            </div>
        );
    } else {
        return <Loader variant='linear' />;
    }
};
