import { BrowserGamingClient, type BrowserGamingClientConfig } from '../api/BrowserGamingClient';
import type { CgAppliance } from '../api/graphql_generated/schema';
import type { LoadingStep } from '../api/utils/LoadingProgressReporter';
import type { OCGAOverrides } from '../hooks/useGamingClientMonitor';

const delay = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms));

const SCRIPTED_STEPS: Array<{ step: LoadingStep; progress: number; gameLoadPercent: number }> = [
    { step: 'connecting', progress: 0.2, gameLoadPercent: 0 },
    { step: 'establishing_webrtc', progress: 0.45, gameLoadPercent: 20 },
    { step: 'loading_game', progress: 0.7, gameLoadPercent: 60 },
    { step: 'starting_stream', progress: 0.9, gameLoadPercent: 90 },
];

const STEP_LABELS: Record<LoadingStep, string> = {
    connecting: 'Connecting to server',
    establishing_webrtc: 'Establishing connection',
    loading_game: 'Loading game',
    starting_stream: 'Starting stream',
    ready: 'Ready',
};

/**
 * Fake `BrowserGamingClient` used only for local-only UI development (`VITE_MOCK_PLAY=true`), so the
 * Play page shell (header, dropdowns, dock panels, perf graph, logs) can be exercised without a real
 * OCGA session, Cadmium/MSL, or any Netflix backend. Reuses the real class's public getters/setters
 * and its `EventEmitter` plumbing (see `BrowserGamingClient`'s constructor for the `gamestatechanged`
 * bookkeeping this relies on) — only `start`/`close`/`setGameVisibility` are replaced with a scripted,
 * local-only session lifecycle. No real streamer/controller/transport code paths are touched, so there
 * is no video track — the player area intentionally stays a placeholder.
 */
export class MockBrowserGamingClient extends BrowserGamingClient {
    public async start(
        _sopAccountEmail: string,
        _sopAccountPin: string,
        _config: BrowserGamingClientConfig,
        _ocgaOverrides?: OCGAOverrides,
        _controllerEnv?: string,
        _testbedVersion?: string,
    ): Promise<CgAppliance[]> {
        const sessionId = `mock-session-${Date.now()}`;
        this.setGamePlaySessionId(sessionId);
        this.emitEvent('sessionCreate', { type: 'sessionCreate' });

        for (const { step, progress, gameLoadPercent } of SCRIPTED_STEPS) {
            await delay(280);
            this.emitEvent('loadingprogress', {
                type: 'loadingprogress',
                step,
                stepLabel: STEP_LABELS[step],
                progress,
                gameLoadPercent,
            });
        }

        this.setBeaconToken('mock-beacon-token');
        this.setGamingStartToken('mock-gaming-start-token');

        await delay(280);
        this.emitEvent('loadingprogress', {
            type: 'loadingprogress',
            step: 'ready',
            stepLabel: STEP_LABELS.ready,
            progress: 1,
            gameLoadPercent: 100,
        });
        this.emitEvent('playing', { type: 'playing' });

        return [];
    }

    public async setGameVisibility(): Promise<void> {
        // Real implementation rejects without a connected transport — mock mode never connects one.
        return Promise.resolve();
    }

    public close(): void {
        // Skip the base implementation's streamer/controller/transport teardown — none were ever
        // started in mock mode, so there's nothing real to close.
        this.setGamePlaySessionId('');
        this.setBeaconToken('');
    }
}
