import clsx from 'clsx';
import { forwardRef, type ReactNode } from 'react';
import './styles.css';

export interface LayoutProps {
    horizontal?: boolean;
    full?: boolean;
    overflowHidden?: boolean;
    children?: ReactNode;
    className?: string;
}

export const Layout = forwardRef<HTMLDivElement, LayoutProps>(
    ({ children, className, horizontal = false, full = false, overflowHidden, ...rest }, ref) => (
        <div
            ref={ref}
            className={clsx('layout', className, {
                horizontal,
                full,
                overflowHidden,
            })}
            {...rest}
        >
            {children}
        </div>
    ),
);
