import { useChannels } from '@gsm-app/hooks/useChannels';
import { useGameChannels } from '@gsm-app/routes/Play/hooks/useGameChannels';
import { createError } from '@gsm-common/utils/toast/createError';
import { createSuccess } from '@gsm-common/utils/toast/createSuccess';
import { Button, Input, Panel, PanelContent, PanelHeader, Stack } from '@hawkins/components';
import { Dimensions } from '@hawkins/variables';
import { debounce } from 'lodash-es';
import { useCallback, useState } from 'react';
import { useChannelCreate } from '@gsm-app/hooks/useChannelCreate';

const DEFAULT_CHANNEL = 'GAME_DEV';

const VALID_CHARS_MATCH_REGEX = /^[A-z0-9\u00C0-\u00ff!?@#$&()"+-]+$/;
const CHANNEL_NAME_MAX_LENGTH = 30;

interface NewChannelModalProps {
    onClose: () => void;
}

export const NewChannelModal = ({ onClose }: NewChannelModalProps) => {
    const { mutateAsync: channelCreateAsync, isPending: isCreatingChannel } = useChannelCreate();
    const [channelName, setChannelName] = useState('');
    const [validationError, setValidationError] = useState<string | undefined>();
    const { selectedGame } = useGameChannels();
    const { data: channels } = useChannels(selectedGame?.value);


    // biome-ignore lint/correctness/useExhaustiveDependencies: channels used in debounce
    const validateChannelName = useCallback(
        debounce((newChannelName: string) => {
            if (channels.map(({ name }: { name: string }) => name).includes(newChannelName)) {
                setValidationError(`Channel ${newChannelName} already exists`);
            } else if (newChannelName.length > CHANNEL_NAME_MAX_LENGTH) {
                setValidationError(`Max length is ${CHANNEL_NAME_MAX_LENGTH} characters`);
            } else if (newChannelName.length > 0 && !VALID_CHARS_MATCH_REGEX.test(newChannelName)) {
                setValidationError('Only alphanumeric characters, dashes, and underscores are allowed');
            } else {
                setValidationError(undefined);
            }
        }, 300),
        [channels],
    );

    const onCreateChannel = async () => {
        if (selectedGame?.value) {
            try {
                const { data, errors } = await channelCreateAsync({
                    gameId: selectedGame?.value,
                    name: channelName,
                });
                if (errors) {
                    errors.forEach(error => {
                        createError({
                            title: 'Error Creating Channel',
                            body: error.message,
                            options: {
                                id: 'channel-create-error',
                            },
                        });
                    });
                } else {
                    createSuccess({
                        title: 'New Channel created successfully',
                        body: data?.name,
                    });
                }
            } catch (err: any) {
                let title = 'Error Creating Channel';
                let body;
                try {
                    const errorObject = JSON.parse(err.message);
                    if (errorObject.errors) {
                        errorObject.errors.forEach((error: any, index: number) => {
                            createError({
                                title: error.message,
                                options: {
                                    id: `channel-create-error-${index}`,
                                },
                            });
                        });
                    } else {
                        if (errorObject.title) {
                            title = errorObject.title;
                        }
                        if (errorObject.message) {
                            body = errorObject.message;
                        }
                        createError({
                            title: 'Error Creating Channel',
                            body,
                            options: {
                                id: 'channel-create-error',
                            },
                        });
                    }
                } catch (error) {
                    /* Use default values if unable to parse JSON */
                }
            } finally {
                onClose();
            }
        }
    };

    return (
        <Panel open position='right' maximizable={false} minimizable={false} width={400}>
            <PanelHeader onCloseClick={onClose} title='Create New Channel' />
            <PanelContent>
                <Stack gap={Dimensions.RawSpace24}>
                    <Input
                        label='Channel Name'
                        value={channelName}
                        onChange={event => {
                            validateChannelName(event.target.value);
                            setChannelName(event.target.value);
                        }}
                        validationStatus={validationError ? 'error' : undefined}
                        validationMessage={validationError}
                    />
                    <Button disabled={isCreatingChannel || !!validationError} onClick={onCreateChannel}>
                        Create
                    </Button>
                </Stack>
            </PanelContent>
        </Panel>
    );
};
