import {
    ClientType,
    type ClientsChangeEvent,
    GameState,
    GameVisibility,
    type IClient,
    InputState,
    ProtocolState,
    newClient,
} from '@netflix-internal/nf-game-control-protocol';
import { v4 as uuid } from 'uuid';
import { assert, loggerManager } from '../common';
import { EventEmitter } from '../common/EventEmitter';
import { ConfigManager } from '../config';
import { ErrorCode } from '../error/ErrorCode';
import { ErrorReporter } from '../error/ErrorReporter';
import { type ConnectionDiagnostics, type ConnectionStage, GameError } from '../error/GameError';
import type { CgAppliance, CgControllerFeatures } from '../graphql_generated/schema';
import type { Streamer } from '../streamer';
import { PromiseTimerImpl as PromiseTimer } from '../utils/PromiseTimer';
import { Timer } from '../utils/Timer';
import type { RTCService } from './RTCService';

type PropertyChanged<T> = {
    oldValue: T;
    newValue: T;
};

interface GcpListeners {
    onSdpAnswer?: (sdp: string) => void;
    inputActive?: () => void;
    inputIdleWarning?: () => void;
    inputIdleError?: () => void;
    onClientsChange?: (event: ClientsChangeEvent) => void;
    onFailed?: (event: unknown) => void;
    gameState?: (args: PropertyChanged<GameState>) => void;
    inputState?: (args: PropertyChanged<InputState>) => void;
    progress?: (args: PropertyChanged<number>) => void;
    state?: (args: PropertyChanged<ProtocolState>) => void;
}

/**
 * GameControl manages communication with OCGA via WebSocket folowing the Game Control Protocol (GCP)
 */
export class GameControl extends EventEmitter<GameControlEventsTypeMap> {
    private readonly clientId = uuid();
    private readonly log = loggerManager.getLogger('GameControl');
    private readonly sdpDebugLog = loggerManager.getLogger('SDP');
    private gcpClient: IClient | undefined;
    private isConnected = false;
    private reconnectStart: number | undefined;
    private reconnectTimeoutId = 0;
    private readonly gcpListeners: GcpListeners = {};

    // Track current OCGA for diagnostics
    private currentOcgaUrl?: string;
    private currentOcgaUuid?: string;
    private currentOcgaShortName?: string;

    public constructor(private readonly rtcService: RTCService) {
        super();
        this.addRtcServiceEventListeners();
    }

    /** Get diagnostic information about the current connection state */
    private getDiagnostics(stage: ConnectionStage, elapsedMs?: number, timeoutMs?: number): ConnectionDiagnostics {
        return {
            stage,
            ocgaUrl: this.currentOcgaUrl,
            ocgaUuid: this.currentOcgaUuid,
            ocgaShortName: this.currentOcgaShortName,
            elapsedMs,
            timeoutMs,
            connectionState: this.rtcService.getConnectionState(),
            iceConnectionState: this.rtcService.getIceConnectionState(),
            signalingState: this.rtcService.getSignalingState(),
        };
    }

    public async connect(
        gameAppliance: CgAppliance,
        controllerFeatures: CgControllerFeatures | undefined,
        streamer: Streamer,
    ): Promise<boolean> {
        // Track OCGA info for diagnostics
        this.currentOcgaUrl = gameAppliance.hostInfo?.url ?? undefined;
        this.currentOcgaUuid = gameAppliance.gamingApplianceId;
        this.currentOcgaShortName = gameAppliance.hostInfo?.url?.split('.')[0]?.replace('wss://', '') ?? undefined;

        this.isConnected = false;
        this.gcpClient = this.createGcpClient(gameAppliance);
        streamer.startMonitor();

        const attemptStartMs = Date.now();
        try {
            await this.connectInternal(gameAppliance, controllerFeatures);
            const signalingEndMs = Date.now();

            await this.waitForWebRtcToConnect();
            const webrtcEndMs = Date.now();

            await this.waitForFirstFrame(streamer);
            const firstFrameEndMs = Date.now();

            this.emitEvent('connectionmetrics', {
                type: 'connectionmetrics',
                ocgaShortName: this.currentOcgaShortName,
                durationsMs: {
                    signalingMs: signalingEndMs - attemptStartMs,
                    webrtcMs: webrtcEndMs - signalingEndMs,
                    firstFrameMs: firstFrameEndMs - webrtcEndMs,
                    ttffMs: firstFrameEndMs - attemptStartMs,
                },
            });

            this.isConnected = true;
            return true;
        } catch (error) {
            this.rtcService.getStatsReport().then((report) => {
                this.log.debug('RTCStatsReport', report);
            });
            streamer.stopMonitor();
            this.close();
            throw error;
        }
    }

    private async connectInternal(
        gameAppliance: CgAppliance,
        controllerFeatures: CgControllerFeatures | undefined,
    ): Promise<void> {
        return PromiseTimer.resolveWithin(
            ConfigManager.getConfig().gameStartTimeout,
            this.rtcService.init().then((sdpOffer) => {
                assert(this.gcpClient, 'gcpClient is undefined');
                assert(sdpOffer.sdp, 'sdp is undefined');
                this.sdpDebugLog.trace(sdpOffer);
                this.log.debug(`Trying to connect to ${gameAppliance.hostInfo?.url}`);
                const beaconToken =
                    controllerFeatures?.mode === 'custom' ? (gameAppliance.beaconToken ?? undefined) : undefined;
                return this.gcpClient.start(sdpOffer.sdp, beaconToken); // start includes wait for connect
            }),
        ).catch((e) => {
            const diagnostics = this.getDiagnostics('signaling');
            this.log.warn('Failed to connect to signaling server', { ...diagnostics, originalError: String(e) });
            throw new GameError(
                ErrorCode.FAILED_TO_CONNECT_TO_SIGNALING_SERVER,
                'Failed to connect to signaling server',
                diagnostics,
            );
        });
    }

    private async reconnect(delay = 0): Promise<void> {
        if (!this.isConnected) {
            return;
        }

        // reconnect may be called from multiple event handlers
        // if there's a pending setTimeout call then this will
        // clear that call and execute immediately
        this.log.debug(`reconnect(${delay})`);
        this.reconnectStart ??= globalThis.Date.now();
        globalThis.clearTimeout(this.reconnectTimeoutId);
        this.reconnectTimeoutId = window.setTimeout(() => {
            this.reconnectInternal()
                .then(() => {
                    this.log.debug('reconnect: success');
                    this.reconnectStart = undefined;
                    this.reconnectTimeoutId = window.setTimeout(() => {}, 0);
                })
                .catch((e) => {
                    this.log.error(`reconnect: ${e}`);
                    const error = this.getReconnectError();
                    if (error) {
                        ErrorReporter.getInstance().report(error);
                    } else {
                        this.reconnect(1000); // Try Again
                    }
                });
        }, delay);
    }

    private async reconnectInternal(): Promise<void> {
        this.log.debug('reconnectInternal');
        return this.renegotiateInternal();
    }

    private renegotiateInternal(): Promise<void> {
        this.log.debug('renegotiateInternal');

        // gcpClient.reconnect waits for internal connection state to change
        // A promise timeout must encapsulate this call because it can resolve
        // minutes later, which will cause an issue with old sdp offers

        assert(this.gcpClient);
        return PromiseTimer.resolveWithin(4000, this.gcpClient.reconnect()).then(() => {
            this.rtcService?.init().then((offer) => {
                assert(offer.sdp);
                return this.gcpClient?.renegotiate(offer.sdp);
            });
        });
    }

    private getReconnectError(): ErrorCode | undefined {
        assert(this.reconnectStart);
        if (globalThis.Date.now() - this.reconnectStart > ConfigManager.getConfig().reconnectionTimeout) {
            return ErrorCode.CANNOT_RECONNECT;
        }
    }

    public getReceiverId(): string {
        return this.clientId;
    }

    public async close(): Promise<void> {
        this.log.trace('close');
        this.isConnected = false;
        globalThis.clearTimeout(this.reconnectTimeoutId);
        this.emitEvent('close', { type: 'close' });
        this.rtcService.close();

        if (this.gcpClient) {
            const gcpState = this.gcpClient.state.value;
            this.log.trace(`close gcpClient, state: ${ProtocolState[gcpState]}`);
            this.removeGcpListeners(this.gcpClient);
            // Don't await gcpClient.stop() as it will never
            // return if gcpClient is already in an error state
            this.gcpClient
                .stop()
                .then(() => this.log.trace('gcpClient stopped'))
                .catch((e) => this.log.trace('gcpClient stop failed', e));
            this.gcpClient = undefined;
        } else {
            this.log.trace('no gcpClient');
        }
    }

    public async setClientLimit(limit: number): Promise<void> {
        this.log.trace(`setClientLimit(${limit})`);
        return this.gcpClient?.clientLimit(limit);
    }

    public async setGameVisibility(visibility: GameVisibility): Promise<void> {
        const clientState = {
            interactive: visibility === GameVisibility.VISIBLE,
            visibility,
        };
        this.log.trace(`setClientState(${JSON.stringify(clientState)})`);
        return this.gcpClient?.setClientState(clientState);
    }

    private createGcpClient(gameAppliance: CgAppliance): IClient {
        assert(gameAppliance.gameStartToken, 'gameStartToken is undefined');
        assert(gameAppliance.hostInfo?.url, 'url is undefined');

        this.log.trace('Create GCP Client', gameAppliance.hostInfo);
        const textEncoder = new TextEncoder();
        const textDecoder = new TextDecoder();
        const gcpClient = newClient(
            gameAppliance.hostInfo?.url,
            textEncoder.encode(gameAppliance.gameStartToken),
            'Browser',
            this.clientId,
            {
                reconnectionTimeout: ConfigManager.getConfig().reconnectionTimeout,
                responseTimeout: ConfigManager.getConfig().gcpResponseTimeout,
                gameStartTimeout: ConfigManager.getConfig().gameStartTimeout,
                idleWarningTimeout: ConfigManager.getConfig().idleWarningTimeout,
                idleErrorTimeout: ConfigManager.getConfig().idleErrorTimeout,
            },
            {
                WebSocket: globalThis.WebSocket,
                atob: (input: string) => textEncoder.encode(input),
                btoa: (input: Uint8Array) => textDecoder.decode(input),
                logger: loggerManager.getLogger('GCP') as unknown as Console,
            },
            ClientType.WEB,
        );

        this.addGcpListeners(gcpClient);

        return gcpClient;
    }

    private addGcpListeners(gcp: IClient): void {
        this.gcpListeners.onSdpAnswer = (sdp: string) => {
            this.log.debug('Received SDP answer');
            const sdpAnswer = { type: 'answer' as RTCSdpType, sdp };
            this.rtcService.setRemoteDescription(sdpAnswer);
            this.emitEvent('receivedsdpanswer', { type: 'receivedsdpanswer' });
            this.sdpDebugLog.trace(sdpAnswer);
        };
        gcp.addListener('onSdpAnswer', this.gcpListeners.onSdpAnswer);

        this.gcpListeners.inputActive = () => {
            this.emitEvent('inputactive', { type: 'inputactive' });
        };
        gcp.addListener('inputActive', this.gcpListeners.inputActive);

        this.gcpListeners.inputIdleWarning = () => {
            this.emitEvent('inputidlewarning', { type: 'inputidlewarning' });
        };
        gcp.addListener('inputIdleWarning', this.gcpListeners.inputIdleWarning);

        this.gcpListeners.inputIdleError = () => {
            ErrorReporter.getInstance().report(ErrorCode.INPUT_IDLE_ERROR);
        };
        gcp.addListener('inputIdleError', this.gcpListeners.inputIdleError);

        this.gcpListeners.onClientsChange = (event: ClientsChangeEvent) => {
            this.log.trace(`gcp.onClientsChange: ${JSON.stringify(event)}`);
            this.emitEvent('clientlist', event);
        };
        gcp.addListener('onClientsChange', this.gcpListeners.onClientsChange);

        this.gcpListeners.onFailed = (event: unknown) => {
            this.log.error(`gcp.onFailed: ${JSON.stringify(event)}`);
            if (this.isConnected) {
                ErrorReporter.getInstance().report(ErrorCode.OCGA_FAILED);
            }
        };
        gcp.addListener('onFailed', this.gcpListeners.onFailed);

        this.gcpListeners.gameState = (args: PropertyChanged<GameState>) => {
            this.log.debug('gcp.gameState', {
                oldValue: GameState[args.oldValue],
                newValue: GameState[args.newValue],
            });
        };
        gcp.gameState.addListener(this.gcpListeners.gameState);

        this.gcpListeners.inputState = (args: PropertyChanged<InputState>) => {
            this.log.debug('gcp.inputState', {
                oldValue: InputState[args.oldValue],
                newValue: InputState[args.newValue],
            });
        };
        gcp.inputState.addListener(this.gcpListeners.inputState);

        this.gcpListeners.progress = (args: PropertyChanged<number>) => {
            this.log.debug(`gcp.progress: ${args.newValue}`);
            this.emitEvent('ocgaloadprogress', {
                type: 'ocgaloadprogress',
                value: args.newValue,
            });
        };
        gcp.progress.addListener(this.gcpListeners.progress);

        this.gcpListeners.state = (args: PropertyChanged<ProtocolState>) => {
            this.log.debug('gcp.state', {
                oldValue: ProtocolState[args.oldValue],
                newValue: ProtocolState[args.newValue],
            });
            switch (args.newValue) {
                // Note: GCP emits onFailed after changing ProtocolState to FAILED
                // case ProtocolState.FAILED:
                //     break;
                case ProtocolState.CLOSED:
                    if (this.isConnected) {
                        ErrorReporter.getInstance().report(ErrorCode.CONTROL_CONNECTION_ENDED);
                    }
                    this.emitEvent('gamecontrolconnectionclosed', {
                        type: 'gamecontrolconnectionclosed',
                        message: 'Connection closed',
                    });
                    break;
            }
        };
        gcp.state.addListener(this.gcpListeners.state);
    }

    private removeGcpListeners(gcp: IClient): void {
        const listeners = this.gcpListeners;
        if (listeners.onSdpAnswer) gcp.removeListener('onSdpAnswer', listeners.onSdpAnswer);
        if (listeners.inputActive) gcp.removeListener('inputActive', listeners.inputActive);
        if (listeners.inputIdleWarning) gcp.removeListener('inputIdleWarning', listeners.inputIdleWarning);
        if (listeners.inputIdleError) gcp.removeListener('inputIdleError', listeners.inputIdleError);
        if (listeners.onClientsChange) gcp.removeListener('onClientsChange', listeners.onClientsChange);
        if (listeners.onFailed) gcp.removeListener('onFailed', listeners.onFailed);
        if (listeners.gameState) gcp.gameState.removeListener(listeners.gameState);
        if (listeners.inputState) gcp.inputState.removeListener(listeners.inputState);
        if (listeners.progress) gcp.progress.removeListener(listeners.progress);
        if (listeners.state) gcp.state.removeListener(listeners.state);
    }

    private addRtcServiceEventListeners() {
        this.rtcService.addEventListener('gameconnectionfailed', () => {
            this.reconnect();
        });
    }

    private waitForWebRtcToConnect(): Promise<void> {
        let timeoutId = 0;
        const timer = new Timer();
        return new Promise<void>((resolve, reject) => {
            const success = () => {
                removeListeners();
                const elapsedMs = timer.getElapsedMilliseconds();
                this.log.trace(`waitForWebRtcToConnect=${(elapsedMs / 1000).toFixed(2)}s (${elapsedMs}ms)`);
                resolve();
            };

            const failure = () => {
                removeListeners();
                const elapsed = timer.getElapsedMilliseconds();
                const diagnostics = this.getDiagnostics('webrtc', elapsed);
                this.log.warn('WebRTC connection failed', diagnostics);
                reject(
                    new GameError(
                        ErrorCode.COULD_NOT_CONNECT_TO_ANY_SIGNALING_SERVER,
                        'WebRTC connection failed',
                        diagnostics,
                    ),
                );
            };

            const timeout = () => {
                removeListeners();
                const elapsed = timer.getElapsedMilliseconds();
                const timeoutMs = ConfigManager.getConfig().gameStartTimeout;
                const diagnostics = this.getDiagnostics('webrtc', elapsed, timeoutMs);
                this.log.warn('WebRTC connection timeout', diagnostics);
                reject(
                    new GameError(
                        ErrorCode.TIMEOUT_ESTABLISHING_CONNECTION,
                        'WebRTC connection timed out',
                        diagnostics,
                    ),
                );
            };

            const removeListeners = () => {
                this.rtcService.removeEventListener('gameconnected', success);
                this.rtcService.removeEventListener('gameconnectionfailed', failure);
                clearTimeout(timeoutId);
            };

            const connectionState = this.rtcService.getConnectionState();
            if (connectionState === 'connected') {
                return resolve();
            }

            this.rtcService.addEventListener('gameconnected', success);
            this.rtcService.addEventListener('gameconnectionfailed', failure);
            timeoutId = window.setTimeout(timeout, ConfigManager.getConfig().gameStartTimeout);
        });
    }

    private waitForFirstFrame(streamer: Streamer): Promise<void> {
        let timeoutId = 0;
        const timer = new Timer();
        return new Promise<void>((resolve, reject) => {
            const success = () => {
                const elapsedMs = timer.getElapsedMilliseconds();
                this.log.trace(`waitForFirstFrame=${(elapsedMs / 1000).toFixed(2)}s (${elapsedMs}ms)`);
                removeListeners();
                resolve();
            };

            const failure = () => {
                removeListeners();
                const elapsed = timer.getElapsedMilliseconds();
                const diagnostics = this.getDiagnostics('first_frame', elapsed);
                this.log.warn('Failed to receive first frame', diagnostics);
                reject(new GameError(ErrorCode.GAME_FAILED_TO_START, 'Failed to receive first frame', diagnostics));
            };

            const timeout = () => {
                removeListeners();
                const elapsed = timer.getElapsedMilliseconds();
                const timeoutMs = ConfigManager.getConfig().renderFrameTimeout;
                const diagnostics = this.getDiagnostics('first_frame', elapsed, timeoutMs);
                this.log.warn('Timeout waiting for first frame', diagnostics);
                reject(new GameError(ErrorCode.GAME_FAILED_TO_START, 'Timeout waiting for first frame', diagnostics));
            };

            const removeListeners = () => {
                streamer.removeEventListener('firstframe', success);
                this.gcpClient?.removeListener('onFailed', failure);
                clearTimeout(timeoutId);
            };

            streamer.addEventListener('firstframe', success);
            this.gcpClient?.addListener('onFailed', failure);
            timeoutId = window.setTimeout(timeout, ConfigManager.getConfig().renderFrameTimeout);
        });
    }
}

export type GameControlEventsTypeMap = {
    gamecontrolconnectionestablished: {
        type: 'gamecontrolconnectionestablished';
    };
    requestedstream: { type: 'requestedstream' };
    receivedsdpanswer: { type: 'receivedsdpanswer' };
    sentsdpoffer: { type: 'sentsdpoffer' };
    gamecontrolconnectionclosed: {
        type: 'gamecontrolconnectionclosed';
        message: string;
    };
    ocgaloadprogress: { type: 'ocgaloadprogress'; value: number };
    inputactive: { type: 'inputactive' };
    inputidlewarning: { type: 'inputidlewarning' };
    close: { type: 'close' };
    clientlist: ClientsChangeEvent;
    connectionmetrics: {
        type: 'connectionmetrics';
        ocgaShortName?: string;
        durationsMs: {
            signalingMs: number;
            webrtcMs: number;
            firstFrameMs: number;
            ttffMs: number;
        };
    };
};

export enum GameControlConnectionStatus {
    Connected = 'connected',
    WebSocketDisconnected = 'WebSocketDisconnected',
    WebRtcFailed = 'WebRtcFailed',
    WebRtcDisconnected = 'WebRtcDisconnected',
}
