import { loggerManager } from '../common';
import * as input from './Input';
import type { InputDevice } from './InputDevice';

export class MouseInput implements InputDevice {
    private readonly events: Array<keyof HTMLElementEventMap> = ['mouseup', 'mousedown', 'mousemove'];
    private readonly log = loggerManager.getLogger('MouseInput');
    private readonly device: input.Device;

    public constructor(private readonly eventsTarget: EventTarget) {
        this.device = input.Device.create(0, 0, 'Mouse', [
            new input.Abs(input.Code.ABS_X, 0, 1280),
            new input.Abs(input.Code.ABS_Y, 0, 720),
            new input.Key(input.Code.BTN_LEFT),
            new input.Key(input.Code.BTN_RIGHT),
            new input.Key(input.Code.BTN_MIDDLE),
        ]);
    }

    public getInputDevice(): input.Device {
        return this.device;
    }

    public start(): void {
        this.log.trace('Subscribing to mouse events', this.events);

        this.eventsTarget.addEventListener('contextmenu', this.handleContextMenu);

        this.events.forEach((mouseEvent) =>
            this.eventsTarget.addEventListener(mouseEvent, this.handleMouseEvent as (e: Event) => void),
        );
    }

    public close(): void {
        this.log.trace('Unsubscribing from mouse events', this.events);

        this.eventsTarget.removeEventListener('contextmenu', this.handleContextMenu);

        this.events.forEach((mouseEvent) =>
            this.eventsTarget.removeEventListener(mouseEvent, this.handleMouseEvent as (e: Event) => void),
        );
    }

    private readonly handleContextMenu = (event: { preventDefault: () => void }) => {
        event.preventDefault();
    };

    private readonly handleMouseEvent = (e: MouseEvent) => {
        try {
            const [normalizedX, normalizedY] = this.normalizeCoordinates(e);
            e.preventDefault();
            this.device.setAbs(input.Code.ABS_X, normalizedX, true);
            this.device.setAbs(input.Code.ABS_Y, normalizedY, true);

            if (e.type === 'mousedown' || e.type === 'mouseup') {
                this.device.setKey(
                    [input.Code.BTN_LEFT, input.Code.BTN_MIDDLE, input.Code.BTN_RIGHT][e.button],
                    e.type === 'mousedown',
                );
            }
            this.device.pushStates();
        } catch (e) {
            // Coordinates are outside video boundaries, don't do anything
        }
    };

    private normalizeCoordinates(mouseEvent: MouseEvent): [number, number] {
        const target = mouseEvent.target as HTMLVideoElement;
        const elementAspectRatio = target.offsetWidth / target.offsetHeight;
        const videoAspectRatio = target.videoWidth / target.videoHeight;

        let normalizedX = Math.round((mouseEvent.offsetX / target.offsetWidth) * target.videoWidth);
        let normalizedY = Math.round((mouseEvent.offsetY / target.offsetHeight) * target.videoHeight);

        if (elementAspectRatio < videoAspectRatio) {
            // Extra vertical space
            const actualVideoHeight = (target.offsetWidth / target.videoWidth) * target.videoHeight;
            const margin = (target.offsetHeight - actualVideoHeight) / 2;
            if (mouseEvent.offsetY < margin || mouseEvent.offsetY > target.offsetHeight - margin) {
                // Out of video content, ignore event
                throw new Error('Event happened outside video boundaries');
            }
            normalizedY = Math.round(((mouseEvent.offsetY - margin) / actualVideoHeight) * target.videoHeight);
        } else if (elementAspectRatio > videoAspectRatio) {
            // Extra horizontal space
            const actualVideoWidth = (target.offsetHeight / target.videoHeight) * target.videoWidth;
            const margin = (target.offsetWidth - actualVideoWidth) / 2;
            if (mouseEvent.offsetX < margin || mouseEvent.offsetX > target.offsetWidth - margin) {
                // Out of video content, ignore event
                throw new Error('Event happened outside video boundaries');
            }
            normalizedX = Math.round(((mouseEvent.offsetX - margin) / actualVideoWidth) * target.videoWidth);
        }

        return [normalizedX, normalizedY];
    }
}
