import { useMutation } from '@apollo/client';
import { consumerClient, getConsumerHeaders } from '../graphql/client';
import { graphql } from '../graphql/generated';

const REDEEM_BEACON_MUTATION = graphql(`
    mutation RedeemBeacon ($beaconCode: String!, $secondScreenDeviceRegistrationToken:String) {
        ngpRedeemBeacon(beaconCode: $beaconCode, secondScreenDeviceRegistrationToken:$secondScreenDeviceRegistrationToken) {
            ...on NGPRedeemBeaconSuccess {
                gameId
                gameplaySessionId
                connectionSecret
                connectionUrl
                controllerUiParameters {
                    key,
                    value
                },
                controllerUiUrl
            }

            ...on NGPRedeemBeaconFailed{
                reason
            }
        }
    }
`);

export const useControllerBeacon = ({ passport }: { passport: string}) =>
    useMutation(
        REDEEM_BEACON_MUTATION,
        {
            client: consumerClient,
            context: {
                headers: getConsumerHeaders(passport),
            }
        }
    );
