import { useEffect, useRef } from 'react';
import { useLocation } from 'react-router-dom';

export const useRouteChange = (callback: Function, depth?: number) => {
    const { pathname } = useLocation();
    const from = useRef(pathname);
    useEffect(() => {
        const to = pathname;
        if (to !== from.current) {
            // full path
            if (depth === undefined) {
                if (to !== from.current) {
                    callback();
                    return;
                }
            }
            // check depth
            else {
                const prev = from.current.split('/');
                const next = to.split('/');

                if (prev.length !== next.length || !prev.slice(0, depth + 1).every((value, i) => value === next[i])) {
                    callback();
                    return;
                }
            }
        }
    }, [pathname, from, callback, depth]);
};
