import fetch from 'cross-fetch';
import { loggerManager } from '../common';
import type { CgStartGameSuccess } from '../graphql_generated/schema';
import type { OCGAOverrides } from '../../hooks/useGamingClientMonitor';

type Env = {
    key: string;
    value: string;
};

interface GameStartResponse {
    data: {
        cg_startGame: CgStartGameSuccess;
        sessionId: string;
    };
    errors?: {
        status: number;
        code: string;
        title: string;
        detail: string;
    }[];
}

export class StartGameError extends Error {
    title: string;
    constructor(message: string, title?: string) {
        super(message);
        this.name = 'StartGameError';
        this.title = title ?? this.name;
    }
}

export class BuildSelectionMismatchError extends Error {
    title: string;
    constructor(message: string, title?: string) {
        super(message);
        this.name = 'BuildSelectionMismatchError';
        this.title = title ?? this.name;
    }
}

export class ControlPlane {
    private readonly httpClient: typeof fetch;
    private readonly log = loggerManager.getLogger('ControlPlane');

    public constructor(customFetch = fetch) {
        this.httpClient = customFetch;
    }

    public async createSessionId(gameId: number): Promise<{ sessionId: string }> {
        return this.httpClient(`/api/games/${gameId}/create-session`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
        }).then((r) => r.json());
    }

    public async startGame(
        gameId: number,
        channelId: string,
        channelName: string,
        buildId: string,
        gameplaySessionId: string,
        sopAccountEmail: string,
        sopAccountPin: string,
        ocgaOverrides?: OCGAOverrides,
        controllerEnv?: string,
        testbedVersion?: string,
    ) {
        this.log.trace('Requesting GST');

        const response = (await (
            await this.httpClient(`/api/games/${gameId}/start`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    buildId,
                    channelId,
                    channelName,
                    gameplaySessionId,
                    sopAccountEmail,
                    sopAccountPin,
                    ocgaOverrides,
                    controllerEnv,
                    testbedVersion,
                }),
            })
        ).json()) as GameStartResponse;

        if (response.errors) {
            const err = response.errors[0];
            throw new StartGameError(err.detail, err.title);
        }

        return response.data;
    }
}
