import { Input, type InputProps } from '@hawkins/components';
import type { ChangeEvent } from 'react';
import { Controller, type FieldPath, type FieldValues, useFormContext } from 'react-hook-form';

export interface InputFieldProps<T extends FieldValues> extends Omit<InputProps, 'value'> {
    name: FieldPath<T>;
    disabled?: boolean;
    transformValue?: (value: string) => string;
}

export const InputField = <T extends FieldValues>({ name, disabled, transformValue, ...rest }: InputFieldProps<T>) => {
    const { control } = useFormContext();

    return (
        <Controller
            name={name}
            control={control}
            render={({ field: { onChange, onBlur, value, name, ref }, fieldState: { error } }) => (
                <Input
                    inputRef={ref}
                    name={name}
                    disabled={disabled}
                    compact
                    {...(rest.type === 'file' ? {} : { value })}
                    {...rest}
                    onChange={(event: ChangeEvent<HTMLInputElement>) => {
                        if (rest.type === 'file') {
                            return onChange(event.target.files);
                        }
                        const value = event.currentTarget.value;
                        const target = { value: transformValue?.(value) ?? value };
                        onChange({ currentTarget: target, target, event });
                    }}
                    onBlur={onBlur}
                    validationStatus={error ? 'error' : undefined}
                    validationMessage={error?.message}
                />
            )}
        />
    );
};
