import { APP_NAME, ROUTE_ADMIN, ROUTE_LOGS, ROUTE_NETWORK, ROUTE_PLAY, ROUTE_SESSIONS, ROUTE_TESTS } from '@gsm-app/constants';
import { useWebRTCDetection } from '@gsm-app/hooks/useWebRTCDetection';
import { useModal } from '@gsm-app/providers/ModalProvider';
import { NotificationsMenuButton } from '@gsm-common/components/NotificationsMenuButton';
import { AssumedIdentitiesUserMenu } from '@hawkins-community/assumed-identities';
import {
    IconBrightnessHigh,
    IconBug,
    IconChatBubbles,
    IconCircleExclamationPoint,
    IconEmployeeBadge,
    IconGlobe,
    IconGraphBar,
    IconLabFlask,
    IconMoon,
    IconPlay,
    IconSeries,
    IconUpload,
} from '@hawkins/assets';
import {
    AppLogo,
    Button,
    ButtonGroup,
    NavigationMenuGroup,
    NavigationMenuItem,
    NavigationQuickAction,
    NavigationQuickActionGroup,
    NavigationUserControls,
    Tooltip,
    VerticalNavigation,
    useHawkinsContext,
} from '@hawkins/components';
import { useGamingClient } from '@ncgt/player';
import { useQuery } from '@tanstack/react-query';
import { useCallback } from 'react';
import { Link, type Location, useLocation } from 'react-router-dom';
import styles from './AppMenu.module.css';

import { useFeature } from '@gsm-app/hooks/useFeature';
import { useDevToolsProvider } from '@gsm-app/providers/DevToolsProvider';
import { useIdentity } from '@gsm-app/providers/IdentityProvider';
import { useTelemetry } from '@ui-paved-road/telemetry/react';
import { Role } from '@ncgt/common/models/identity';

const isLinkActive = (location: Location, url: string): boolean => {
    const { pathname } = location;
    if (url === '/') {
        return url === pathname;
    }
    return pathname.startsWith(url);
};

export const AppMenu = () => {
    const telemetry = useTelemetry();
    telemetry.setLoggingTag('ncgtPortal', 'AppMenu');
    const { identity } = useIdentity();
    const webRTCDetection = useWebRTCDetection();
    const gamingClient = useGamingClient();
    const location = useLocation();
    const { headless, networkValidation, networkReport, crashDashboard, testExecutions } = useFeature();
	const { toggleDevTools } = useDevToolsProvider();

    const { theme, setTheme } = useHawkinsContext();
    const { showModal } = useModal();

    const devMode = process.env.NODE_ENV === 'development';

    const handleToggleTheme = useCallback(() => {
        const newTheme = theme === 'light' ? 'dark' : 'light';
        localStorage.setItem('theme', newTheme);
        setTheme(newTheme);
    }, [setTheme, theme]);

    const handleToggleDevTools = useCallback(() => {
        toggleDevTools();
    }, [toggleDevTools]);

    const { data: systemData } = useQuery<{ db: string }>({
        queryKey: ['system'],
        queryFn: () => fetch('/api/system').then(response => response.json()),
        enabled: identity.roles.has(Role.NCGT_ADMIN),
    });

    const infoTooltip = {
        label: ['Browser', 'Gaming Client Version'],
        description: [webRTCDetection, gamingClient.version],
    };

    if (systemData) {
        infoTooltip.label.push('Db');
        infoTooltip.description.push(systemData.db);
    }

    // Do not render the AppMenu for headless mode
    if (headless || networkReport) {
        return null;
    }

    return (
        <VerticalNavigation
            collapsible
            defaultOpen={false}
            logo={
                <AppLogo
                    name={APP_NAME}
                    classes={{ 'appName': styles.appName }}
                    studioLogo
                    translate={{ 'appLogo.netflix.studio': APP_NAME }}
                />
            }
            quickActions={
                <NavigationQuickActionGroup>
                    <NavigationQuickAction
                        icon={IconUpload}
                        variant='secondary'
                        onClick={() => showModal('uploadBuild')}
                    >
                        Upload Build
                    </NavigationQuickAction>
                </NavigationQuickActionGroup>
            }
            stickyCollapseControl
            userControls={
                <NavigationUserControls
                    actions={
                        <ButtonGroup>
                            <Button
                                compact
                                variant='icon'
                                icon={theme === 'light' ? IconBrightnessHigh : IconMoon}
                                onClick={handleToggleTheme}
                            >
                                Switch Theme
                            </Button>
                            {devMode && (
                                <Button compact variant='icon' icon={IconBug} onClick={handleToggleDevTools}>
                                    Toggle Dev Tools
                                </Button>
                            )}
                            <Button compact variant='icon' icon={IconChatBubbles} onClick={() => showModal('feedback')}>
                                Give Feedback
                            </Button>
                            <Tooltip label={infoTooltip.label} description={infoTooltip.description}>
                                <Button compact icon={IconCircleExclamationPoint} variant='icon' aria-label='app info' />
                            </Tooltip>
                            <NotificationsMenuButton onClick={() => showModal('notifications')} />
                        </ButtonGroup>
                    }
                    userMenu={
                        <AssumedIdentitiesUserMenu
                            name={identity.details.username.charAt(0)}
                            menuProps={{
                                showCaret: false,
                            }}
                            avatarProps={{
                                variant: 'avatar-only',
                            }}
                        />
                    }
                />
            }
        >
            <NavigationMenuGroup collapsedLabel=' ' label=' '>
                <NavigationMenuItem
                    icon={IconPlay}
                    active={isLinkActive(location, ROUTE_PLAY)}
                    to={`${ROUTE_PLAY}${location.search}`}
                    component={Link}
                >
                    Play
                </NavigationMenuItem>
                <NavigationMenuItem
                    icon={IconSeries}
                    active={isLinkActive(location, ROUTE_SESSIONS)}
                    to={`${ROUTE_SESSIONS}${location.search}`}
                    component={Link}
                >
                    Session Viewer
                </NavigationMenuItem>
                {crashDashboard && (
                    <NavigationMenuItem
                        icon={IconGraphBar}
                        active={isLinkActive(location, ROUTE_LOGS)}
                        to={`${ROUTE_LOGS}${location.search}`}
                        component={Link}
                    >
                        Crash Dashboard
                    </NavigationMenuItem>
                )}
                {testExecutions && (
                    <NavigationMenuItem
                        icon={IconLabFlask}
                        active={isLinkActive(location, ROUTE_TESTS)}
                        to={`${ROUTE_TESTS}${location.search}`}
                        component={Link}
                    >
                        Test Executions
                    </NavigationMenuItem>
                )}
                {networkValidation && (

                    <NavigationMenuItem
                    icon={IconGlobe}
                    active={isLinkActive(location, ROUTE_NETWORK)}
                    to={`${ROUTE_NETWORK}${location.search}`}
                    component={Link}
                    >
                        Network Validation
                    </NavigationMenuItem>
                )}
                {identity.roles.has(Role.NCGT_ADMIN) && (
                    <NavigationMenuItem
                        icon={IconEmployeeBadge}
                        active={isLinkActive(location, ROUTE_ADMIN)}
                        to={`${ROUTE_ADMIN}${location.search}`}
                        component={Link}
                    >
                        Admin
                    </NavigationMenuItem>
                )}
            </NavigationMenuGroup>
        </VerticalNavigation>
    );
};
