import type { DropdownOption } from '@hawkins/components';
import { createContext, useContext } from 'react';

export type SopAccountType = DropdownOption<string> & {
    pin: string;
};

export interface SopAccountContextValue {
    savedAccounts: SopAccountType[];
    setSavedAccounts: (value: SopAccountType[]) => void;
    selectedAccount: SopAccountType | undefined;
    setSelectedAccount: (value: SopAccountType | undefined) => void;
    isLoading: boolean;
}

const context = createContext<SopAccountContextValue>({} as SopAccountContextValue);
export const SopAccountProvider = context.Provider;
export const useSopAccounts = () => useContext(context);
