import { ConfigManager } from '../config';
import type { Transport } from '../transport';
import { DataChannelLabel } from '../transport/RTCService';

export class PlaybackStatusReporter {
    private framesMetadata: Array<VideoFrameCallbackMetadata> = [];
    private readonly maxFramesPerMessage: number;

    public constructor(private readonly transport: Transport) {
        const config = ConfigManager.getConfig();
        this.maxFramesPerMessage = config.playbackStatusReportBatchedFrames;
        this.init();
    }

    public report(videoFrameMetadata: VideoFrameCallbackMetadata): void {
        this.framesMetadata.push(videoFrameMetadata);
        if (this.framesMetadata.length >= this.maxFramesPerMessage) {
            this.sendReport();
        }
    }

    public init(): void {
        this.framesMetadata = [];
    }

    public close(): void {
        if (this.framesMetadata.length > 0) {
            this.sendReport();
        }
    }

    private sendReport(): void {
        this.transport.sendData(DataChannelLabel.Feedback, this.buildMessage());
        this.framesMetadata = [];
    }

    /**
     * Message Format
     *
     * In order to reduce the message size, we apply a delta encoding for all the timestamps. The first 8
     * octets provide the two baseline timestamps.
     *
     * First Frame Timestamp (32 bits): This is the rtp timestamp for the first frame in the message.
     *                                  This is provided as the field ‘rtpTimestamp’ in the requestVideoFrameCallback API.
     *
     * First Frame Receive Time (32 bits): This is the receive time of the first frame in the message.
     *                                     The receive time is provided as the field ‘receiveTime’ in the requestVideoFrameCallback API.
     *
     * The following 16 bits records the number of frames in this message, which is followed by 16 unused bits.
     *
     * Each frame consists of 4 data points. Each data point is 16 bits, making it 8 bytes for each frame.
     *
     * Frame Timestamp Offset (16 bits): The rtp timestamp of this frame, as an offset after the first frame timestamp.
     * Receive Time Offset (16 bits): The receive time of this frame, as an offset after the first frame receive time.
     * Release for Render (16 bits): The time when this frame is submitted to the render, as an offset after the first
     *                               frame receive time. This time is provided as the field presentationTime in the
     *                               requestVideoFrameCallback API.
     * Render Time Offset (16 bits): The time when this frame is rendered, as an offset after the first frame receive time.
     *                               This time is provided as the field expectedDisplayTime in the requestVideoFrameCallback API.
     *
     * Spec: https://docs.google.com/document/d/1y7ajr3OXf6dcII_v9NlQiYIzXBIGYGCnZKSnfZ-0Lqg/edit#
     */
    private buildMessage(): ArrayBuffer {
        if (this.framesMetadata.length === 0) {
            throw new Error('Empty message');
        }
        const messageSize = 12 + 8 * this.framesMetadata.length;
        const message = new DataView(new ArrayBuffer(messageSize));

        let byteOffset = 0;
        // First Frame Timestamp
        const firstFrameTimestamp = Math.trunc(this.framesMetadata[0].rtpTimestamp!);
        message.setUint32(byteOffset, firstFrameTimestamp);
        byteOffset += 4;

        // First Frame Receive Time
        const firstFrameReceiveTime = Math.trunc(this.framesMetadata[0].receiveTime!);
        message.setUint32(byteOffset, firstFrameReceiveTime);
        byteOffset += 4;

        // Number of frames
        message.setUint16(byteOffset, this.framesMetadata.length);
        byteOffset += 2;

        // Unused 16 bits
        byteOffset += 2;

        this.framesMetadata.forEach(frame => {
            // Frame Timestamp Offset
            message.setUint16(byteOffset, frame.rtpTimestamp! - firstFrameTimestamp);
            byteOffset += 2;

            // Receive Time Offset
            message.setUint16(byteOffset, frame.receiveTime! - firstFrameReceiveTime);
            byteOffset += 2;

            // Release for Render
            message.setUint16(byteOffset, frame.presentationTime - firstFrameReceiveTime);
            byteOffset += 2;

            // Render Time Offset
            message.setUint16(byteOffset, frame.expectedDisplayTime - firstFrameReceiveTime);
            byteOffset += 2;
        });

        return message.buffer;
    }
}
