import { Content } from '@gsm-common/components/Content';

import type { PropsWithChildren } from 'react';
import { Suspense } from 'react';

export const LazyContent = ({
    loadingMessage = 'Loading...',
    children,
}: PropsWithChildren<{ loadingMessage?: string }>) => {
    return <Suspense fallback={<Content>{loadingMessage}</Content>}>{children}</Suspense>;
};
