import { Input as HawkinsInput, type InputProps as HawkinsInputProps } from '@hawkins/components';
import { type ClipboardEvent, forwardRef, type KeyboardEvent } from 'react';

export const Input = forwardRef<HTMLElement, HawkinsInputProps>((props, ref) => {
    const inputProps = props.inputProps;
    const onKeyPress = (e: KeyboardEvent<HTMLInputElement>) => {
        if (e.key === 'Enter') {
            return;
        }
        if (inputProps) {
            const pattern = inputProps.pattern instanceof RegExp ? inputProps.pattern : new RegExp(inputProps.pattern);
            const value = e.target instanceof HTMLInputElement ? e.target.value : '';

            if (!pattern.test(e.key) || value.length + 1 > (inputProps.max || Infinity)) {
                e.preventDefault();
            }
        }
        props.onKeyPress?.(e);
    };

    const onPaste = (e: ClipboardEvent<HTMLInputElement>) => {
        if (inputProps) {
            const pattern =
                inputProps.pattern instanceof RegExp ? inputProps.pattern : new RegExp(`^${inputProps.pattern}+$`);

            const paste = e.clipboardData.getData('Text');

            if (!pattern.test(paste) || paste.length > (inputProps.max || Infinity)) {
                e.preventDefault();
            }
        }

        props.onPaste?.(e);
    };
    return (
        <HawkinsInput
            {...props}
            ref={ref}
            onMouseUp={e => e.preventDefault()}
            onKeyPress={onKeyPress}
            onPaste={onPaste}
        />
    );
});
