import type { GameVisibility } from '@netflix-internal/nf-game-control-protocol';
import fetch from 'cross-fetch';
import type { OCGAOverrides } from '../hooks/useGamingClientMonitor';
import { type LogEntry, type LogFilters, loggerManager } from './common';
import { EventEmitter } from './common/EventEmitter';
import { Controller } from './controller';
import { ControlPlane } from './controlplane/ControlPlane';
import { ErrorCode } from './error/ErrorCode';
import type { ErrorTypeMap } from './error/ErrorReporter';
import { GameError } from './error/GameError';
import type { CgAppliance } from './graphql_generated/schema';
import { Streamer, type StreamerEventsTypeMap } from './streamer';
import { Transport, type TransportEventsTypeMap } from './transport';
import { type LoadingProgressEventsTypeMap, LoadingProgressReporter } from './utils/LoadingProgressReporter';
import { UIEventManager, type UIEventsTypeMap } from './utils/UIEventManager';
import { version } from './version.json';

export type Game = {
    name: string;
    gameId: number;
    branches: Record<string, string>;
    names?: Record<string, string>;
};

export type Env = {
    key: string;
    value: string;
};

export type PlayerMetricEvent = {
    type: 'playermetric';
    name: string;
    valueMs: number;
    metadata: {
        gameId: number;
        buildId: string;
        ocgaShortName?: string;
    };
};

export class BrowserGamingClient extends EventEmitter<PublicEventsMap> {
    public get version(): string {
        return version;
    }

    public getGamePlaySessionId() {
        return this.gameplaySessionId;
    }
    public setGamePlaySessionId(id: string) {
        this.gameplaySessionId = id;
    }
    public getGamingStartToken() {
        return this.gamingStartToken;
    }
    public setGamingStartToken(gst: string) {
        this.gamingStartToken = gst;
    }
    public getBeaconToken() {
        return this.beaconToken;
    }
    public setBeaconToken(beaconToken: string) {
        this.beaconToken = beaconToken;
    }
    public getQrCodeConfig() {
        return this.qrCodeConfig;
    }
    public setQrCodeConfig(conf: string) {
        this.qrCodeConfig = conf;
    }

    public getGameId() {
        return this.gameId;
    }
    public setGameId(id: number) {
        this.gameId = id;
    }

    public getChannelId() {
        return this.channelId;
    }
    public setChannelId(id: string) {
        this.channelId = id;
    }

    public getChannelName() {
        return this.channelName;
    }
    public setChannelName(name: string) {
        this.channelName = name;
    }

    public getBuildId() {
        return this.buildId;
    }
    public setBuildId(id: string) {
        this.buildId = id;
    }

    public getGamingAppliance() {
        return this.gameAppliance;
    }
    public setGamingAppliance(gameAppliance: CgAppliance) {
        this.gameAppliance = gameAppliance;
    }

    private gameplaySessionId = '';
    private gamingStartToken = '';
    private beaconToken = '';
    private gameId = 0;
    private buildId = '';
    private channelId = '';
    private channelName = '';
    private qrCodeConfig = '';
    private gameAppliance: CgAppliance | null = null;
    private abort = false;
    private readonly transport = new Transport();
    private readonly streamer = new Streamer(this.transport);
    private readonly controller = new Controller(this.transport);
    private readonly loadingProgressReporter = new LoadingProgressReporter(this.transport, this.streamer);
    private readonly uiEventManager = new UIEventManager(this.controller);
    private readonly controlPlane: ControlPlane;
    private gameState: GameStateEnum = GameStateEnum.preGameStart;

    private readonly log = loggerManager.getLogger('BrowserGamingClient');

    public constructor(customFetch?: typeof fetch) {
        super();

        this.controlPlane = new ControlPlane(customFetch);

        this.log.debug(`Client version ${this.version}`);

        // this.forwardEvents(this.streamer, ['autoplayblocked', 'playing']);
        // this.forwardEvents(this.loadingProgressReporter, ['loadingprogress']);
        // this.forwardEvents(this.uiEventManager, ['togglemenu']);
        // this.forwardEvents(this.transport, ['gamecontrolconnectionerror']);

        this.forwardEvents(this.streamer, ['autoplayblocked', 'background', 'frozen', 'play', 'playing']);
        this.forwardEvents(this.loadingProgressReporter, ['loadingprogress']);
        this.forwardEvents(this.uiEventManager, ['togglemenu', 'toggledebug']);
        this.forwardEvents(this.transport, ['clientlist', 'inputactive', 'inputidlewarning']);
        // this.forwardEvents(this.errorReporter, ['error']);
        loggerManager.onLog((logEntry: LogEntry) => this.emitEvent('log', { type: 'log', logEntry }));

        // Connection performance metrics (emitted by GameControl via Transport)
        this.transport.addEventListener('connectionmetrics', (event) => {
            const { ocgaShortName, durationsMs } = event;
            const metadata = {
                gameId: this.getGameId(),
                buildId: this.getBuildId(),
                ocgaShortName,
            };

            this.emitEvent('playermetric', {
                type: 'playermetric',
                name: 'player.stage.signaling_ms',
                valueMs: durationsMs.signalingMs,
                metadata,
            });
            this.emitEvent('playermetric', {
                type: 'playermetric',
                name: 'player.stage.webrtc_ms',
                valueMs: durationsMs.webrtcMs,
                metadata,
            });
            this.emitEvent('playermetric', {
                type: 'playermetric',
                name: 'player.stage.first_frame_ms',
                valueMs: durationsMs.firstFrameMs,
                metadata,
            });
            this.emitEvent('playermetric', {
                type: 'playermetric',
                name: 'player.ttff_ms',
                valueMs: durationsMs.ttffMs,
                metadata,
            });
        });

        // Update GameState
        this.addEventListener('background', () => {
            this.setGameState(GameStateEnum.background);
        });
        this.addEventListener('frozen', () => {
            this.setGameState(GameStateEnum.frozen);
        });
        this.addEventListener('playing', () => {
            this.setGameState(GameStateEnum.playing);
        });
    }

    /**
     * Return stats about current webRTC connection
     * @returns {RTCStatsReport} peer connection stats
     */
    public async getRTCStats(): Promise<RTCStatsReport> {
        return this.transport.getRTCStats();
    }

    /*
     *
     * @returns DisplayGameState
     *
     * https://stash.corp.netflix.com/pages/CL/cl-types/master/browse/docs/enums/cl.game.cloud.gamestate.html
     */
    public getGameState(): GameState {
        return GameStateEnum[this.gameState] as GameState;
    }

    private setGameState(gameState: GameStateEnum): void {
        this.log.debug(`gameState: ${GameStateEnum[gameState]}`);
        this.gameState = gameState;
    }

    public async getGames(): Promise<Game[]> {
        const games = await (await fetch('/api/authGames')).json();
        return games;
    }

    public async setClientLimit(max: number): Promise<void> {
        return this.transport.setClientLimit(max);
    }

    public async typeText(text: string, delay: number): Promise<void> {
        await this.controller.typeText(text, delay);
    }

    public setGameVisibility(visibility: GameVisibility): Promise<void> {
        if (!this.transport.connectedAppliance) {
            return Promise.reject(new Error('There is no connectedAppliance'));
        }

        this.streamer.setGameVisibility(visibility);
        return this.transport.setGameVisibility(visibility);
    }

    /**
     * Create video element and start streaming
     */
    public async start(
        sopAccountEmail: string,
        sopAccountPin: string,
        config: BrowserGamingClientConfig,
        ocgaOverrides?: OCGAOverrides,
        controllerEnv?: string,
        testbedVersion?: string,
    ): Promise<CgAppliance[]> {
        this.log.trace('Initializing gaming client');
        this.loadingProgressReporter.reset();
        this.streamer.init(config.videoParentElement);
        this.controller.setTargetForKeyboardEvents(this.streamer.getTargetForKeyboardEvents());
        this.controller.setTargetForMouseEvents(this.streamer.getTargetForMouseEvents());
        this.controller.start();
        this.uiEventManager.start();
        try {
            let gameAppliances: CgAppliance[];

            if (this.getGamePlaySessionId().length === 0) {
                const createSessionResponse = await this.controlPlane.createSessionId(this.getGameId());
                if (createSessionResponse.sessionId) {
                    this.setGamePlaySessionId(createSessionResponse.sessionId);
                    this.emitEvent('sessionCreate', { type: 'sessionCreate' });
                }
            }

            const response = await this.controlPlane.startGame(
                this.getGameId(),
                this.getChannelId(),
                this.getChannelName(),
                this.getBuildId(),
                this.getGamePlaySessionId(),
                sopAccountEmail,
                sopAccountPin,
                ocgaOverrides,
                controllerEnv,
                testbedVersion,
            );
            gameAppliances = (response.cg_startGame.gameAppliances ?? []).filter(
                (appliance) => !!appliance,
            ) as CgAppliance[];
            const ocgaOverride = ocgaOverrides?.ocgas?.[0];
            if (ocgaOverride) {
                gameAppliances = gameAppliances.filter((a) => a.gamingApplianceId === ocgaOverride);
            }
            this.setGamePlaySessionId(response.sessionId);

            let index = 1;
            const failedConnectionApplianceUuids: string[] = [];

            for (const gameAppliance of gameAppliances) {
                const shortName = gameAppliance.hostInfo?.url?.split('.')[0]?.replace('wss://', '') ?? 'unknown';

                try {
                    if (this.abort) {
                        throw new GameError(ErrorCode.GAMEPLAY_ABORTED);
                    }

                    this.log.debug(`[Start] Connecting to OCGA ${index}/${gameAppliances.length}: ${shortName}`);

                    this.setGameState(GameStateEnum.starting);
                    this.setGamingAppliance(gameAppliance);
                    await this.transport.connect(
                        gameAppliance,
                        response.cg_startGame.controllerFeatures ?? undefined,
                        this.streamer,
                    );
                    this.setGamingStartToken(gameAppliance.gameStartToken!);
                    this.setBeaconToken(gameAppliance.beaconToken!);
                    break;
                } catch (error) {
                    failedConnectionApplianceUuids.push(gameAppliance.gamingApplianceId);
                    const isLastAttempt = index++ === gameAppliances.length;

                    this.log.warn(`[Start] OCGA ${shortName} failed (attempt ${index - 1}/${gameAppliances.length})`);

                    if (isLastAttempt) {
                        const gameError = GameError.convert(error, ErrorCode.COULD_NOT_CONNECT_TO_ANY_SIGNALING_SERVER);
                        gameError.failedConnectionApplianceUuids = failedConnectionApplianceUuids;
                        throw gameError;
                    }
                }
            }

            // set max controller limit
            const maxControllers = response.cg_startGame.controllerFeatures?.maxControllers ?? 1;
            this.setClientLimit(maxControllers);

            return gameAppliances;
        } catch (e) {
            this.close();
            throw e;
        }
    }

    /**
     * Stop streaming and close the peer connection
     */
    public close() {
        this.log.trace('Closing connections');
        this.gameplaySessionId = '';
        this.beaconToken = '';
        this.streamer.close();
        this.controller.close();
        this.transport.close();
    }

    public getLogs(filters?: LogFilters) {
        return loggerManager.getLogs(filters);
    }
}

enum GameStateEnum {
    preGameStart = 0,
    starting = 1,
    playing = 3,
    frozen = 4,
    background = 5,
}

type GameState = 'preGameStart' | 'starting' | 'playing' | 'frozen' | 'background';

type SessionEventsTypeMap = {
    sessionCreate: { type: 'sessionCreate' };
};

export type PublicEventsMap = StreamerEventsTypeMap &
    LoadingProgressEventsTypeMap & {
        log: { type: 'log'; logEntry: LogEntry };
        debug: string;
        playermetric: PlayerMetricEvent;
    } & Pick<TransportEventsTypeMap, 'clientlist' | 'inputactive' | 'inputidlewarning'> &
    UIEventsTypeMap &
    ErrorTypeMap & {
        gamestatechanged: {
            type: 'gamestatechanged';
            oldvalue: GameStateEnum;
            newvalue: GameStateEnum;
        };
    } & SessionEventsTypeMap;

export type BrowserGamingClientConfig = {
    signalingServer?: string;
    videoParentElement?: HTMLElement;
};

export class GamingClientFactory {
    public createClient(customFetch?: typeof fetch) {
        return new BrowserGamingClient(customFetch);
    }
}
