import { useCallback } from 'react';
import { FullStory } from '@ui-paved-road/telemetry/fullstory';

export const useFullStory = () => {
    const devMode = process.env.NODE_ENV === 'development';

    const trackEvent = useCallback(
        (
            name: string,
            properties: {
                [key: string]: unknown;
            } = {},
        ) => {
            if (!devMode) {
                FullStory('trackEvent', {
                    name,
                    properties,
                });
            } else {
                // Log events for development
                console.info(`[${name}]`, properties);
            }
        },
        [devMode],
    );

    return {
        trackEvent,
    };
};
