import type { Game } from '@gsm-app/models/Game';
import { fetch } from '@gsm-app/utils/fetch';
import { createError } from '@gsm-common/utils/toast/createError';
import { useQuery } from '@tanstack/react-query';
import { useEffect, useMemo } from 'react';

interface GamesResponse {
    data: Game[];
    errors?: {
        title: string;
        detail: string;
    }[];
}

export const GAMES_QUERY_KEY = 'games';

export const useGames = () => {
    const query = useQuery<GamesResponse>({
        queryKey: [GAMES_QUERY_KEY],
        meta: {
            pollIntervalMs: 300000,
        },
        queryFn: async () => {
            const response = await fetch('/api/games');
            return await response.json();
        },
    });

    const games = useMemo<Game[]>(
        () => (query.data?.data && Array.isArray(query.data?.data) ? query.data?.data : []),
        [query],
    );

    const { error, isError } = query;
    useEffect(() => {
        if (isError) {
            createError({
                title: 'Error Loading Games',
                body: `${error?.message}`,
                options: {
                    id: 'games-fetch-error',
                },
            });
        }
        if (query.data?.errors) {
            query.data?.errors.forEach((e) => {
                createError({
                    title: e.title,
                    body: e.detail,
                    options: {
                        duration: 1500,
                        id: `games-fetch-error-${e.title}`,
                    },
                });
            });
        }
    }, [query.data, error, isError]);

    return {
        ...query,
        data: games,
    };
};
