export class EventEmitter<T> {
    private readonly eventListeners: { [K in keyof T]?: Array<(evt: T[K]) => void> } = {};

    public addEventListener<K extends keyof T>(type: K, listener: (ev: T[K]) => void): void {
        if (!this.eventListeners[type]) {
            this.eventListeners[type] = [];
        }
        this.eventListeners[type]?.push(listener);
    }

    public removeEventListener<K extends keyof T>(type: K, listener: (ev: T[K]) => void): void {
        const listeners = this.eventListeners[type];
        listeners?.splice(listeners.indexOf(listener));
    }

    public emitEvent<K extends keyof T>(type: K, event: T[K]) {
        const listeners = this.eventListeners[type]?.slice();
        listeners?.forEach(l => l(event));
    }

    public forwardEvents<S>(eventEmitter: EventEmitter<S>, events: Array<keyof T & keyof S>): void {
        events.forEach(eventType => eventEmitter.addEventListener(eventType, e => this.emitEvent(eventType, e as any)));
    }
}
