import { useChannels } from '@gsm-app/hooks/useChannels';
import { useFeature } from '@gsm-app/hooks/useFeature';
import { useGames } from '@gsm-app/hooks/useGames';
import type { Build } from '@gsm-app/models/Build';
import { BuildState } from '@gsm-app/models/BuildState';
import { isAuthzError } from '@gsm-app/utils/auth';
import { paramsObject, useSearchParams } from '@gsm-common/hooks/useSearchParams';
import { createWarning } from '@gsm-common/utils/toast/createWarning';
import type { DropdownOption } from '@hawkins/components';
import type { RefetchOptions } from '@tanstack/react-query';
import { useCallback, useEffect, useMemo } from 'react';
import { useChannelOptions } from './useChannelOptions';
import { useGameOptions } from './useGameOptions';

const SELECTED_GAME_ID_KEY = 'ncgt_selectedGameId';
const SELECTED_CHANNEL_MAP_KEY = 'ncgt_selectedChannelMap';

export type GameParams = {
    gameId?: string;
    channelName?: string;
    channelId?: string;
    encryptedAccount?: string;
};

export interface GameChannelsResponse {
    channelOptions: DropdownOption<string>[];
    areChannelsFetching: boolean;
    areChannelsRefetching: boolean;
    selectedChannel: DropdownOption<string> | undefined;
    setSelectedChannel: (channel: DropdownOption<string>) => void;
    refetchChannels: (options?: RefetchOptions) => Promise<unknown>;
    gameOptions: DropdownOption<string>[];
    activeBuild: Build | null | undefined;
    selectedGame: DropdownOption<string> | undefined;
    setSelectedGame: (selectedGame: DropdownOption<string>) => void;
}

const getChannelMap = () => {
    try {
        const serializedMap = localStorage.getItem(SELECTED_CHANNEL_MAP_KEY) ?? '';
        return new Map(JSON.parse(serializedMap));
    } catch {
        return new Map();
    }
};

const updateChannelMap = (gameId: string, selectedChannelId: string) => {
    const channelMap = getChannelMap();
    channelMap.set(gameId, selectedChannelId);
    localStorage.setItem(SELECTED_CHANNEL_MAP_KEY, JSON.stringify([...channelMap]));
};

export const useGameChannels = (filterGameDev?: boolean): GameChannelsResponse => {
    const { data: games } = useGames();
    const { headless } = useFeature();
    const [{ gameId, channelName, channelId }, setParams] = useSearchParams<GameParams>();
    const gameOptions = useGameOptions(games);
    const isValidGameId = useMemo(() => {
        if (!gameId) {
            return false;
        }
        return gameOptions.some((option) => option.value === gameId);
    }, [gameId, gameOptions]);
    const {
        data: channels,
        isFetching: areChannelsFetching,
        isRefetching: areChannelsRefetching,
        refetch: refetchChannels,
        isError: isChannelsError,
        error: channelsError,
    } = useChannels(gameId, filterGameDev, { enabled: isValidGameId });
    const selectedGame = useMemo(() => gameOptions.find((option) => option.value === gameId), [gameId, gameOptions]);
    const game = useMemo(() => games.find((game) => game.id === selectedGame?.value), [games, selectedGame]);
    const channelOptions = useChannelOptions(channels);
    const selectedChannel = useMemo(
        () => channelOptions.find((option) => option.label === channelName),
        [channelName, channelOptions],
    );

    const setSelectedGame = useCallback(
        (selectedGame: DropdownOption<string>) => {
            localStorage.setItem(SELECTED_GAME_ID_KEY, selectedGame.value);

            setParams(
                (prev): GameParams => {
                    return {
                        ...paramsObject(prev),
                        gameId: selectedGame.value,
                        channelName: undefined,
                    };
                },
                { replace: true },
            );
        },
        [setParams],
    );

    const setSelectedChannel = useCallback(
        (channel: DropdownOption<string>) => {
            updateChannelMap(gameId!, channel.value);
            setParams(
                (prev): GameParams => {
                    return {
                        ...paramsObject(prev),
                        channelName: channel?.label,
                    };
                },
                { replace: true },
            );
        },
        [setParams, gameId],
    );

    const showWarning = useCallback((title: string, body: string) => {
        createWarning({
            title,
            body,
            options: {
                id: 'dropdown-auto-select',
            },
        });
    }, []);

    useEffect(() => {
        if (!gameId || !isChannelsError || !isAuthzError(channelsError)) {
            return;
        }
        setParams(
            (prev): GameParams => {
                return {
                    ...paramsObject(prev),
                    gameId: undefined,
                    channelName: undefined,
                    channelId: undefined,
                };
            },
            { replace: true },
        );
    }, [channelsError, gameId, isChannelsError, setParams]);

    useEffect(() => {
        if (headless) {
            // In headless mode, use the query parameters directly
            if (gameId && gameOptions.length > 0) {
                const selectedGame = gameOptions.find((option) => option.value === gameId);
                if (selectedGame) {
                    setSelectedGame(selectedGame);
                } else {
                    showWarning('Game Not Found', 'Please select a different game.');
                }
            }
        } else {
            const selectedGameId = localStorage.getItem(SELECTED_GAME_ID_KEY);
            const selectedGame = gameOptions.find((option) => option.value === selectedGameId);
            // defaults to last selected game in local storage
            if (!gameId && selectedGame) {
                setSelectedGame(selectedGame);
            }
            // select 1st game in dropdown
            else if (!gameId && gameOptions.length > 0) {
                setSelectedGame(gameOptions[0]);
            }
            // show error if gameId is not a valid option
            else if (gameId && gameOptions.length > 0 && !gameOptions.find((option) => option.value === gameId)) {
                showWarning('Game Not Found', 'Please select a different game.');
            }
        }
    }, [gameOptions, gameId, headless, setSelectedGame, showWarning]);

    useEffect(() => {
        if (headless) {
            // In headless mode, use the query parameters directly
            if (channelId && channelOptions.length > 0) {
                const selectedChannel = channelOptions.find((option) => option.value === channelId);
                if (selectedChannel) {
                    setSelectedChannel(selectedChannel);
                } else {
                    showWarning('Channel Not Found', 'Please select a different channel.');
                }
            }
        } else {
            const channelMap = getChannelMap();
            const selectedChannelId = game && channelMap && channelMap.get(game.id);
            // defaults to last selected channel in local storage
            if (!channelName && selectedChannelId) {
                const ch = channelOptions.find((ch) => ch.value === selectedChannelId);
                if (ch) {
                    setSelectedChannel(ch);
                }
            }
            // no selection found in local storage, select 1st channel with a playable build in it
            else if (!channelName && channelOptions.length > 0) {
                const chWithOkBuild =
                    channels?.find((ch) => ch?.activeBuild?.state === BuildState.INSTALL_SUCCEED) ?? channels?.[0];
                const ch = channelOptions.find((ch) => ch.value === chWithOkBuild?.id);
                setSelectedChannel(ch!);
            }
            // show error if channelName is not a valid option
            else if (
                channelName &&
                channelOptions.length > 0 &&
                !channelOptions.find((option) => option.label === channelName)
            ) {
                showWarning('Channel Not Found', 'Please select a different channel.');
            }
        }
    }, [channelOptions, channelName, channelId, game, channels, headless, setSelectedChannel, showWarning]);

    const activeBuild = useMemo(() => {
        if (!game || !channels) {
            return undefined;
        }
        return channels?.find((ch) => ch.name === selectedChannel?.label)?.activeBuild ?? null;
    }, [game, channels, selectedChannel]);

    return {
        channelOptions,
        areChannelsFetching,
        areChannelsRefetching,
        selectedChannel,
        setSelectedChannel,
        refetchChannels,
        gameOptions,
        activeBuild,
        selectedGame,
        setSelectedGame,
    };
};
