export type FileFormat = 'csv' | 'log' | 'json' | 'binary' | 'txt' | 'png' | 'webm';

const formats: { [k in FileFormat]: string } = {
    'csv': 'text/csv',
    'log': 'text/plain',
    'json': 'application/json',
    'binary': 'application/octet-stream',
    'txt': 'text/plain',
    'png': 'image/png',
    'webm': 'video/webm',
};

export const download = function (fileName: string, data: string | Blob, format: FileFormat = 'csv') {
    const blob = typeof data === 'string' ? new Blob([data], { type: formats[format] }) : data;
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.setAttribute('href', url);
    a.setAttribute('download', format === 'binary' ? fileName : `${fileName}.${format}`);
    document.body.appendChild(a); // Required for this to work in FireFox
    a.click();
    document.body.removeChild(a);
    window.URL.revokeObjectURL(url);
};
