import { Client, type Code } from '@netflix-internal/game-input';
import { loggerManager } from '../common';
import { ConfigManager } from '../config';
import type { Transport, TransportEventsTypeMap } from '../transport';
import { DataChannelLabel } from '../transport/RTCService';
import { GamepadAdapter } from './GamepadAdapter';
import { type KeyPressEventModifiers, KeyboardInput } from './KeyboardInput';
import { MouseInput } from './MouseInput';

export class Controller {
    private readonly log = loggerManager.getLogger('InputController');
    private readonly gamepadAdapter: GamepadAdapter | undefined;
    private mouseInput: MouseInput | undefined;
    private keyboardInput: KeyboardInput | undefined;
    private detach?: () => void;

    public constructor(private readonly transport: Transport) {
        const config = ConfigManager.getConfig();
        if (config.enableGamepad) {
            this.gamepadAdapter = new GamepadAdapter();
        }
    }

    public setTargetForKeyboardEvents(keyEventsTarget: EventTarget): void {
        this.keyboardInput?.close();
        this.keyboardInput = new KeyboardInput(keyEventsTarget);
    }

    public setTargetForMouseEvents(mouseEventsTarget: EventTarget): void {
        this.mouseInput = new MouseInput(mouseEventsTarget);
    }

    public subscribeToKeyPress(keyCode: string, options: KeyPressEventModifiers, callback: (e: KeyboardEvent) => void) {
        this.keyboardInput?.subscribeToKeyPress(keyCode, options, callback);
    }

    public subscribeToButtonPress(button: Code, callback: () => void) {
        this.gamepadAdapter?.subscribeToButtonPress(button, callback);
    }

    public async typeText(text: string, delay: number): Promise<void> {
        await this.keyboardInput?.typeText(text, delay);
    }

    public start() {
        const inputClient = new Client();
        inputClient.logger = this.log;
        inputClient.on('connected', (d) => this.log.debug(`device ${d.name}: connected`));
        inputClient.on('disconnected', (d) => this.log.debug(`device ${d.name}: disconnected`));

        this.log.trace('Starting controller input');
        if (this.keyboardInput) {
            inputClient.add(this.keyboardInput.getInputDevice());
            this.keyboardInput.start();
        }

        if (this.mouseInput) {
            inputClient.add(this.mouseInput.getInputDevice());
            this.mouseInput.start();
        }

        if (this.gamepadAdapter) {
            inputClient.add(this.gamepadAdapter.getInputDevice());
            this.gamepadAdapter.start();
        }

        const connection = {
            send: (data: ArrayBuffer) => {
                this.transport.sendData(DataChannelLabel.Input, data);
            },
            onReceive: (data: ArrayBuffer) => {},
        };

        const attach = ({ channel }: TransportEventsTypeMap['datachannelopened']) => {
            if (channel !== DataChannelLabel.Input) {
                return;
            }

            this.detach?.(); // detach previous connection

            this.log.trace('attach inputClient');
            // biome-ignore lint/suspicious/noExplicitAny: game-input library connection types
            inputClient.attach(connection as any);

            this.transport.onDataMessage(DataChannelLabel.Input, (data) => connection.onReceive(data));

            this.detach = () => {
                this.log.trace('detach inputClient');
                // biome-ignore lint/suspicious/noExplicitAny: game-input library connection types
                inputClient.detach(connection as any);
                this.transport.removeEventListener('datachannelopened', attach);
                this.detach = () => {};
            };
        };

        this.transport.addEventListener('datachannelopened', attach);
    }

    public close() {
        this.log.trace('close');
        this.detach?.();
        this.mouseInput?.close();
        this.keyboardInput?.close();
        this.gamepadAdapter?.close();
    }
}
