import { useKeyState } from '@gsm-common/hooks/useKeyState';
import { type FileUploaderProgress, FileUploaderProgressToast } from '@hawkins/components';
import axios, { AxiosError, type AxiosRequestConfig, type AxiosResponse, CanceledError } from 'axios';
import { type ReactNode, type SetStateAction, createContext, useCallback, useContext, useState } from 'react';

type UploadState = {
    controller: AbortController;
    promise: Promise<any>;
    timestamp: number;
} & FileUploaderProgress;

type UploadProviderState = {
    [k: string]: UploadState;
};

export type UploadContextValue = {
    startUpload: <T, D>(id: string, filename: string, config: AxiosRequestConfig<D>) => Promise<AxiosResponse<T>>;
    cancelUpload: (id: string) => void;
    state: UploadProviderState;
    updateUpload: (id: string, value: SetStateAction<Partial<UploadState>>) => void;
};

type ServerError = { errors: { title: string; detail: string } };
export type UploadError<T> = ServerError | CanceledError<T>;

const context = createContext<UploadContextValue>({} as UploadContextValue);
const Provider = context.Provider;

const errorMessage = (error: any): string | undefined => {
    let message: string | undefined;
    if (error instanceof AxiosError) {
        message = error.response?.data?.errors?.[0]?.detail;
    }
    return message ?? error.message;
};

const startFileUpload = <T, D>(
    mergeState: (id: string, value: SetStateAction<Partial<UploadState>>) => void,
    id: string,
    filename: string,
    config: AxiosRequestConfig<D>,
) => {
    const controller = new AbortController();

    const promise = axios<D, AxiosResponse<T>>({
        ...config,
        maxContentLength: Infinity,
        maxBodyLength: Infinity,
        onUploadProgress: event => {
            mergeState(id, {
                loaded: event.loaded,
                total: event.total ?? 0,
            });

            config.onUploadProgress?.(event);
        },
        signal: controller.signal,
    })
        // completed
        .then(response => {
            mergeState(id, prev => ({ loaded: prev.total, status: 'success' }));
            return response;
        })
        // show error
        .catch((error: UploadError<T>) => {
            if (error instanceof CanceledError) {
                mergeState(id, { status: 'warning', message: 'Upload Canceled' });
            } else {
                mergeState(id, { status: 'failure', message: errorMessage(error) ?? 'Upload Errored' });
            }
            throw error;
        });

    mergeState(id, {
        status: 'pending',
        loaded: 0,
        total: 0,
        controller,
        promise,
        filename,
        timestamp: new Date().getTime(),
    });

    return promise;
};

export const UploadProvider = ({ children }: { children: ReactNode }) => {
    const { state, setState, mergeState } = useKeyState<UploadState>({});
    const [isToastVisible, setToastVisible] = useState(false);

    const startUpload = useCallback<UploadContextValue['startUpload']>(
        <T, D>(id: string, filename: string, config: AxiosRequestConfig<D>) => {
            setToastVisible(true);
            return startFileUpload<T, D>(mergeState, id, filename, config);
        },
        [state],
    );

    const cancelUpload = useCallback(
        (id: string) => {
            if (!state[id]) {
                return;
            }
            // cancel upload
            if (state[id].status !== 'success') {
                state[id].controller?.abort();
            }

            // remove from state
            setState(prev => {
                let newState = { ...prev };
                delete newState[id];
                return newState;
            });
        },
        [state],
    );

    const updateUpload = useCallback(
        (id: string, newValues: SetStateAction<Partial<UploadState>>) => {
            setToastVisible(true);
            mergeState(id, newValues);
        },
        [mergeState],
    );

    const onToastCancel = useCallback(() => {
        Object.keys(state).forEach(id => {
            cancelUpload(id);
        });
        setToastVisible(false);
    }, [state, cancelUpload]);

    // create list from map
    const fileProgress: UploadState[] = Object.keys(state).map(id => state[id]);

    return (
        <Provider value={{ startUpload, cancelUpload, state, updateUpload }}>
            {children}
            <FileUploaderProgressToast
                onCancel={onToastCancel}
                onSetVisible={setToastVisible}
                progress={fileProgress}
                progressType='upload'
                openOnMount
                visible={isToastVisible}
            />
        </Provider>
    );
};

export const useUpload = () => useContext(context);
