type LogEventHandler = (logMsg: LogEntry, logger: LoggerManager) => void;

export enum LogLevel {
    TRACE = 0,
    DEBUG = 1,
    INFO = 2,
    WARN = 3,
    ERROR = 4,
}

// biome-ignore lint/suspicious/noExplicitAny: log message components can be anything
type LogMessageComponent = any;

export type LogFunction = {
    (level: LogLevel, ...message: LogMessageComponent[]): void;
    trace(...message: LogMessageComponent[]): void;
    debug(...message: LogMessageComponent[]): void;
    info(...message: LogMessageComponent[]): void;
    warn(...message: LogMessageComponent[]): void;
    error(...message: LogMessageComponent[]): void;
};

export class LogEntry {
    public readonly message: string;
    public constructor(
        public readonly time: Date,
        public readonly level: LogLevel,
        public readonly topic: string,
        public readonly messageItems: LogMessageComponent[],
    ) {
        this.message = this.messageItems
            .map((m) => (typeof m === 'object' && m.toString === Object.prototype.toString ? JSON.stringify(m) : m))
            .join(', ');
    }

    public toString() {
        return `${this.getFormattedTime()} ${LogLevel[this.level]} [${this.topic}] ${this.message}`;
    }

    private padLeft(number: number, places = 2): string {
        return String(number).padStart(places, '0');
    }

    public getFormattedTime() {
        return `${this.padLeft(this.time.getHours())}:${this.padLeft(this.time.getMinutes())}:${this.padLeft(
            this.time.getSeconds(),
        )}.${this.padLeft(this.time.getMilliseconds(), 3)}`;
    }
}

export class LoggerManager {
    private readonly listeners: LogEventHandler[] = [];
    private readonly logs: LogEntry[] = [];
    public readonly id: number;

    constructor() {
        this.id = Math.random();
    }

    public onLog(handler: LogEventHandler, retroactive = true) {
        this.listeners.push(handler);
        if (retroactive) {
            this.logs.forEach((l) => handler(l, this));
        }
    }

    public log(topic: string, level: LogLevel, ...message: LogMessageComponent[]): void {
        const logEntry = new LogEntry(new Date(), level, topic, message);
        this.logs.push(logEntry);
        this.listeners.forEach((l) => l(logEntry, this));
    }

    public getLogger(topic: string): LogFunction {
        const logger = this.log.bind(this, topic) as LogFunction;
        logger.trace = this.log.bind(this, topic, LogLevel.TRACE);
        logger.debug = this.log.bind(this, topic, LogLevel.DEBUG);
        logger.info = this.log.bind(this, topic, LogLevel.INFO);
        logger.warn = this.log.bind(this, topic, LogLevel.WARN);
        logger.error = this.log.bind(this, topic, LogLevel.ERROR);

        return logger;
    }

    public getLogs(filters?: LogFilters): LogEntry[] {
        return filters?.level || filters?.topics || filters?.excludeTopics
            ? this.logs.filter(
                  (logEntry) =>
                      (!filters.level || filters.level <= logEntry.level) &&
                      (!filters.topics || filters.topics.includes(logEntry.topic)) &&
                      (!filters.excludeTopics || !filters.excludeTopics.includes(logEntry.topic)),
              )
            : [...this.logs];
    }
}
export type LogFilters = { level?: LogLevel; topics?: string[]; excludeTopics?: string[] };
export const loggerManager = new LoggerManager();
