import { useNotifications } from '@gsm-app/hooks/useNotifications';
import { IconNewspaper } from '@hawkins/assets';
import { Button, NotificationBadge } from '@hawkins/components';
import { useCallback, useMemo, useState } from 'react';

const NOTIFICATION_LAST_TS_KEY = 'notificationLastTs';

export type NotificationsMenuButtonProps = {
    onClick: () => void;
};

export const NotificationsMenuButton = (props: NotificationsMenuButtonProps) => {
    const { onClick } = props;
    const { notifications } = useNotifications();
    const [opened, setOpened] = useState(false);
    const lastSeenTs = localStorage.getItem(NOTIFICATION_LAST_TS_KEY);
    const lastSeenDate = lastSeenTs ? new Date(Number(lastSeenTs)) : new Date(0);

    // Compare the notifications timestamps to see if
    const hasUnseenNotifications = useMemo(() => {
        let result = false;

        notifications?.forEach(n => {
            if (n.createdDate) {
                const notificationCreatedDate = new Date(n.createdDate);
                result = result || lastSeenDate < notificationCreatedDate;
            }
            return n.createdDate;
        });
        return result;
    }, [notifications]);

    const onButtonClick = useCallback(() => {
        setOpened(true);
        onClick();
    }, [onClick]);

    const button = (
        <Button compact variant='icon' aria-label='news' icon={IconNewspaper} onClick={onButtonClick}>
            Notifications
        </Button>
    );

    return hasUnseenNotifications && !opened ? <NotificationBadge compact>{button}</NotificationBadge> : button;
};
