import { loggerManager } from '../common';
import { EventEmitter } from '../common/EventEmitter';
import type { Streamer, StreamerEventsTypeMap } from '../streamer';
import type { Transport, TransportEventsTypeMap } from '../transport';

/** Loading steps in order of progression */
export type LoadingStep = 'connecting' | 'establishing_webrtc' | 'loading_game' | 'starting_stream' | 'ready';

/** Human-readable labels for each loading step */
export const LoadingStepLabels: Record<LoadingStep, string> = {
    connecting: 'Connecting to server',
    establishing_webrtc: 'Establishing connection',
    loading_game: 'Loading game',
    starting_stream: 'Starting stream',
    ready: 'Ready',
};

/**
 * The LoadingProgressReporter is a helper class that estimates loading progress to be rendered by
 * the loading bar on the UI. It combines the progress messages received from the OCGA informing
 * game initialization progress with the connection and initialization process of the client itself
 * that's mapped by the events sent by the Transport layer
 */
export class LoadingProgressReporter extends EventEmitter<LoadingProgressEventsTypeMap> {
    private readonly log = loggerManager.getLogger('LoadingProgress');
    private readonly expectedTransportEvents: Set<keyof TransportEventsTypeMap> = new Set([
        'gamecontrolconnectionestablished',
        'requestedstream',
        'sentsdpoffer',
        'receivedsdpanswer',
        'track',
    ]);

    private pendingTransportEvents: Set<keyof TransportEventsTypeMap> = new Set(this.expectedTransportEvents);
    private streamingIsReady = false;
    private stepsProgress = 0;
    private serverReadyProgress = 0;
    private currentStep: LoadingStep = 'connecting';

    public constructor(
        private readonly transport: Transport,
        private readonly streamer: Streamer,
    ) {
        super();
        this.expectedTransportEvents.forEach((eType) => {
            this.transport.addEventListener(eType, () => this.updateLoadingProgress(eType));
        });

        this.transport.addEventListener('ocgaloadprogress', (e) => {
            if (!this.streamingIsReady) {
                const percent = Math.round(e.value * 100);
                this.log.debug(`ocgaloadprogress: ${percent}%`);
                this.serverReadyProgress = e.value;
                this.currentStep = 'loading_game';
                this.emitLoadingProgress();
            }
        });

        const streamerEvents: Array<keyof StreamerEventsTypeMap> = ['autoplayblocked', 'play', 'playing'];
        streamerEvents.forEach((eType) => {
            this.streamer.addEventListener(eType, () => this.updateLoadingProgress(eType));
        });
    }

    public reset(): void {
        this.pendingTransportEvents = new Set(this.expectedTransportEvents);
        this.streamingIsReady = false;
        this.stepsProgress = 0;
        this.serverReadyProgress = 0;
        this.currentStep = 'connecting';
    }

    private updateLoadingProgress(eventType: keyof (TransportEventsTypeMap & StreamerEventsTypeMap)): void {
        const previousStep = this.currentStep;

        if (eventType === 'firstframe') {
            // First frame visible - truly ready
            this.streamingIsReady = true;
            this.serverReadyProgress = 1;
            this.stepsProgress = 1;
            this.currentStep = 'ready';
        } else if (
            eventType === 'autoplayblocked' ||
            eventType === 'background' ||
            eventType === 'frozen' ||
            eventType === 'play' ||
            eventType === 'playing'
        ) {
            // Stream is starting but video may not be visible yet
            this.streamingIsReady = true;
            this.serverReadyProgress = 1;
            this.stepsProgress = 1;
            this.currentStep = 'starting_stream';
        } else if (!this.streamingIsReady && this.pendingTransportEvents.has(eventType)) {
            this.pendingTransportEvents.delete(eventType);
            this.stepsProgress = 1 - this.pendingTransportEvents.size / this.expectedTransportEvents.size;

            // Update current step based on which events have completed
            if (eventType === 'gamecontrolconnectionestablished') {
                this.currentStep = 'establishing_webrtc';
            } else if (eventType === 'receivedsdpanswer' || eventType === 'track') {
                // If we haven't received OCGA progress yet, we're waiting for WebRTC
                // Otherwise we're loading the game
                this.currentStep = this.serverReadyProgress > 0 ? 'loading_game' : 'establishing_webrtc';
            }
        } else {
            return;
        }

        // Log step transitions
        if (this.currentStep !== previousStep) {
            this.log.debug(`Step: ${previousStep} → ${this.currentStep} (event: ${eventType})`);
        } else {
            this.log.debug(`Event: ${eventType} (step unchanged: ${this.currentStep})`);
        }

        this.emitLoadingProgress();
    }

    private emitLoadingProgress(): void {
        // Calculate game load percentage (0-100) for display
        const gameLoadPercent = Math.round(this.serverReadyProgress * 100);

        this.emitEvent('loadingprogress', {
            type: 'loadingprogress',
            progress: (this.serverReadyProgress + this.stepsProgress) / 2,
            step: this.currentStep,
            stepLabel: LoadingStepLabels[this.currentStep],
            gameLoadPercent,
        });
    }
}

export type LoadingProgressEventsTypeMap = {
    loadingprogress: {
        type: 'loadingprogress';
        progress: number;
        step: LoadingStep;
        stepLabel: string;
        gameLoadPercent: number;
    };
};
