import type { ErrorCode } from './ErrorCode';
import type { GamingClientError } from './ErrorReporter';

export type ConnectionStage = 'init' | 'signaling' | 'webrtc' | 'first_frame' | 'unknown';

export interface ConnectionDiagnostics {
    stage: ConnectionStage;
    ocgaUrl?: string;
    ocgaUuid?: string;
    ocgaShortName?: string;
    elapsedMs?: number;
    timeoutMs?: number;
    connectionState?: string;
    iceConnectionState?: string;
    signalingState?: string;
    originalError?: string;
}

export class GameError implements GamingClientError {
    public readonly stack;
    public diagnostics?: ConnectionDiagnostics;

    constructor(
        readonly code: ErrorCode,
        readonly message?: string,
        diagnostics?: ConnectionDiagnostics,
    ) {
        this.stack = new Error().stack
            ?.split('\n')
            .slice(2)
            .map((line) => line.replace(/\s+at\s+/, ''))
            .join('\n');
        this.diagnostics = diagnostics;
    }

    public static convert(error: unknown, code: ErrorCode): GamingClientError {
        if (error instanceof GameError) {
            return error;
        }

        const message = error instanceof Error ? error.message : String(error);
        return new GameError(code, message, {
            stage: 'unknown',
            originalError: message,
        });
    }

    public toJSON() {
        return {
            code: this.code,
            message: this.message,
            stack: this.stack,
            diagnostics: this.diagnostics,
        };
    }
}
