import { AuthenticationError, isAuthzError as isAuthzErrorBase } from '@gsm-app/utils/auth';
import { QueryClient, type Query } from '@tanstack/react-query';

const QUERY_RETRY_LIMIT = 2;
const QUERY_STALE_TIME_MS = 1000 * 60 * 60 * 24; // cache 1 day

const isAuthzError = (error: unknown) => {
    // IdentityProvider throws this to trigger logout; retries are never useful.
    if (error instanceof AuthenticationError) {
        return true;
    }
    return isAuthzErrorBase(error);
};

const getPollIntervalMs = (query: Query): number | false => {
    const poll = (query.options.meta as { pollIntervalMs?: unknown } | undefined)?.pollIntervalMs;
    return typeof poll === 'number' ? poll : false;
};

export const queryClient = new QueryClient({
    defaultOptions: {
        queries: {
            staleTime: QUERY_STALE_TIME_MS,
            retry: (failureCount, error) => {
                if (isAuthzError(error)) {
                    return false;
                }
                return failureCount < QUERY_RETRY_LIMIT;
            },
            refetchInterval: (query) => {
                const pollIntervalMs = getPollIntervalMs(query);
                if (!pollIntervalMs) {
                    return false;
                }
                // Stop polling permanently when we know it can't recover without user action (e.g., re-auth).
                const error = (query as { state?: { error?: unknown } }).state?.error;
                if (isAuthzError(error)) {
                    return false;
                }
                return pollIntervalMs;
            },
        },
    },
});
