import { createContext, type PropsWithChildren, useContext } from 'react';

interface SessionTimelineDataContextValue {
    datasets?: {[key: string]: any};
    isDisconnected: boolean;
    error: string | null;
    isLoading: boolean;
    targetInstanceCount: number;
    exportOrder?: string[];
}

const context = createContext<SessionTimelineDataContextValue>({} as SessionTimelineDataContextValue);

type SessionTimelineDataProviderProps = PropsWithChildren<{
    data?: {[key: string]: any},
    isDisconnected: boolean,
    error: string | null,
    isLoading: boolean,
    targetInstanceCount: number,
    exportOrder?: string[]
}>

const DEFAULT_TARGET_INSTANCE_COUNT = 50;

export const SessionTimelineDataProvider = (props: SessionTimelineDataProviderProps) => {
    const {
        children,
        error,
        data = {},
        isDisconnected,
        isLoading,
        targetInstanceCount,
        exportOrder
    } = props;

    return (
        <context.Provider value={{
            datasets: data,
            error,
            targetInstanceCount: targetInstanceCount || DEFAULT_TARGET_INSTANCE_COUNT,
            isDisconnected,
            isLoading,
            exportOrder,
        }}>
            {children}
        </context.Provider>
    );
};

export const useSessionTimelineData = () => useContext(context);
