import { type SetStateAction, useCallback, useState } from 'react';

export const useKeyState = <T>(defaultValue: Partial<T>) => {
    const [state, setState] = useState<{ [k: string]: T }>({});

    const mergeState = useCallback(
        (id: string, newValues: SetStateAction<Partial<T>>) => {
            setState(prev => {
                const newProvider = { ...prev };
                const oldValues: T | Partial<T> = newProvider[id] ?? defaultValue;
                const mergedValues = typeof newValues === 'function' ? newValues(oldValues) : newValues;

                if (typeof oldValues === 'object') {
                    newProvider[id] = { ...oldValues, ...mergedValues } as T;
                } else {
                    newProvider[id] = mergedValues as T;
                }

                return newProvider;
            });
        },
        [setState, defaultValue],
    );

    return {
        state,
        setState,
        mergeState,
    };
};
