import { useNotifications } from '@gsm-app/hooks/useNotifications';
import { ContextualBanner, Panel, PanelContent, PanelHeader, Text } from '@hawkins/components';
import { Dimensions, Typography } from '@hawkins/variables';
import { useEffect } from 'react';
import styles from './NotificationsModal.module.css';

const NOTIFICATION_LAST_TS_KEY = 'notificationLastTs';

interface NotificationsModalProps {
    onClose: () => void;
}

const userLocale = navigator.language || 'en-US';
const dateFormat = new Intl.DateTimeFormat(userLocale, { dateStyle: 'medium' });

export const NotificationsModal = ({ onClose }: NotificationsModalProps) => {
    const { notifications } = useNotifications();

    useEffect(() => {
        localStorage.setItem(NOTIFICATION_LAST_TS_KEY, `${new Date().getTime()}`);
    }, []);

    return (
        <Panel open position='right' maximizable={false} minimizable={false} width={400}>
            <PanelHeader onCloseClick={onClose} title='Notifications' />
            <PanelContent>
                {notifications?.length ? (
                    notifications?.map((notification, i) => {
                        let variant: 'error' | 'neutral' | 'success' | 'warning' | undefined;
                        switch (notification.variant) {
                            case 'ERROR':
                                variant = 'error';
                                break;
                            case 'WARNING':
                                variant = 'warning';
                                break;
                            case 'SUCCESS':
                                variant = 'success';
                                break;
                            case 'REGULAR':
                                variant = undefined;
                                break;
                            default:
                                variant = undefined;
                        }
                        return (
                            <div key={notification.uuid}>
                                <ContextualBanner
                                    multiline
                                    classes={{
                                        text: styles.notificationContextualBannerText,
                                    }}
                                    variant={variant}
                                    title={notification.title}
                                    text={
                                        <div className='example-classname'>
                                            {notification.markup}
                                            {notification.createdDate && (
                                                <Text
                                                    colorVariant='faded'
                                                    style={{
                                                        marginTop: Dimensions.Space4,
                                                        fontSize: Typography.FontSize10,
                                                        textAlign: 'right',
                                                    }}
                                                >
                                                    {dateFormat.format(new Date(notification.createdDate))}
                                                </Text>
                                            )}
                                        </div>
                                    }
                                    style={{
                                        marginBottom: Dimensions.Space24,
                                    }}
                                />
                            </div>
                        );
                    })
                ) : (
                    <Text>No new notifications</Text>
                )}
            </PanelContent>
        </Panel>
    );
};
