import { useEffect, useState } from 'react';

type AppParams = {
    gameId?: number;
    channelName?: string;
    headless?: boolean;
    networkReport?: string;
};

const createAppQueryParams = <T>(search: string, numberKeys: T[], booleanKeys: T[]) => {
    const queryParams = new URLSearchParams(search);
    const params: { [k: string]: string | number | boolean | undefined } = {};

    for (const [k, v] of queryParams) {
        if (numberKeys.includes(k as T)) {
            params[k] = parseInt(v);
        } else if (booleanKeys.includes(k as T)) {
            params[k] = v === 'true';
        } else {
            params[k] = v;
        }
    }

    return params;
};

export const useAppQueryParams = () => {
    const [state, setState] = useState<AppParams>(
        createAppQueryParams<keyof AppParams>(window.location.search, ['gameId'], ['headless']),
    );

    // sync state when history changes
    useEffect(() => {
        const updateParams = () =>
            setState(() => createAppQueryParams<keyof AppParams>(window.location.search, ['gameId'], ['headless']));
        const pushState = window.history.pushState;
        const replaceState = window.history.replaceState;

        window.history.pushState = function (data: any, unused: string, url?: any) {
            pushState.call(window.history, data, unused, url);
            updateParams();
        };

        window.history.replaceState = function (data: any, unused: string, url?: any) {
            replaceState.call(window.history, data, unused, url);
            updateParams();
        };

        return () => {
            window.history.pushState = pushState;
            window.history.replaceState = replaceState;
        };
    }, []);

    return state;
};
