import { createContext, useContext } from 'react';

export type Modals =
    | 'help'
    | 'confirm'
    | 'uploadBuild'
    | 'sopAccount'
    | 'playerBlob'
    | 'newChannel'
    | 'notifications'
    | 'feedback'
    | undefined;

export interface ModalContextValue {
    modal: Modals;
    modalData: any;
    showModal: (value: Modals, data?: any) => void;
}

const context = createContext<ModalContextValue>({} as ModalContextValue);
export const ModalProvider = context.Provider;
export const useModal = () => useContext(context);
