import { type ApolloError, useMutation } from '@apollo/client';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { NotificationCondition, NotificationScope, NotificationStyle } from '../api/graphql_generated/schema';
import { consumerClient, getConsumerHeaders } from '../graphql/client';
import { graphql } from '../graphql/generated';
import { isMockPlayMode } from '../mocks/isMockPlayMode';
import { useSyncedRef } from './useSyncedRef';

const REFRESH_BEFORE_MS = 2 * 60_000; // 2 minutes
const MINUTES_TO_EXTEND = 15;

export const CREATE_GAME_CONTROLLER_BEACON_MUTATION = graphql(`
    mutation CreateGameControllerBeacon($gameId: Int!, $gameplaySessionId: ID!, $cloudGameToken: String!, $notificationConfig: [NotificationConfig]) {
        ngpCreateBeacon(
            gameId: $gameId
            gameType: CLOUD_GAME
            gameplaySessionId: $gameplaySessionId
            cloudGameToken: $cloudGameToken,
            notificationConfig: $notificationConfig
        ) {
            id
            code
            qrCodeUrl
            validUntil
        }
    }
`);

export const EXTEND_GAME_CONTROLLER_BEACON_MUTATION = graphql(`
    mutation ExtendGameControllerBeacon(
        $gameId: Int!
        $gameplaySessionId: ID!
        $beaconCode: String!
        $minutesToExtend: Int!
    ) {
        ngpExtendBeaconValidUntil(
            gameId: $gameId
            gameplaySessionId: $gameplaySessionId
            beaconCode: $beaconCode
            minutesToExtend: $minutesToExtend
        ) {
            success
        }
    }
`);

export const CLOSE_GAME_CONTROLLER_BEACON_MUTATION = graphql(`
    mutation CloseGameControllerBeacon($beaconId: ID!) {
        ngpCloseBeacon(beaconId: $beaconId) {
            id
        }
    }
`);

interface QRCodeProps {
    beaconToken: string;
    gameId: string;
    sessionId: string;
}

interface ControllerData {
    beaconId: string;
    qrCodeUrl: string;
}

interface UseControllerQRCodeResponse<T> {
    data: T | null;
    error: ApolloError | undefined;
    isError: boolean;
    loading: boolean;
    retry: () => void;
}

type UseControllerQRCodeProps = Partial<Pick<QRCodeProps, 'gameId' | 'sessionId'>> & {
    disabled?: boolean;
    cloudGameToken?: string;
    passport?: string;
};

const MOCK_RESPONSE: UseControllerQRCodeResponse<ControllerData> = {
    data: null,
    error: undefined,
    isError: false,
    loading: false,
    retry: () => {},
};

export const useControllerQRCode = (props: UseControllerQRCodeProps): UseControllerQRCodeResponse<ControllerData> => {
    // Mock-mode is a fixed build-time flag (not conditional per-render), so delegating entirely to
    // one hook or the other here is safe — this component instance always takes the same branch.
    if (isMockPlayMode) {
        return MOCK_RESPONSE;
    }
    return useRealControllerQRCode(props);
};

const useRealControllerQRCode = ({
    disabled,
    gameId,
    sessionId,
    cloudGameToken,
    passport,
}: UseControllerQRCodeProps): UseControllerQRCodeResponse<ControllerData> => {
    const isCreateEnabled = Boolean(!disabled && cloudGameToken && sessionId && gameId && passport);
    const [validUntilMs, setValidUntilMs] = useState<number | undefined>();
    const [
        createGameControllerBeaconMutate,
        {
            data: createGameControllerBeaconData,
            error: createGameControllerBeaconError,
            loading: createGameControllerBeaconPending,
        },
    ] = useMutation(CREATE_GAME_CONTROLLER_BEACON_MUTATION, {
        client: consumerClient,
        onCompleted: (response) => {
            const validUntil = new Date(response.ngpCreateBeacon?.validUntil ?? '').getTime();
            if (!Number.isNaN(validUntil)) {
                setValidUntilMs(validUntil);
            }
        },
    });
    const devMode = process.env.NODE_ENV === 'development';
    const isError = !devMode && Boolean(createGameControllerBeaconError);

    const [extendGameControllerBeaconMutate] = useMutation(EXTEND_GAME_CONTROLLER_BEACON_MUTATION, {
        client: consumerClient,
        onCompleted: ({ ngpExtendBeaconValidUntil }) => {
            if (ngpExtendBeaconValidUntil?.success && validUntilMs) {
                setValidUntilMs(validUntilMs + MINUTES_TO_EXTEND * 60_000);
            }
        },
    });

    const [closeGameControllerBeacon] = useMutation(CLOSE_GAME_CONTROLLER_BEACON_MUTATION, {
        client: consumerClient,
    });

    const closeBeaconRef = useSyncedRef(() => {
        if (createGameControllerBeaconData?.ngpCreateBeacon?.id && passport) {
            closeGameControllerBeacon({
                variables: {
                    beaconId: createGameControllerBeaconData?.ngpCreateBeacon?.id,
                },
                context: {
                    headers: getConsumerHeaders(passport),
                },
            });
        }
    });

    const createBeacon = useCallback(async () => {
        if (cloudGameToken && sessionId && gameId && passport) {
            await createGameControllerBeaconMutate({
                variables: {
                    gameId: Number.parseInt(gameId),
                    gameplaySessionId: sessionId,
                    cloudGameToken,
                    notificationConfig: [
                        {
                            type: NotificationStyle.SilentPush,
                            scope: NotificationScope.SameAccount,
                            conditions: [],
                        },
                        {
                            type: NotificationStyle.SilentPush,
                            scope: NotificationScope.ReplayEligibleDevices,
                            conditions: [NotificationCondition.SameNetwork],
                        },
                        {
                            type: NotificationStyle.VisualPush,
                            scope: NotificationScope.SameAccount,
                            conditions: [NotificationCondition.SameNetworkOrFirstContact],
                        },
                        {
                            type: NotificationStyle.VisualPush,
                            scope: NotificationScope.ReplayEligibleDevices,
                            conditions: [NotificationCondition.SameNetwork],
                        },
                    ],
                },
                context: { headers: getConsumerHeaders(passport) },
            });
        }
    }, [cloudGameToken, createGameControllerBeaconMutate, gameId, sessionId, passport]);

    // close the beacon when the session is disabled
    useEffect(() => {
        if (sessionId && disabled) {
            closeBeaconRef?.current();
        }
    }, [sessionId, disabled, closeBeaconRef]);

    // extend beacon token
    useEffect(() => {
        let timer: NodeJS.Timeout | number | undefined;

        const beaconCode = createGameControllerBeaconData?.ngpCreateBeacon?.code;

        if (validUntilMs && beaconCode && gameId && sessionId && passport && !disabled) {
            const refreshMs = validUntilMs - new Date().getTime() - REFRESH_BEFORE_MS;

            if (refreshMs >= 0) {
                timer = setTimeout(() => {
                    extendGameControllerBeaconMutate({
                        variables: {
                            gameId: Number.parseInt(gameId),
                            beaconCode,
                            gameplaySessionId: sessionId,
                            minutesToExtend: MINUTES_TO_EXTEND,
                        },
                        context: {
                            headers: getConsumerHeaders(passport),
                        },
                    });
                }, refreshMs);
            }
        }

        return () => {
            if (timer) {
                clearTimeout(timer);
            }
        };
    }, [
        createGameControllerBeaconData?.ngpCreateBeacon?.code,
        extendGameControllerBeaconMutate,
        gameId,
        sessionId,
        disabled,
        validUntilMs,
        passport,
    ]);

    // create beacon token
    useEffect(() => {
        if (isCreateEnabled) {
            createBeacon();
        }
    }, [createBeacon, isCreateEnabled]);

    // close beacon token
    useEffect(() => {
        const closeBeacon = () => {
            closeBeaconRef?.current();
        };
        return () => {
            closeBeacon();
        };
    }, [closeBeaconRef]);

    const data = useMemo(() => {
        const qrCodeUrl = createGameControllerBeaconData?.ngpCreateBeacon?.qrCodeUrl;
        const beaconId = createGameControllerBeaconData?.ngpCreateBeacon?.id;
        if (qrCodeUrl && beaconId) {
            return {
                beaconId,
                qrCodeUrl,
            };
        }
        return null;
    }, [
        createGameControllerBeaconData?.ngpCreateBeacon?.qrCodeUrl,
        createGameControllerBeaconData?.ngpCreateBeacon?.id,
    ]);

    return {
        data,
        isError,
        error: createGameControllerBeaconError,
        loading: createGameControllerBeaconPending,
        retry: createBeacon,
    };
};
