import * as input from '@netflix-internal/game-input';
import { assert, loggerManager } from '../common';
import { AxisMap, ButtonMap } from './GamepadMap';
import type { InputDevice } from './InputDevice';

export class GamepadAdapter implements InputDevice {
    private readonly log = loggerManager.getLogger('GamepadAdapter');
    private loopRunning = 0;
    private started = false;
    private readonly device: input.Device;
    private readonly interceptedButtons: Array<ButtonInterceptor> = [];
    private previouslyPressedButtons: input.Code[] = [];

    public constructor() {
        this.device = input.Device.create(0, 0, 'Gamepad', [
            ...Button.map((code) => new input.Key(code)),
            ...Axis.map((axis) => new input.Abs(axis, 500, 1000)),
        ]);
    }

    public start() {
        if (this.started) {
            return;
        }

        this.started = true;
        globalThis.window.addEventListener('gamepadconnected', ({ gamepad }: GamepadEvent) => {
            this.log.debug(
                `Gamepad connected at index ${gamepad.index}: ${gamepad.id}. ${gamepad.buttons.length} buttons, ${gamepad.axes.length} axes.`,
            );
            if (!this.loopRunning) {
                this.initGameLoop();
            }
        });
        globalThis.window.addEventListener('gamepaddisconnected', ({ gamepad }: GamepadEvent) => {
            this.log.debug(`Gamepad disconnected from index ${gamepad.index}: ${gamepad.id}`);
            if (this.loopRunning) {
                this.stopGameLoop();
            }
        });
    }

    public close() {
        this.stopGameLoop();
    }

    public getInputDevice(): input.Device {
        return this.device;
    }

    public subscribeToButtonPress(button: input.Code, callback: () => void) {
        this.interceptedButtons.push({ button, callback });
    }

    /**
     * The Gamepad API behaves differently from keyboard and mouse, as it's not event based.
     * Therefore we need to have a loop to poll the gamepad state
     */
    private initGameLoop(): void {
        if (this.loopRunning) {
            return;
        }
        const loop = () => {
            const gamepad = globalThis.navigator.getGamepads()[0];
            assert(gamepad);

            const currentlyPressedButtons: input.Code[] = [];
            gamepad.buttons.forEach((state, index) => {
                if (!(index in Button)) {
                    return; // If button isn't mapped
                }

                const buttonCode = Button[index];
                this.device.setKey(buttonCode, state.pressed);

                if (state.pressed) {
                    currentlyPressedButtons.push(buttonCode);

                    if (!this.previouslyPressedButtons.includes(buttonCode)) {
                        this.interceptedButtons.forEach(({ button, callback }) => {
                            if (button === buttonCode) {
                                callback();
                            }
                        });
                    }
                }
            });
            this.previouslyPressedButtons = currentlyPressedButtons;

            gamepad.axes.forEach((state, index) => {
                if (!(index in Axis)) {
                    return;
                }
                this.device.setAbs(Axis[index], state);
            });

            this.device.pushStates();
            this.loopRunning = globalThis.requestAnimationFrame(loop);
        };
        loop();
    }

    private stopGameLoop() {
        globalThis.cancelAnimationFrame(this.loopRunning);
        this.loopRunning = 0;
    }
}

const Button = [
    ButtonMap.ButtonA,
    ButtonMap.ButtonB,
    ButtonMap.ButtonX,
    ButtonMap.ButtonY,
    ButtonMap.ButtonL1,
    ButtonMap.ButtonR1,
    ButtonMap.ButtonL2,
    ButtonMap.ButtonR2,
    ButtonMap.ButtonSelect,
    ButtonMap.ButtonStart,
    ButtonMap.ButtonL3,
    ButtonMap.ButtonR3,
    ButtonMap.ButtonDpadUp,
    ButtonMap.ButtonDpadDown,
    ButtonMap.ButtonDpadLeft,
    ButtonMap.ButtonDpadRight,
    ButtonMap.ButtonHome,
];

const Axis = [AxisMap.LeftThumbstickX, AxisMap.LeftThumbstickY, AxisMap.RightThumbstickX, AxisMap.RightThumbstickY];

/**
 * Definition for a button and a callback for when it's pressed by the user
 */
type ButtonInterceptor = {
    button: input.Code;
    callback: () => void;
};
