import type { ResourceEnvelope } from '@ncgt/resource-envelope';
import { useAppQueryParams } from '@gsm-app/hooks/useAppQueryParams';
import { useQuery } from '@tanstack/react-query';

interface Features {
    headless: boolean;
    crashDashboard: boolean;
    testExecutions: boolean;
    testExecutionOcgaUuid: boolean;
    networkReport: boolean;
    copyPasteCharDelay: number;
    networkValidation: boolean;
    controllerBeacon: boolean;
    controllerMagicPath: boolean;
    successfulSessions: boolean;
    authZEnabled: boolean;
    maintenanceMode: boolean;
    adminPageV2: boolean;
    ocgaTargeting: boolean;
    ocgaSoftwarePoolTargeting: boolean;
    viewUserVoice: boolean;
    resourceEnvelope: ResourceEnvelope | null;
    controllerConnectToEditorLink: boolean;
    enableLoadCustomTestbedVersion: boolean;
}

export type FeatureKeys = keyof Features;

export const useFeature = (overrideGameId?: number | undefined) => {
    const { gameId: queryGameId, headless } = useAppQueryParams();
    const params = new URLSearchParams(window.location.search);
    const networkReportId = params.get('networkReport');

    const gameId: number | undefined = overrideGameId ? overrideGameId : queryGameId;
    const { data, isLoading } = useQuery<Features, Error>({
        select: (data) => {
            return data;
        },
        queryKey: ['features', gameId],
        queryFn: () =>
            fetch('/api/features', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ gameId }),
            })
                .then(async (res) => {
                    if (!res.ok) {
                        const text = await res.text();
                        throw new Error(`${res.status} : ${text}`);
                    }
                    return res.json();
                })
                .then((res) => res?.data),
    });
    return {
        isLoading,
        crashDashboard: data?.crashDashboard ?? false,
        testExecutions: data?.testExecutions ?? false,
        testExecutionOcgaUuid: data?.testExecutionOcgaUuid ?? false,
        successfulSessions: data?.successfulSessions ?? false,
        networkValidation: data?.networkValidation ?? false,
        authZEnabled: data?.authZEnabled ?? false,
        maintenanceMode: data?.maintenanceMode ?? false,
        adminPageV2: data?.adminPageV2 ?? false,
        ocgaTargeting: data?.ocgaTargeting ?? false,
        ocgaSoftwarePoolTargeting: data?.ocgaSoftwarePoolTargeting ?? false,
        viewUserVoice: data?.viewUserVoice ?? false,
        resourceEnvelope:
            overrideGameId && (data?.resourceEnvelope as any)?.enabled !== false
                ? (data?.resourceEnvelope ?? null)
                : null,
        controllerBeacon: data?.controllerBeacon ?? false,
        controllerMagicPath: data?.controllerBeacon ?? false,
        controllerConnectToEditorLink: data?.controllerConnectToEditorLink ?? false,
        enableLoadCustomTestbedVersion: data?.enableLoadCustomTestbedVersion ?? false,
        headless,
        networkReport: !!networkReportId,
        copyPasteCharDelay: data?.copyPasteCharDelay ?? 0,
    };
};
