import { useAppQueryParams } from '@gsm-app/hooks/useAppQueryParams';
import { useSopAccounts } from '@gsm-app/providers/SopAccountProvider';
import { useRouteChange } from '@gsm-common/hooks/useRouteChange';
import { Panel, PanelContent, PanelHeader, Text } from '@hawkins/components';
import { Dimensions } from '@hawkins/variables';
import { PlayerBlobContent } from './components/PlayerBlobContent';

interface PlayerBlobModalProps {
    onClose: () => void;
}

export const PlayerBlobModal = ({ onClose }: PlayerBlobModalProps) => {
    const { gameId } = useAppQueryParams();
    const { selectedAccount, isLoading } = useSopAccounts();
    useRouteChange(onClose, 1); // autoclose when the top level route changes

    return (
        <Panel open position='right' maximizable={false} minimizable={false} width={400}>
            <PanelHeader onCloseClick={onClose} title='Player Blobs' />
            <PanelContent>
                <Text colorVariant='faded' level={0} variant='label'>
                    Test Account
                </Text>
                <Text style={{ marginBottom: Dimensions.Space10 }}>{selectedAccount?.value ?? ''}</Text>
                <PlayerBlobContent gameId={gameId} email={selectedAccount?.value} loadingSopAccount={isLoading} />
            </PanelContent>
        </Panel>
    );
};
