import { fetch } from '@gsm-app/utils/fetch';
import { createError } from '@gsm-common/utils/toast/createError';
import { useQuery } from '@tanstack/react-query';
import { useEffect } from 'react';

type PlayerAccessTokenResponse = {
    data: {
        playerAccessToken?: string;
    };
};

const fetchPlayerAccessToken = async (
    gameId: number | undefined,
    email: string | undefined,
): Promise<string | undefined> => {
    if (!gameId || !email) {
        return Promise.resolve(undefined);
    }
    const response = await fetch('/api/access/playerAccessToken', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
        },
        body: JSON.stringify({
            email,
            gameId,
        }),
    });

    if (!response.ok) {
        const errorData = await response.text();
        throw new Error(`Fetch failed with status ${response.status}: ${errorData}`);
    }
    return ((await response.json()) as PlayerAccessTokenResponse)?.data.playerAccessToken;
};

export function usePAT(gameId: number | undefined, email: string | undefined) {
    const query = useQuery({
        queryKey: ['create-player-access-token', gameId, email],
        queryFn: () => fetchPlayerAccessToken(gameId, email),
        enabled: Boolean(gameId && email),
    });

    const {error, isError} = query;

    useEffect(() => {
        if (isError) {
            createError({
                title: 'Error Creating Player Access Token',
                body: `${error?.message}`,
                options: {
                    id: 'create-player-access-token',
                },
            });
        }
    }, [error, isError, createError]);

    return query;
}
