import type { ModalContextValue, Modals } from '@gsm-app/providers/ModalProvider';
import { useCallback, useState } from 'react';

export const useModalData = (): ModalContextValue => {
    const [modal, setModal] = useState<Modals>(undefined);
    const [modalData, setModalData] = useState({});

    const showModal = useCallback((value: Modals, data?: any) => {
        setModalData(data);
        setModal(value);
    }, []);

    return { modal, modalData, showModal };
};
