import { useIdentity } from '@gsm-app/providers/IdentityProvider';
import { ErrorUI } from '@gsm-common/components/Error';
import { Role } from '@ncgt/common/models/identity';
import type { ReactNode } from 'react';
import { Navigate, Outlet } from 'react-router-dom';
import { useFeature } from '@gsm-app/hooks/useFeature';

interface Props {
    roles?: Role[];
    children?: ReactNode;
    redirectUrl?: string;
    redirect?: boolean;
}

export const RolesProtectedRoute = ({ roles = [], children, redirectUrl = '/', redirect = true }: Props) => {
    const { identity } = useIdentity();
    const authorised = roles.length === 0 || roles.some((r) => identity.roles.has(r));
    const hasAdminRole = identity.roles.has(Role.NCGT_ADMIN);
    const { authZEnabled } = useFeature();

    // If the user is not authorized AND (authZ is enabled OR this is an admin route we need to feature gate)
    if (!authorised && (authZEnabled || hasAdminRole)) {
        return redirect ? <Navigate to={redirectUrl} replace /> : <ErrorUI variant='restricted' />;
    }
    return children ? <>{children}</> : <Outlet />;
};
