export function getRandomColor(key: string | undefined) {
    if (!key) {
        return '';
    }
    // Simple hash function (djb2)
    let hash = 5381;
    for (let i = 0; i < key.length; i++) {
        hash = (hash * 33) ^ key.charCodeAt(i);
    }

    // Use bitwise operations to extract RGB components
    const r = (hash >> 16) & 0xff;
    const g = (hash >> 8) & 0xff;
    const b = hash & 0xff;
    return `rgb(${r}, ${g}, ${b})`;
}

