import { type DeepReadonly, isPresent } from '../common/TypeHelpers';
import { defaultConfig } from './config.default';

export type Config = {
    autoConnect: boolean;
    debugLogging: boolean;
    enableGamepad: boolean;
    graphqlEndpoint: string;
    playbackStatusReportBatchedFrames: number;
    reportVideoFrameMetrics: boolean;
    enableDebugView: boolean;
    reconnectionTimeout: number;
    gcpResponseTimeout: number;
    gameStartTimeout: number;
    renderFrameTimeout: number;
    idleWarningTimeout: number;
    idleErrorTimeout: number;
    frozenTimeout: number;
    ocgaDemoMode: boolean;
};

const config = Object.assign({}, defaultConfig);
const encode = (decodedConfig: Partial<Config>): Partial<Config> => {
    const encoded = {
        autoConnect: decodedConfig.autoConnect ?? decodedConfig['autoConnect'],
        debugLogging: decodedConfig.debugLogging ?? decodedConfig['debugLogging'],
        enableGamepad: decodedConfig.enableGamepad ?? decodedConfig['enableGamepad'],
        graphqlEndpoint: decodedConfig.graphqlEndpoint ?? decodedConfig['graphqlEndpoint'],
        playbackStatusReportBatchedFrames:
            decodedConfig.playbackStatusReportBatchedFrames ?? decodedConfig['playbackStatusReportBatchedFrames'],
        reportVideoFrameMetrics: decodedConfig.reportVideoFrameMetrics ?? decodedConfig['reportVideoFrameMetrics'],
        enableDebugView: decodedConfig.enableDebugView ?? decodedConfig['enableDebugView'],
        reconnectionTimeout: decodedConfig.reconnectionTimeout ?? decodedConfig['reconnectionTimeout'],
        gcpResponseTimeout: decodedConfig.gcpResponseTimeout ?? decodedConfig['gcpResponseTimeout'],
        gameStartTimeout: decodedConfig.gameStartTimeout ?? decodedConfig['gameStartTimeout'],
        renderFrameTimeout: decodedConfig.renderFrameTimeout ?? decodedConfig['renderFrameTimeout'],
        idleWarningTimeout: decodedConfig.idleWarningTimeout ?? decodedConfig['idleWarningTimeout'],
        idleErrorTimeout: decodedConfig.idleErrorTimeout ?? decodedConfig['idleErrorTimeout'],
        frozenTimeout: decodedConfig.frozenTimeout ?? decodedConfig['frozenTimeout'],
        ocgaDemoMode: decodedConfig.ocgaDemoMode ?? decodedConfig['ocgaDemoMode'],
    };
    (Object.keys(encoded) as Array<keyof Config>).filter(k => !isPresent(encoded[k])).forEach(k => delete encoded[k]);

    return encoded;
};

export const ConfigManager = {
    parseConfig(configOverrides: Partial<Config>): Config {
        return Object.assign(config, encode(configOverrides));
    },
    getConfig(): DeepReadonly<Config> {
        return config;
    },
};
