import { loggerManager } from '../common';
import { EventEmitter } from '../common/EventEmitter';
import type { ErrorCode } from './ErrorCode';
import { GameError } from './GameError';

export class ErrorReporter extends EventEmitter<ErrorTypeMap> {
    private static instance: ErrorReporter | undefined;

    private constructor() {
        super();
    }

    public static getInstance(): ErrorReporter {
        if (!ErrorReporter.instance) {
            ErrorReporter.instance = new ErrorReporter();
        }
        return ErrorReporter.instance;
    }

    public report(code: ErrorCode, message?: string): void {
        const error = new GameError(code, message);
        loggerManager.getLogger('ErrorReporter').error(error);
        this.emitEvent('error', error);
    }
}

export type ErrorTypeMap = {
    error: GamingClientError;
};

export interface GamingClientError {
    code: ErrorCode;
    message?: string;
    stack?: string;
    failedConnectionApplianceUuids?: string[];
    diagnostics?: {
        stage?: string;
        ocgaUrl?: string;
        ocgaUuid?: string;
        ocgaShortName?: string;
        elapsedMs?: number;
        timeoutMs?: number;
        connectionState?: string;
        iceConnectionState?: string;
        signalingState?: string;
        originalError?: string;
        connectionAttempts?: Array<{ ocga: string; error?: string }>;
    };
}
