import { mockRawIdentity } from '@gsm-app/mocks/mockPlayFixtures';
import { isMockPlayMode } from '@gsm-app/mocks/mockPlayMode';
import { AuthenticationError, auth, initAuth, isAuthzStatus } from '@gsm-app/utils/auth';
import { ErrorUI } from '@gsm-common/components/Error';
import NotificationsHost from '@gsm-common/components/NotificationsHost/NotificationsHost';
import {
    type AuthenticationResponse,
    type MeechumUserData,
    hasSessionExpired,
} from '@hawkins-community/user-authentication';
import { Loader } from '@hawkins/components';
import { Identity, IdentityKind, type RawIdentity, type UserIdentityInstance } from '@ncgt/common/models/identity';
import { useQuery } from '@tanstack/react-query';
import { useTelemetry } from '@ui-paved-road/telemetry/react';
import { type PropsWithChildren, createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react';

/* ------------------ Custom Errors---------------------------------------- */
class IdentityProviderError extends Error {
    constructor(message: string) {
        super(message);
        this.name = this.constructor.name; // Set the error name to the class name
    }
}

/** Error indicating the user's session has expired */
class SessionExpiredError extends IdentityProviderError {
    constructor(message = 'User session has expired.') {
        super(message);
    }
}

type IdentityContextShape = {
    /** Always USER in the browser; null while loading / unauthenticated */
    identity: UserIdentityInstance;
    /** Direct access to the Hawkins SDK singleton (tokens, logout, …) */
    auth: typeof auth;
    /** Convenience wrapper around auth.refreshUser */
    refreshUser: () => Promise<void>;
};

const IdentityCtx = createContext<IdentityContextShape | null>(null);

/* ---------- Public hooks ------------------------------------------------ */

export const useIdentity = () => {
    const ctx = useContext(IdentityCtx);
    if (!ctx) throw new Error('useIdentity must be used within IdentityProvider');
    return ctx;
};

/* ---------- Provider ---------------------------------------------------- */

/**
 * Local-only UI dev mode — skips Hawkins DTA auth and the `/api/identity` fetch entirely (neither is
 * reachable without VPN + a real Netflix backend) and hands the app a fully-permissive fake identity
 * so the Play page shell renders immediately on plain `vite dev`.
 */
const MockIdentityProvider = ({ children }: PropsWithChildren) => {
    const identity = useMemo(() => Identity.create(mockRawIdentity) as UserIdentityInstance, []);
    const contextValue = useMemo<IdentityContextShape>(
        () => ({ identity, auth, refreshUser: async () => {} }),
        [identity],
    );

    return <IdentityCtx.Provider value={contextValue}>{children}</IdentityCtx.Provider>;
};

export const IdentityProvider = ({ children }: PropsWithChildren) => {
    if (isMockPlayMode) {
        return <MockIdentityProvider>{children}</MockIdentityProvider>;
    }
    return <RealIdentityProvider>{children}</RealIdentityProvider>;
};

const RealIdentityProvider = ({ children }: PropsWithChildren) => {
    /* 1.  Ensure Hawkins auth is initialised exactly once  ------------ */
    const [authClient] = useState(() => auth); // singleton
    const [isAuthInitialized, setIsAuthInitialized] = useState(authClient.initialized()); // Initial check
    useEffect(() => {
        if (!authClient.initialized()) {
            initAuth()
                .then(() => {
                    setIsAuthInitialized(true); // Trigger re-render
                })
                .catch(console.error);
        }
    }, [authClient]);

    /* 2.  Keep the user session fresh -------------------- */
    type MeechumResp = AuthenticationResponse<MeechumUserData>;

    const {
        data: meechumUser,
        isLoading: authLoading,
        error: authError,
        refetch: refetchMeechumUser,
    } = useQuery<MeechumResp, Error, MeechumUserData, ['meechum-user']>({
        queryKey: ['meechum-user'],
        enabled: isAuthInitialized,
        queryFn: () => authClient.getOrRefreshUser<MeechumUserData>(),
        select: (res) => res.user,
        staleTime: 60_000,
        retry: 1,
    });

    /* 3.  Fetch NCGT domain identity once authClient is ready ------------------- */
    type IdentityApiRes = { data: RawIdentity };

    const {
        data: rawIdentity,
        isLoading: identLoading,
        error: identError,
        refetch: refetchIdentity,
    } = useQuery<IdentityApiRes, Error, RawIdentity>({
        enabled: !!meechumUser,
        queryKey: ['identity', meechumUser?.userId],
        queryFn: async () => {
            if (hasSessionExpired(authClient)) {
                authClient.triggerLogout();
                throw new SessionExpiredError('Session expired before fetching identity.');
            }
            const res = await fetch('/api/identity');
            if (!res.ok) {
                if (isAuthzStatus(res.status)) {
                    authClient.triggerLogout();
                    throw new AuthenticationError(
                        `Authentication error fetching identity (${res.status}). Session likely expired.`,
                    );
                }
                throw new Error(`Identity API ${res.status}: ${await res.text()}`);
            }
            return await res.json();
        },
        select: (res) => res.data,
        staleTime: 1000 * 60 * 60 * 24, // 24h
        retry: (failureCount, error) => {
            // Don't retry on specific non-recoverable errors
            if (error instanceof SessionExpiredError || error instanceof AuthenticationError) {
                return false;
            }
            return failureCount < 2;
        },
    });

    /* 4.  Derive domain Identity (only USER allowed on the web) -------- */
    const identity = useMemo<UserIdentityInstance | null>(() => {
        if (rawIdentity && rawIdentity.kind === IdentityKind.USER) {
            try {
                return Identity.create(rawIdentity) as UserIdentityInstance;
            } catch (creationError) {
                console.error('Error creating Identity instance:', creationError, rawIdentity);
                return null; // Treat creation error as invalid identity
            }
        }
        return null;
    }, [rawIdentity]);

    /* 5.  Update Telemetry with user info when identity is available */
    const telemetry = useTelemetry();

    useEffect(() => {
        if (identity) {
            telemetry.setUser({
                email: identity?.details.username || '',
                fullName: identity?.details.fullName,
                id: identity?.details.userId,
            });
        }
    }, [identity, telemetry]);

    /* 6.  Define refreshUser callback (call unconditionally) ----------- */
    const refreshUser = useCallback(async () => {
        try {
            console.debug('Attempting to refresh user session...');
            await authClient.refreshUser<MeechumUserData>();
            // Refetch queries after successful session refresh
            await Promise.all([refetchMeechumUser(), refetchIdentity()]);
            console.debug('User session and identity data refetched.');
        } catch (error) {
            console.error('Failed to refresh session:', error);
            // Check session expiry *after* the failed refresh attempt
            if (hasSessionExpired(authClient)) {
                console.warn('Session confirmed expired after refresh attempt. Triggering logout.');
                authClient.triggerLogout();
            }
        }
    }, [authClient, refetchMeechumUser, refetchIdentity]);

    /* 7. Trigger logout as a side effect */
    useEffect(() => {
        if (
            identError instanceof AuthenticationError ||
            identError instanceof SessionExpiredError ||
            authError ||
            hasSessionExpired(authClient)
        ) {
            authClient.triggerLogout();
        }
    }, [identError, authError, authClient]);

    /* 8. Build context value  */
    const contextValue = useMemo<IdentityContextShape | null>(() => {
        if (identity) {
            // Only create the full shape if identity is valid
            return {
                identity,
                auth: authClient,
                refreshUser,
            };
        }
        return null;
    }, [identity, authClient, refreshUser]);

    /* 9.  Render Logic: Loading, Errors, or Children --------------- */
    const isAuthInitializing = !isAuthInitialized;
    const isIdentLoading = !!meechumUser && !identError && identLoading;
    const isLoading = isAuthInitializing || authLoading || isIdentLoading;

    if (isLoading) {
        return <Loader variant='linear' />;
    }

    // --- Error Handling ---
    // check errors BEFORE hasSessionExpired to allow auto-refresh
    if (identError) {
        return <ErrorUI errorMessage={identError.message} variant='restricted' />;
    }

    // Handle authClient query errors (could be SDK errors)
    if (authError) {
        if (hasSessionExpired(authClient)) {
            return <ErrorUI errorMessage={new SessionExpiredError().message} variant='restricted' />;
        }
        return <ErrorUI errorMessage={authError.message} variant='restricted' />;
    }

    // if no errors but session expired, show restricted
    if (hasSessionExpired(authClient)) {
        return <ErrorUI errorMessage={new SessionExpiredError().message} variant='restricted' />;
    }

    // --- Final Validity Check ---
    // This catches cases where loading/errors passed, but identity is still null
    if (!identity || !contextValue) {
        return (
            <ErrorUI
                errorMessage='Your user account could not be loaded correctly. Please try logging in again or contact support.'
                variant='restricted'
            />
        );
    }

    // Render the provider ONLY when identity is valid
    return (
        <IdentityCtx.Provider value={contextValue}>
            <NotificationsHost />
            {children}
        </IdentityCtx.Provider>
    );
};
