import { CHANNELS_QUERY_KEY } from '@gsm-app/hooks/useChannels';
import { GAMES_QUERY_KEY } from '@gsm-app/hooks/useGames';
import { useModalOnClose } from '@gsm-app/hooks/useModalOnClose';
import { useGameChannels } from '@gsm-app/routes/Play/hooks/useGameChannels';
import { fetch } from '@gsm-app/utils/fetch';
import { FileUploader, UploadState } from '@gsm-app/utils/uploadFile';
import { Input } from '@gsm-common/components/Input';
import { keyFromOptions } from '@gsm-common/utils/dropdown/keyFromOptions';
import { formatBytes } from '@gsm-common/utils/file/formatBytes';
import { createError } from '@gsm-common/utils/toast/createError';
import { createSuccess } from '@gsm-common/utils/toast/createSuccess';
import { createWarning } from '@gsm-common/utils/toast/createWarning';
import { IconCircleExclamationPoint } from '@hawkins/assets';
import {
    Button,
    ButtonGroup,
    Card,
    CardBody,
    Checkbox,
    CheckboxGroup,
    Dropdown,
    type DropdownOption,
    Heading,
    Loader,
    Modal,
    ModalBody,
    ModalFooter,
    ModalHeader,
    Stack,
    Text,
    Tooltip,
    getFuzzyFilterOption,
} from '@hawkins/components';
import { Dimensions } from '@hawkins/variables';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { type ChangeEvent, useCallback, useEffect, useRef, useState } from 'react';
import { useTelemetry } from '@ui-paved-road/telemetry/react';
import { useDisplayUploadStateErrors } from './useDisplayUploadStateErrors';
import { useFullStory } from '@gsm-app/hooks/useFullStory';

interface UploadBuildModalProps {
    onClose: () => void;
}

interface BuildStateError {
    status?: number;
    code?: string;
    title: string;
    detail: string;
    meta?: Record<string, unknown>;
}

type FileStatus = 'READY' | 'ERROR' | 'UPLOADING' | 'FILE_SELECTED' | 'COMPLETED' | 'INSTALLING';

enum TestSuite {
    OcgaPerf = 'ocgaperf',
}

const BUILD_STATE_POLL_INTERVAL_MS = 2000;
const GZIP_MAGIC_BYTE_1 = 0x1f;
const GZIP_MAGIC_BYTE_2 = 0x8b;
const MIN_FILE_SIZE_BYTES = 2;
const MAX_LABEL_LENGTH = 50;
const PROGRESS_COMPLETE_THRESHOLD = 100;

export const UploadBuildModal = ({ onClose }: UploadBuildModalProps) => {
    const filterGameDev = true;
    const {
        gameOptions,
        channelOptions,
        areChannelsFetching,
        selectedGame,
        selectedChannel,
        setSelectedGame,
        setSelectedChannel,
    } = useGameChannels(filterGameDev);
    const [label, setLabel] = useState('');
    const [selectedFile, setSelectedFile] = useState<File>();
    const [fileError, setFileError] = useState('');
    const [progressValue, setProgressValue] = useState(0);
    const [uploadStatus, setUploadStatus] = useState<FileStatus>('READY');
    const [pollUrl, setPollUrl] = useState<string>();
    const { showErrors } = useDisplayUploadStateErrors();
    const { trackEvent } = useFullStory();
    const telemetry = useTelemetry();

    const handleBuildUploadError = useCallback(
        (resBuild: {
            errors?: BuildStateError[];
            message?: string;
            title?: string;
            reqId?: string;
        }) => {
            if (resBuild.errors) {
                resBuild.errors.forEach((error: BuildStateError) => {
                    const errorMessage = error.detail || error.title || 'Upload Failed';
                    telemetry.trackError(new Error(errorMessage), {
                        tags: {
                            action: 'build-upload',
                            gameId: selectedGame?.value || '',
                            channel: selectedChannel?.label || '',
                            label,
                            code: error.code,
                            status: error.status,
                        },
                    });
                    createError({
                        title: error.title || 'Upload Failed',
                        body: error.detail,
                    });
                });
            } else {
                const errorMessage = resBuild.message || resBuild.title || 'Upload Failed';
                telemetry.trackError(new Error(errorMessage), {
                    tags: {
                        action: 'build-upload',
                        gameId: selectedGame?.value || '',
                        channel: selectedChannel?.label || '',
                        label,
                    },
                });
                createError({
                    title: resBuild.title || 'Upload Failed',
                    body: (
                        <>
                            <Text>{resBuild.message}</Text>
                            {resBuild.reqId && <Text>{`reqId: ${resBuild.reqId}`}</Text>}
                        </>
                    ),
                });
            }
        },
        [telemetry, selectedGame, selectedChannel, label],
    );

    const handleUploadResultError = useCallback(
        (uploadResult: { state?: string; error?: { message?: string } } | undefined) => {
            if (uploadResult?.state === UploadState.UPLOAD_CANCELED) {
                createWarning({
                    title: 'Upload Canceled',
                    options: {
                        duration: 2000,
                        id: 'upload-game-canceled',
                    },
                });
                return;
            }

            const errorMessage = uploadResult?.error?.message || 'Upload Failed';
            telemetry.trackError(new Error(errorMessage), {
                tags: {
                    action: 'build-upload',
                    gameId: selectedGame?.value || '',
                    channel: selectedChannel?.label || '',
                    label,
                    state: uploadResult?.state || '',
                },
            });
            createError({
                title: 'Upload Failed',
                body: errorMessage,
                options: {
                    id: 'upload-game-failed',
                },
            });
        },
        [telemetry, selectedGame, selectedChannel, label],
    );

    const { data: pollData, error: pollError } = useQuery<{
        data?: {
            errors?: BuildStateError[];
            attributes: {
                state: string;
            };
        };
        errors?: BuildStateError[];
    }>({
        refetchInterval: BUILD_STATE_POLL_INTERVAL_MS,
        enabled: pollUrl !== undefined,
        queryKey: ['build-state', pollUrl],
        queryFn: async () => {
            if (!pollUrl) {
                return undefined;
            }
            return await fetch(pollUrl).then((res) => res.json());
        },
    });
    const [tests, setTests] = useState<string[]>([]);

    const fileUploader = useRef<FileUploader | null>(null);
    if (!fileUploader.current) {
        fileUploader.current = new FileUploader();
    }

    const queryClient = useQueryClient();

    const refreshGamesAndChannels = useCallback(() => {
        queryClient.invalidateQueries({ queryKey: [GAMES_QUERY_KEY] });
        queryClient.invalidateQueries({ queryKey: [CHANNELS_QUERY_KEY, selectedGame?.value] });
    }, [queryClient, selectedGame]);

    useEffect(() => {
        if (pollData) {
            if (pollData.errors) {
                showErrors(pollData.errors);

                createError({
                    title: 'Install Game Failed',
                    options: {
                        id: 'install-game-failed',
                    },
                });
                setPollUrl(undefined);
                onClose();
            } else if (pollData.data?.attributes?.state === 'install_succeed') {
                // Show warnings if present
                if (pollData.data?.errors) {
                    showErrors(pollData.data?.errors);
                }

                createSuccess({
                    title: 'Install Game Succeeded',
                    options: {
                        id: 'install-game-succeeded',
                    },
                });
                refreshGamesAndChannels();
                setPollUrl(undefined);
                onClose();
            }
        }
    }, [pollData, refreshGamesAndChannels, onClose, showErrors]);

    useEffect(() => {
        if (pollError) {
            telemetry.trackError(pollError, {
                tags: {
                    action: 'build-install',
                    gameId: selectedGame?.value,
                    channel: selectedChannel?.label,
                    label: label,
                },
            });
            createError({
                title: 'Failed to get build upload status',
                body: pollError.message,
                options: {
                    id: 'build-state-poll-error',
                },
            });
            setPollUrl(undefined);
            onClose();
        }
    }, [pollError, telemetry, selectedGame, selectedChannel, label, onClose]);

    const handleCancel = async () => {
        if (uploadStatus === 'UPLOADING') {
            fileUploader.current?.cancel();
        }
        onClose();
    };

    const validateTarGzFile = async (file: File): Promise<boolean> => {
        const fileName = file.name.toLowerCase();
        const isValidExtension = fileName.endsWith('.tar.gz') || fileName.endsWith('.tgz') || fileName.endsWith('.gz');

        if (!isValidExtension) {
            setFileError('File must have a .tar.gz, .tgz, or .gz extension');
            return false;
        }

        // check if file is actually a gzip (gzip files start with magic bytes 0x1f 0x8b)
        return new Promise((resolve) => {
            const reader = new FileReader();
            reader.onload = (e) => {
                const arrayBuffer = e.target?.result as ArrayBuffer;
                if (!arrayBuffer || arrayBuffer.byteLength < MIN_FILE_SIZE_BYTES) {
                    setFileError('File is too small or could not be read');
                    resolve(false);
                    return;
                }

                const bytes = new Uint8Array(arrayBuffer);
                const isGzip = bytes[0] === GZIP_MAGIC_BYTE_1 && bytes[1] === GZIP_MAGIC_BYTE_2;

                if (!isGzip) {
                    setFileError('File is not a valid tar.gz file. Expected gzip format (magic bytes 0x1f 0x8b)');
                    resolve(false);
                    return;
                }

                setFileError('');
                resolve(true);
            };
            reader.onerror = () => {
                setFileError('Error reading file, please try again');
                resolve(false);
            };
            // read only first 2 bytes to check magic bytes
            reader.readAsArrayBuffer(file.slice(0, 2));
        });
    };

    const changeHandler = async (event: ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (!file) {
            setSelectedFile(undefined);
            setFileError('');
            setUploadStatus('READY');
            return;
        }

        setFileError('');
        const isValid = await validateTarGzFile(file);

        if (isValid) {
            setSelectedFile(file);
            setUploadStatus('FILE_SELECTED');
        } else {
            setSelectedFile(undefined);
            setUploadStatus('ERROR');
        }
    };
    const handleSubmission = async () => {
        if (!selectedGame || !selectedChannel || !selectedFile) {
            return;
        }
        try {
            setUploadStatus('UPLOADING');
            const fileName = selectedFile.name;

            trackEvent('Upload Game', {
                game: selectedGame.value,
                channel: selectedChannel.label,
                label,
                diff_upload: false,
                tests: tests.join(','),
            });

            // Build Upload
            const resBuild = await fetch(`/api/games/${selectedGame.value}/builds`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    channelName: selectedChannel.label,
                    label,
                    size: selectedFile.size,
                    storageStrategy: 'single', // upload a single tar
                    fileName: fileName,
                }),
            }).then((res) => res.json());

            // Process errors if there's no data
            if (!resBuild.data) {
                handleBuildUploadError(resBuild);
                onClose();
                return;
            }

            interface BuildData {
                type: string;
                key: string;
                attributes: {
                    uploadUrl: string;
                    path: string;
                };
            }
            const {
                data: {
                    key: buildKey,
                    attributes: { uploadUrl: buildUploadUrl },
                },
            } = resBuild as { data: BuildData };
            const gameBuildBaseUrl = `/api/games/${selectedGame.value}/builds/${buildKey}`;

            const uploadResult = await fileUploader.current?.upload(buildUploadUrl, selectedFile, {
                updateProgressCallback: (p: number) => setProgressValue(() => p),
                onStart: async () => {
                    return await fetch(`${gameBuildBaseUrl}/upload-state`, {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json',
                        },
                        body: JSON.stringify({
                            state: UploadState.UPLOAD_PROGRESS,
                        }),
                    });
                },
            });

            await fetch(`${gameBuildBaseUrl}/upload-state`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    state: uploadResult?.state,
                    error: uploadResult?.error,
                }),
            });

            if (uploadResult?.state !== UploadState.UPLOAD_SUCCEED) {
                handleUploadResultError(uploadResult);
                onClose();
                return;
            }

            // Build Install
            setUploadStatus('INSTALLING');
            const installResponse = await fetch(`${gameBuildBaseUrl}/install`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    gameName: selectedGame.label,
                    channelName: selectedChannel.label,
                    tests,
                }),
            });

            const installData = await installResponse.json();

            if (!installResponse.ok) {
                const errorMessage = installData.message || 'Build install failed';
                telemetry.trackError(new Error(errorMessage), {
                    tags: {
                        action: 'build-install',
                        gameId: selectedGame.value,
                        channel: selectedChannel.label,
                        label: label,
                    },
                });
                createError({
                    title: 'Build Install Failed',
                    body: errorMessage,
                    options: {
                        id: 'build-install-failed',
                    },
                });
                onClose();
                return;
            }

            setPollUrl(`${gameBuildBaseUrl}/state`);
        } catch (e) {
            setUploadStatus('ERROR');

            const error = e instanceof Error ? e : new Error(String(e));
            const errorMessage = error.message || 'Unknown error during upload';
            telemetry.trackError(new Error(errorMessage), {
                tags: {
                    action: 'build-upload',
                    gameId: selectedGame.value,
                    channel: selectedChannel.label,
                    label: label,
                },
            });

            createError({
                title: 'Upload Build Error',
                body: errorMessage,
                options: {
                    id: 'upload-build-error',
                },
            });

            onClose();
        }
    };

    const isFileReadyForUpload = Boolean(
        selectedFile && selectedGame && selectedChannel && label.length > 0 && !fileError,
    );
    const isFileChangeDisabled = Boolean(
        uploadStatus === 'UPLOADING' || uploadStatus === 'COMPLETED' || uploadStatus === 'INSTALLING',
    );
    const isFileCancelDisabled = Boolean(uploadStatus === 'COMPLETED' || uploadStatus === 'INSTALLING');

    const handleOnClose = useModalOnClose({ onClose });

    return (
        <Modal open style={{ width: '600px' }} maxWidth='medium' onClose={handleOnClose}>
            <ModalHeader>
                <Heading level={0}>Upload Build</Heading>
            </ModalHeader>
            <ModalBody>
                <Stack gap={5}>
                    <Dropdown
                        label='Game'
                        requirementType='required-star'
                        onChange={(selected: DropdownOption<string> | null) => {
                            if (selected) {
                                setSelectedGame(selected);
                            }
                        }}
                        options={gameOptions}
                        loading={gameOptions.length === 0}
                        value={selectedGame}
                        getOptionValue={(option) => {
                            if (typeof option === 'string') {
                                return option;
                            }
                            return option.value;
                        }}
                        searchable={gameOptions.length > 5}
                        clearSearchOnSelect
                        filterOptions={getFuzzyFilterOption(gameOptions, {
                            keys: ['label', 'subtitle'],
                            ignoreLocation: true,
                        })}
                        key={`games-${keyFromOptions(gameOptions)}`}
                        disabled={isFileChangeDisabled}
                    />
                    <Dropdown
                        label='Channel'
                        requirementType='required-star'
                        startAdornment={areChannelsFetching && <Loader size={Dimensions.Size24} />}
                        groupBy={(option) => option.group ?? ''}
                        onChange={(selected: DropdownOption<string> | null) => {
                            if (selected) {
                                setSelectedChannel(selected);
                            }
                        }}
                        options={channelOptions}
                        loading={gameOptions.length === 0}
                        value={selectedChannel ?? channelOptions[0]}
                        searchable={channelOptions.length > 5}
                        filterOptions={getFuzzyFilterOption(channelOptions, { ignoreLocation: true })}
                        key={`channels-${keyFromOptions(channelOptions)}`}
                        disabled={isFileChangeDisabled || areChannelsFetching}
                    />
                    <Input
                        label='Label'
                        requirementType='required-star'
                        placeholder='Insert a label for the build'
                        value={label}
                        onChange={(e) => setLabel(e.target.value)}
                        disabled={isFileChangeDisabled}
                        inputProps={{
                            pattern: /^[A-Za-z0-9\-_.]+$/,
                            autoComplete: 'off',
                            max: MAX_LABEL_LENGTH,
                        }}
                    />
                    <Text variant='label' bold gutterBottom='5px' level={1}>
                        Choose the game file to upload
                    </Text>
                    <Stack gap={5}>
                        {!isFileChangeDisabled && (
                            <div style={{ position: 'relative' }}>
                                <Input
                                    type='file'
                                    inputProps={{ accept: '.tar.gz,.tgz,.gz' }}
                                    onChange={(e: ChangeEvent<HTMLInputElement>) => changeHandler(e)}
                                />
                                {fileError && (
                                    <Text
                                        variant='body'
                                        gutterTop={Dimensions.Space2}
                                        level={0}
                                        color='red'
                                    >
                                        {fileError}
                                    </Text>
                                )}
                                {selectedFile && !fileError && (
                                    <Tooltip
                                        label={['Filename', 'Filetype', 'Size']}
                                        description={[
                                            selectedFile.name,
                                            selectedFile.type,
                                            formatBytes(selectedFile.size),
                                        ]}
                                    >
                                        <Button
                                            variant='icon'
                                            icon={IconCircleExclamationPoint}
                                            style={{ position: 'absolute', right: 0, top: 0 }}
                                            aria-label='file info'
                                        />
                                    </Tooltip>
                                )}
                            </div>
                        )}
                        {isFileChangeDisabled && (
                            <Card>
                                <CardBody>
                                    <Stack style={{ gridAutoFlow: 'column', justifyContent: 'space-between' }}>
                                        <Text variant='body' level={0}>
                                            {uploadStatus}
                                        </Text>
                                        {uploadStatus === 'UPLOADING' && (
                                            <Text variant='body' level={0}>
                                                {`${progressValue}%`}
                                            </Text>
                                        )}
                                    </Stack>
                                    <Stack gap={10}>
                                        <Text variant='body' colorVariant='faded' level={0}>
                                            {selectedFile?.name}
                                        </Text>
                                        <Loader
                                            variant='linear'
                                            state={
                                                progressValue >= PROGRESS_COMPLETE_THRESHOLD
                                                    ? 'indeterminate'
                                                    : 'determinate'
                                            }
                                            value={progressValue}
                                        />
                                    </Stack>
                                </CardBody>
                            </Card>
                        )}
                    </Stack>
                    <CheckboxGroup
                        label='Test Suite'
                        description='Select the appropriate tests to be executed for the build'
                        disabled={isFileChangeDisabled}
                        onChange={(newValue) => {
                            setTests(newValue);
                        }}
                        value={tests}
                    >
                        <Checkbox label='OCGA Performance' value={TestSuite.OcgaPerf} />
                    </CheckboxGroup>
                </Stack>
            </ModalBody>
            <ModalFooter>
                <ButtonGroup justifyContent='flex-end'>
                    <Button variant='secondary' onClick={handleCancel} disabled={isFileCancelDisabled}>
                        Cancel
                    </Button>
                    <Button onClick={handleSubmission} disabled={!isFileReadyForUpload || isFileChangeDisabled}>
                        Upload
                    </Button>
                </ButtonGroup>
            </ModalFooter>
        </Modal>
    );
};
