import { ModalContainer } from '@gsm-app/components/ModalContainer';
import { useDevToolsData } from '@gsm-app/hooks/useDevToolsData';
import { useModalData } from '@gsm-app/hooks/useModalData';
import { useSopAccountData } from '@gsm-app/hooks/useSopAccountData';
import { DevToolsProvider } from '@gsm-app/providers/DevToolsProvider';
import { ModalProvider } from '@gsm-app/providers/ModalProvider';
import { SopAccountProvider } from '@gsm-app/providers/SopAccountProvider';
import { Layout } from '@gsm-common/components/Layout';
import { FeedbackProvider } from '@hawkins/components';
import { Outlet } from 'react-router-dom';
import { AppMenu } from '../AppMenu';
import { DevTools } from '../DevTools';

export const AppLayout = () => {
    const isPopout = window.opener !== null;

    return (
        <Layout full horizontal>
            <FeedbackProvider anchorOrigin={{ vertical: 'top', horizontal: 'center' }}>
                <ModalProvider value={useModalData()}>
                    <SopAccountProvider value={useSopAccountData()}>
                        <DevToolsProvider value={useDevToolsData()}>
                            {!isPopout && <AppMenu />}
                            <DevTools />
                            <Outlet />
                            <ModalContainer />
                        </DevToolsProvider>
                    </SopAccountProvider>
                </ModalProvider>
            </FeedbackProvider>
        </Layout>
    );
};
