import { MOCK_SOP_ACCOUNT } from '@gsm-app/mocks/mockPlayFixtures';
import { isMockPlayMode } from '@gsm-app/mocks/mockPlayMode';
import type { SopAccountContextValue, SopAccountType } from '@gsm-app/providers/SopAccountProvider';
import type { GameParams } from '@gsm-app/routes/Play/hooks/useGameChannels';
import { useSearchParams } from '@gsm-common/hooks/useSearchParams';
import { useCallback, useEffect, useRef, useState } from 'react';
import { decrypt, encrypt } from '../utils/encrypt';
import { useSecretKey } from './useSecretKey';

const SAVED_ACCOUNTS_KEY = 'ncgt_savedAccounts';
const SELECTED_ACCOUNT_KEY = 'ncgt_selectedAccount';

export type Account = { email: string; pin: string };

const saveEncryptedAccounts = async (secretKey: string, accounts: SopAccountType[]) => {
    const encryptedAccounts = await encrypt(
        secretKey,
        JSON.stringify(
            accounts.map<Account>((sop) => {
                return {
                    email: sop.value,
                    pin: sop.pin,
                };
            }),
        ),
    );
    localStorage.setItem(SAVED_ACCOUNTS_KEY, encryptedAccounts);
};

const getDecryptedAccounts = async (secretKey: string) => {
    const encryptedAccounts = localStorage.getItem(SAVED_ACCOUNTS_KEY);
    let accounts: Account[] = [];

    if (encryptedAccounts) {
        try {
            const decryptedAccounts = await decrypt(secretKey, encryptedAccounts);
            const parsed = JSON.parse(decryptedAccounts);
            if (Array.isArray(parsed)) {
                accounts = parsed.filter((sop) => Boolean(sop.email && sop.pin));
            }
        } catch (e) {
            console.log('NO SAVED ACCOUNTS');
            saveEncryptedAccounts(secretKey, []);
        }
    }

    return accounts;
};

/** Local-only UI dev mode — skips the secret-key fetch + localStorage decrypt flow and pre-selects a
 * fake test account, since `useGamingClientMonitor` requires one before it will "start" the mock
 * session. */
const useMockSopAccountData = (): SopAccountContextValue => {
    const [savedAccounts, setSavedAccounts] = useState<SopAccountType[]>([MOCK_SOP_ACCOUNT]);
    const [selectedAccount, setSelectedAccount] = useState<SopAccountType | undefined>(MOCK_SOP_ACCOUNT);

    return { savedAccounts, setSavedAccounts, selectedAccount, setSelectedAccount, isLoading: false };
};

export const useSopAccountData = (): SopAccountContextValue => {
    if (isMockPlayMode) {
        return useMockSopAccountData();
    }
    return useRealSopAccountData();
};

const useRealSopAccountData = (): SopAccountContextValue => {
    const [{ encryptedAccount }] = useSearchParams<GameParams>();
    const state = useRef<Omit<SopAccountContextValue, 'setSavedAccounts' | 'setSelectedAccount' | 'isLoading'> | null>(
        null,
    );
    const [id, setId] = useState<number>(0);

    const triggerRerender = () => setId(new Date().getTime());

    const { secretKey, isLoading, isFetched } = useSecretKey();

    useEffect(() => {
        // wait for secret
        if (!secretKey) {
            return;
        }

        const load = async () => {
            let selectedAccount: SopAccountType | undefined;
            let savedAccounts: SopAccountType[] = [];

            // Decrypt the account data from the URL if available
            if (encryptedAccount) {
                try {
                    const decryptedAccountData = await decrypt(secretKey, encryptedAccount);
                    const decryptedAccount = JSON.parse(decryptedAccountData);

                    selectedAccount = {
                        label: decryptedAccount.email,
                        value: decryptedAccount.email,
                        pin: decryptedAccount.pin,
                    };
                    savedAccounts = [selectedAccount];
                } catch (e) {
                    console.error('Failed to decrypt account data from URL:', e);
                }
            } else {
                const accounts = await getDecryptedAccounts(secretKey);
                savedAccounts = accounts.map((sop): SopAccountType => {
                    return {
                        label: sop.email,
                        value: sop.email,
                        pin: sop.pin,
                    };
                });

                const selected = localStorage.getItem(SELECTED_ACCOUNT_KEY) ?? '';
                selectedAccount = savedAccounts.find((sop: SopAccountType) => sop.value === selected);
            }

            state.current = {
                savedAccounts,
                selectedAccount,
            };
            triggerRerender();
        };

        if (!state.current) {
            load();
        }
    }, [encryptedAccount, state, secretKey]);

    const setSavedAccounts = useCallback(
        (savedAccounts: SopAccountType[]) => {
            if (state.current) {
                state.current.savedAccounts = savedAccounts;
                triggerRerender();
                saveEncryptedAccounts(secretKey, savedAccounts);
            }
        },
        [state, secretKey],
    );

    const setSelectedAccount = useCallback(
        (selectedAccount: SopAccountType | undefined) => {
            if (state.current) {
                state.current.selectedAccount = selectedAccount;
                if (selectedAccount) {
                    localStorage.setItem(SELECTED_ACCOUNT_KEY, selectedAccount.value);
                } else {
                    localStorage.removeItem(SELECTED_ACCOUNT_KEY);
                }
                triggerRerender();
            }
        },
        [state],
    );

    return {
        savedAccounts: state.current?.savedAccounts ?? [],
        selectedAccount: state.current?.selectedAccount ?? undefined,
        setSavedAccounts,
        setSelectedAccount,
        isLoading: (isLoading && !isFetched) || !id,
    };
};
