import { useDevToolsProvider } from '@gsm-app/providers/DevToolsProvider';
import { Panel } from '@hawkins/components';
import * as React from 'react';
import styles from './DevTools.module.css';

const ReactQueryDevtoolsPanelProduction = React.lazy(() =>
    import('@tanstack/react-query-devtools/build/modern/production.js').then(
      (d) => ({
        default: d.ReactQueryDevtoolsPanel,
      }),
    ),
  )

export const DevTools = () => {
    const devMode = process.env.NODE_ENV === 'development';
    const { open, toggleDevTools } = useDevToolsProvider();
    return devMode ? 
        (
            <Panel open={open}  position="right" width={600}>
                <Panel.Header onCloseClick={toggleDevTools} />
                <Panel.Content className={styles.panelContent}>
                    <React.Suspense fallback={null}>
                        <ReactQueryDevtoolsPanelProduction
                          style={{
                            height: '100%'
                          }}
                          onClose={toggleDevTools}
                        />
                    </React.Suspense>
                </Panel.Content>
            </Panel>
        ) : null;
};
