import { fetch } from '@gsm-app/utils/fetch';
import { useQuery } from '@tanstack/react-query';
import { useEffect } from 'react';

// Alerts are prioritized to be more prominent
export type NotificationType = 'TOASTER' | 'MODAL' | 'SIDEBAR' | 'BANNER' | undefined;
export type NotificationVariant = 'REGULAR' | 'ERROR' | 'SUCCESS' | 'WARNING' | undefined;
export type NotificationPersistence = 'TRANSIENT' | 'PERMANENT' | 'CLEARABLE' | undefined;

export type PlatformType = 'ncgtportal' | 'ncgt-cli';

export interface NotificationTarget {
    platform?: PlatformType;
    partner?: string;
    version?: string;
}

export type Notification = {
    uuid: string;
    createdDate?: string;
    createdBy?: string;
    updatedBy?: string;
    startDate?: string;
    endDate?: string;
    title: string;
    markup: string;
    type: NotificationType;
    variant: NotificationVariant;
    persistence?: NotificationPersistence;
    target?: NotificationTarget;
};

const fetchNotifications = async (all?: boolean): Promise<Notification[] | undefined> => {
    const url = all ? '/api/notifications?all=true' : '/api/notifications';
    const response = await fetch(url, {
        headers: {
            'Content-Type': 'application/json',
        },
    });

    if (!response.ok) {
        const errorData = await response.text();
        throw new Error(`Fetch failed with status ${response.status}: ${errorData}`);
    }
    return response.json() as Promise<Notification[]>;
};

interface UseNotificationsOptions {
    all?: boolean;
}

export function useNotifications(options?: UseNotificationsOptions) {
    const { all } = options ?? {};
    const query = useQuery({
        queryKey: ['notifications', { all }],
        queryFn: () => fetchNotifications(all),
    });

    const {error, isError} = query;
    useEffect(() => {
        if (isError) {
            console.error(`Error getting notifications. ${error?.message}`);
        }
    }, [error, isError]);

    const notifications = query.data || [];

    return {
        ...query,
        notifications,
    };
}
