import { App } from '@gsm-app/components/App';
import { mockFetch } from '@gsm-app/mocks/mockFetchHandlers';
import { isMockPlayMode } from '@gsm-app/mocks/mockPlayMode';
import { routeCleanup } from '@gsm-app/utils/route';
import '@hawkins/components/lib/css/allHawkinsStyles.css';
import '@hawkins/table/lib/css/hawkins-dark.css';
import '@hawkins/table/lib/css/hawkins-light.css';
import '@inovua/reactdatagrid-enterprise/base.css';
import { ErrorBoundary } from '@gsm-common/components/Error';
import { HawkinsProvider } from '@hawkins/components';
import { TelemetryClient } from '@ui-paved-road/telemetry';
import { FullStoryIntegration } from '@ui-paved-road/telemetry/fullstory';
import { TelemetryProvider } from '@ui-paved-road/telemetry/react';
import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';

// remove the old branchName before app bootstraps
routeCleanup();

// Local-only UI dev mode (VITE_MOCK_PLAY=true) — patch the one global `fetch` reference so every
// plain `fetch('/api/...')` call site (useFeature, useSecretKey, usePassport, etc.) gets fixture
// data too, without needing its own mock branch. `utils/fetch.ts`'s authed wrapper short-circuits to
// the same fixtures separately, since it never reaches this global (it calls Hawkins auth first).
if (isMockPlayMode) {
    window.fetch = mockFetch as typeof window.fetch;
}

const ORG_ID = 'o-20VE6D-na1';
const APP_NAME = 'needlecast_dta_ocga_part_server_client';

const fullstoryIntegration = new FullStoryIntegration({ orgId: ORG_ID });
const telemetryClient = new TelemetryClient({
    app: APP_NAME,
    integrations: [fullstoryIntegration],
});

const app = document.getElementById('app');
const root = createRoot(app!);

root.render(
    <StrictMode>
        <HawkinsProvider theme={localStorage.getItem('theme') === 'light' ? 'light' : 'dark'}>
            <TelemetryProvider client={telemetryClient}>
                <ErrorBoundary>
                    <App />
                </ErrorBoundary>
            </TelemetryProvider>
        </HawkinsProvider>
    </StrictMode>,
);
